local config = {
  ui_story_5040_50400101_1_dialog_content = "(휴... 오랜만에 쉬는 날인데...)",
  ui_story_5040_50400101_2_dialog_content = "(...아니지, 그래도 기운 내야지!)",
  ui_story_5040_50400101_3_dialog_content = "「삐빅, <color=#FFB400>관월제</color>까지 3일 남았습니다.」",
  ui_story_5040_50400101_4_dialog_content = "「관월제는 연인들이 서로의 마음을 전하는 아스트라의 전통 기념일로,\n결혼식을 올리기에도 좋은 날입니다.」",
  ui_story_5040_50400101_5_dialog_content = "알고 있다니까! 작년에 너무 바빠서 관월제를 잊어버리지만 않았어도, 지금 이렇게...",
  ui_story_5040_50400101_6_dialog_content = "아무튼...! 바이스랑 카렌이 마음에 들어 했던 턴테이블을 사서 깜짝 놀래켜 줘야지!",
  ui_story_5040_50400101_7_dialog_content = "(그러고 보니까 둘도 쉬는 날일 텐데, 어디 간 거지? 뭐, 됐어. 나 혼자 노력해 보자!)",
  ui_story_5040_50400101_8_dialog_content = "PlayerName 님이 절 찾아오시다니 신기하네요. 무슨 일 있으신가요?",
  ui_story_5040_50400101_9_dialog_content = "죄송해요. 공휴일 전은 성수기라 지금은 이야기를 나눌 시간이 많지 않아요.",
  ui_story_5040_50400101_10_dialog_content = "게다가 레디젤 렌치 지부 쪽 동료가 백야성으로 보내는\n대량의 우편물을 어지럽혀 놨거든요...",
  ui_story_5040_50400101_11_dialog_content = "그래? 내가 도와줄 수 있는 건 없을까?",
  ui_story_5040_50400101_12_dialog_content = "관월제 때 사고 싶은 게 있거든. 그래서 돈을 좀 벌려고 의뢰를 받는 중이야.",
  ui_story_5040_50400101_13_dialog_content = "예전에도 트위티가 신세를 졌으니까, 수고를 끼치고 싶진 않은걸요...",
  ui_story_5040_50400101_14_dialog_content = "그래도 그렇게 말씀해 주신다면야, 확실히 부탁드릴 일이 있긴 해요.\n아무래도 레디젤 렌치 지부에 한번 가 주셔야 할 것 같네요.",
  ui_story_5040_50400101_15_dialog_content = "북방에 사는 제 오랜 친구가 결혼식을 올리거든요.\n날짜는 다른 많은 연인들처럼 관월제 날에 잡았고요.",
  ui_story_5040_50400101_16_dialog_content = "하지만 약혼녀가 얼마 전 레디젤 사막에서 조금 다쳤거든요.\n몸조리를 기다리면 북방에서 올리는 결혼식에 늦을 거예요.",
  ui_story_5040_50400101_17_dialog_content = "아, 콜로서스로 태워주면 되는 거야? 그거면 쉽지.",
  ui_story_5040_50400101_18_dialog_content = "(...그것보다 나로세르는 친구 결혼식인데 참석 안 하는 건가?)",
  ui_story_5040_50400101_19_dialog_content = "(뭐, 자세한 건 도착해서 당사자한테 물어보자... 여기가 레디젤 렌치 지부인가?)",
  ui_story_5040_50400101_20_dialog_content = "<color=#e8d9bb>똑똑──</color>",
  ui_story_5040_50400101_21_dialog_content = "저기...",
  ui_story_5040_50400101_22_dialog_content = "특별히 도와주러 온 아이테르 군이지? 한참 기다렸어~",
  ui_story_5040_50400101_23_dialog_content = "아이테르의 콜로서스는 빠르다고 나로세르한테 자주 들어서, 더 빨리 올 줄 알았는데 말이야.",
  ui_story_5040_50400101_X23_dialog_content = "(어, 엄청 큰 뱀이잖아?! 이것도 쿠리어의 언령인가? 대단하네...)",
  ui_story_5040_50400101_X24_dialog_content = "(그리고 이 사무실... 뭐랄까, 너무 정교해서 전혀 레디젤 렌치 스타일 같지가 않잖아.)",
  ui_story_5040_50400101_24_dialog_content = "(이 사무실... 뭐랄까, 너무 정교해서 전혀 레디젤 렌치 스타일 같지가 않잖아.)",
  ui_story_5040_50400101_25_dialog_content = "안녕하세요. 나로세르의 의뢰를 받고 지원을 온 PlayerName인데요...",
  ui_story_5040_50400101_26_dialog_content = "두 사람은...?",
  ui_story_5040_50400101_27_dialog_content = "내가 상상했던 것보다 훨씬 젊네. 그럼 우선 자기소개를 할까?",
  ui_story_5040_50400101_28_dialog_content = "난 레디젤 렌치 지부의 장로 <color=#FFB400>예리아</color>야. 이쪽은 <color=#FFB400>타라</color>, 이번 우리 임무의 주인공이야.",
  ui_story_5040_50400101_29_dialog_content = "안녕, 타라라고 해. 전설의 그 아이테르를 만나다니 이거 운이 좋네!",
  ui_story_5040_50400101_30_dialog_content = "아니, 그렇게 대단한 건 아닌데... 근데 그럼 예리아 장로님도 같이 북방으로 가시나요?",
  ui_story_5040_50400101_31_dialog_content = "그냥 예리아라고 부르면 돼, 후훗.\n우편물에 실수가 좀 있었거든. 그래서 나로세르한테 도와달라고 한 거야.",
  ui_story_5040_50400101_32_dialog_content = "그 조건으로 결혼식 입회인 일은 내가 대신 맡게 됐어.",
  ui_story_5040_50400101_33_dialog_content = "(나로세르가 말했던 대량의 우편물을 어지럽힌 레디젤 렌치 쪽 동료가 혹시 예리아 씨인가?)",
  ui_story_5040_50400101_34_dialog_content = "입회인? 아, 전에 들은 적 있는 것 같아요.\n쿠리어가 결혼식에 참석하면 행복이 찾아온다고 말이에요.",
  ui_story_5040_50400101_35_dialog_content = "맞아! 관월제 날 결혼식에 쿠리어를 초대하는 게 얼마나 힘든지 알아?\n이번엔 어떻게든 나로세르 덕을 봐야 한다구!",
  ui_story_5040_50400101_36_dialog_content = "나로세르는 지금 하루도 시간을 못 낼 정도로 바쁜 거야?",
  ui_story_5040_50400101_37_dialog_content = "관월제 전후가 원래 제일 바쁘거든. 초대장이니 편지니 온 사방에 보내야 하니까.",
  ui_story_5040_50400101_38_dialog_content = "게다가 우리 아름다운 예리아 씨가 또 「깜빡」 실수를 해서\n북방에 갈 소포를 잔뜩 잘못 처리해 버렸지 뭐야.",
  ui_story_5040_50400101_39_dialog_content = "모처럼 아이테르 군도 불러왔는데 나한테 싫은 소리 하지 말고 얼른 출발해.\n미래의 남편을 빨리 보고 싶지 않아?",
  ui_story_5040_50400101_40_dialog_content = "그것도 그렇네요. 콜로서스가 아무리 빨라도 역시 일찍 출발하는 게 좋겠죠.",
  ui_story_5040_50400101_41_dialog_content = "우와! PlayerName 네 콜로서스는 우리 큰 도마뱀이랑 완전히 다르구나!",
  ui_story_5040_50400101_42_dialog_content = "아하하, 신난 모양이네.",
  ui_story_5040_50400101_43_dialog_content = "그나저나 사막 출신 신부와 북방 출신 신랑이라니 색다른 커플이잖아.\n이런 결혼이 자주 있는 편이야?",
  ui_story_5040_50400101_44_dialog_content = "으음, 뭐랄까~ 아주 흔치 않아!",
  ui_story_5040_50400101_45_dialog_content = "세상은 넓어. 그러니까 무슨 일이든지 일어날 수 있어.\n다만 오로리안의 눈으로 본다면 확실히 드물다고 할 수 있겠지.",
  ui_story_5040_50400101_46_dialog_content = "그, 그런가요?",
  ui_story_5040_50400101_47_dialog_content = "근데 예리아 장로... 아니, 예리아 씨도 레디젤 사막 출신인가요?",
  ui_story_5040_50400101_48_dialog_content = "인정하고 싶진 않지만, 맞아.",
  ui_story_5040_50400101_49_dialog_content = "예리아도 참 특이하다니까. 사막 토박이이면서 레디젤 렌치엔 아는 사람도 없고.",
  ui_story_5040_50400101_50_dialog_content = "나 여기 사무실 오는 것도 한참 물어서 겨우 찾아왔잖아.",
  ui_story_5040_50400101_51_dialog_content = "후훗, 누구나 자기만의 살아가는 방법이 있을 뿐이야.",
  ui_story_5040_50400101_52_dialog_content = "뭐, 내 얘긴 그만하면 됐어. 이번엔 네가 주인공이니까.",
  ui_story_5040_50400101_53_dialog_content = "그러게요! 저 결혼을 앞둔 신부를 만나는 건 처음이에요!",
  ui_story_5040_50400101_54_dialog_content = "그렇게 대단한 것도 아니야. 사막 사람들의 연애관은 무척 개방적이거든.",
  ui_story_5040_50400101_55_dialog_content = "아무튼 시간도 별로 없으니까, 일단 콜로서스부터 좀 구경하고 싶어.",
  ui_story_5040_50400101_56_dialog_content = "PlayerName, 미안한데 안내 좀 해 줘!",
  ui_story_5040_50400101_57_dialog_content = "아, 알았어. 잠깐만 기다려.",
  ui_story_5040_50400101_58_dialog_content = "이렇게 말해도 될지는 모르겠지만, 타라를 보면 왠지 신부라는 생각이 잘 안 들어요.",
  ui_story_5040_50400101_59_dialog_content = "누구나 자기 스타일이 있기 마련이야, 아이테르 군. 험담은 좋지 않아.",
  ui_story_5040_50400101_60_dialog_content = "...아, 그렇네요.",
  ui_story_5040_50400101_61_dialog_content = "(결혼식인데... 예리아 씨는 뭔가 무관심하네.)",
  ui_story_5040_50400101_62_dialog_content = "휴. 드디어 도착했네요.",
  ui_story_5040_50400101_63_dialog_content = "타라는 신랑한테 간 건가요? 근처에 마을이 하나 있었던 것 같은데...",
  ui_story_5040_50400101_64_dialog_content = "강림의 마을이야. 북방의 변두리에 있는데, 거기 사람들은 대부분 옛 전통을 지키거든.\n그래서 마을의 신전에서 결혼식을 올리는 사람들이 많아.",
  ui_story_5040_50400101_65_dialog_content = "그럼 우리도 그 신전으로 가면 되나요?",
  ui_story_5040_50400101_66_dialog_content = "신랑 신부는 아마 다른 곳에 있을걸.",
  ui_story_5040_50400101_67_dialog_content = "(...그나저나 신부는 이미 바래다줬는데, 나까지 결혼식에 참석할 필요가 있을까?)",
  ui_story_5040_50400101_68_dialog_content = "너 이제 돌아가도 되는 거 아닌가 생각하고 있지?",
  ui_story_5040_50400101_69_dialog_content = "(아, 들켜버렸네...)",
  ui_story_5040_50400101_70_dialog_content = "너도 나로세르의 지인이야. 그러니까 너한테도 분명히 결혼식에 참석해 달라고 할걸.",
  ui_story_5040_50400101_71_dialog_content = "그래도 모처럼 여기까지 왔잖아.\n백야성만큼 떠들썩하진 않지만, 북방의 결혼식도 꽤 볼만하거든.",
  ui_story_5040_50400101_72_dialog_content = "그것도 그렇네요. 근데... 예리아 씨는 레디젤 렌치 지부 장로잖아요?\n북방에 대해서도 잘 아는 건가요?",
  ui_story_5040_50400101_73_dialog_content = "북방뿐만이 아니야. 업무만 빼고 예리아는 모르는 게 없는 사람이거든.",
  ui_story_5040_50400101_74_dialog_content = "아하하, 돌아왔구나. 신랑은?",
  ui_story_5040_50400101_75_dialog_content = "타라!",
  ui_story_5040_50400101_76_dialog_content = "오, 오래 기다렸어...!",
  ui_story_5040_50400101_77_dialog_content = "정말 늦었네──",
  ui_story_5040_50400101_78_dialog_content = "이쪽은 예리아. 저번에 얘기했던 레디젤 사막 쿠리어 길드의 장로야.",
  ui_story_5040_50400101_79_dialog_content = "그리고 이쪽이 우릴 여기까지 데려다준 PlayerName, 아이테르야!\n콜로서스도 정말 대단했다니까!",
  ui_story_5040_50400101_80_dialog_content = "...이쪽은 <color=#FFB400>아도니스</color>, 내 약혼자야...\n음, 이렇게 부르니까 뭔가 어색하네. 평소엔 항상 이름만 불러서.",
  ui_story_5040_50400101_81_dialog_content = "예리아 장로님, PlayerName 씨, 안녕하세요.",
  ui_story_5040_50400101_82_dialog_content = "죄송합니다. 오늘 여러 가지로 정신이 없어서...\n나로세르는 제 동창입니다. 이번에도 여러모로 도움을 받게 됐네요.",
  ui_story_5040_50400101_83_dialog_content = "PlayerName 씨도 저희 결혼식에 꼭 참석해 주셨으면 좋겠습니다.",
  ui_story_5040_50400101_84_dialog_content = "참, 집에는 갔다 왔어?",
  ui_story_5040_50400101_85_dialog_content = "아, 아직...",
  ui_story_5040_50400101_86_dialog_content = "아직도 얘기 안 했어?",
  ui_story_5040_50400101_87_dialog_content = "대체 언제까지 미룰 생각인데?",
  ui_story_5040_50400101_88_dialog_content = "그, 금방 얘기할게. 내일이면 돌아가니까...",
  ui_story_5040_50400101_89_dialog_content = "오늘 물어보면 내일, 내일 물어보면 또 모레!\n이런 중요한 일을 도대체 언제까지 미룰 거야? 부모님한테 말씀드릴 생각은 있어?!",
  ui_story_5040_50400101_90_dialog_content = "......",
  ui_story_5040_50400101_91_dialog_content = "(...이게 무슨 상황이지?)",
  ui_story_5040_50400101_92_dialog_content = "아무래도 무슨 사정이 있는 것 같네.",
  ui_story_5040_50400101_93_dialog_content = "나랑 아이테르 군도 의뢰를 받아서 온 거잖아.\n우리한테도 상황을 좀 설명해 줘야 하지 않을까?",
  ui_story_5040_50400101_94_dialog_content = "흥, 네가 얘기해!",
  ui_story_5040_50400101_95_dialog_content = "...부끄러운 일이긴 하지만, 사실 저흰... 몰래 결혼식을 올리려던 겁니다.",
  ui_story_5040_50400101_96_dialog_content = "저희 부모님은 처음부터 타라와의 결혼을 반대하셨거든요.",
  ui_story_5040_50400101_97_dialog_content = "어쩐지.",
  ui_story_5040_50400101_98_dialog_content = "북방 남자가 사막 출신 여자와 결혼하는 것도 확실히 흔한 일은 아니니까.",
  ui_story_5040_50400101_99_dialog_content = "하지만 전 진지해요! 이번에야말로 부모님께 제대로 말씀드릴 겁니다!",
  ui_story_5040_50400101_100_dialog_content = "그리고 저흰 어딘가 멀리 가서 살 겁니다!\n레디젤 사막이든, 다른 어디든 좋으니까요!",
  ui_story_5040_50400101_101_dialog_content = "...그럼 도망가겠다는 거야?",
  ui_story_5040_50400101_102_dialog_content = "물론 저도 부모님께서 인정해 주시길 바라죠. 하지만...",
  ui_story_5040_50400101_103_dialog_content = "하지만 뭐? 아직 얘기도 안 했잖아?",
  ui_story_5040_50400101_104_dialog_content = "넌 자기 생각을 말하는 게 그렇게 어려워?",
  ui_story_5040_50400101_105_dialog_content = "난...",
  ui_story_5040_50400101_106_dialog_content = "저기, 아도니스. 너 설마 한 번도 북방에서 나온 적 없는 건 아니지?",
  ui_story_5040_50400101_107_dialog_content = "어, 없습니다... 저랑 타라는 북방에서 만났거든요.",
  ui_story_5040_50400101_108_dialog_content = "어머, 온실에서 자란 꽃이 갑자기 도적 생활에 뛰어들다니, 정말 대단한 용기네.",
  ui_story_5040_50400101_109_dialog_content = "전 이미 결심했습니다! 타라와 함께라면 어떤 어려움도 해결할 수 있을 겁니다!",
  ui_story_5040_50400101_110_dialog_content = "그래?! 그럼 부모님한테 솔직하게 얘기하는 건 왜 해결을 못 하는데?",
  ui_story_5040_50400101_111_dialog_content = "저기, 잠깐 실례하겠습니다!",
  ui_story_5040_50400101_112_dialog_content = "아도니스 씨, 당신 앞으로 소포가 왔어요. 전에 급하다고 하셔서 먼저 전해주러 왔어요.",
  ui_story_5040_50400101_113_dialog_content = "어머, 북방의 아기새 아냐?",
  ui_story_5040_50400101_114_dialog_content = "예, 예리아 장로님?",
  ui_story_5040_50400101_115_dialog_content = "저번에 편지 몇 통 북방으로 잘못 보냈던 일도 잘 처리해 줘서 정말 고마웠어.",
  ui_story_5040_50400101_116_dialog_content = "「몇 통」은 아니었을 텐데요... 다음부터는 주의해 주세요.",
  ui_story_5040_50400101_117_dialog_content = "<size=33>그때 업무량은 정말 다시 생각하고 싶지도 않아요...</size>",
  ui_story_5040_50400101_118_dialog_content = "고마워요, <color=#FFB400>키아</color>.",
  ui_story_5040_50400101_119_dialog_content = "그건 뭐야?",
  ui_story_5040_50400101_120_dialog_content = "아, 이건 영매가 배송을 의뢰한 물약이에요.\n효과가 아주 좋으니까 조심해서 쓰라고 하더라구요.",
  ui_story_5040_50400101_121_dialog_content = "물약? 무슨 약인데?",
  ui_story_5040_50400101_122_dialog_content = "그, 그건... 돌아가면 얘기해 줄게...",
  ui_story_5040_50400101_123_dialog_content = "그러니까 대체 무슨 약인데 말을 못 하는 거야?!",
  ui_story_5040_50400101_124_dialog_content = "휴...",
  ui_story_5040_50400101_125_dialog_content = "이건 아주 신통한 영매가 만들어 준 <color=#FFB400>만능 마법약</color>이야.\n용기나 의지가 필요할 때 마시면 효과가 있대.",
  ui_story_5040_50400101_126_dialog_content = "이게 있으면 부모님한테 얘기할 때 도움이 되지 않을까 싶어서...",
  ui_story_5040_50400101_127_dialog_content = "(마법약? 그런 게 진짜 존재하는 건가?)",
  ui_story_5040_50400101_128_dialog_content = "하아? 너 머리에 문제 있어?! 그런 걸 믿는단 말이야?! 빨리 줘 봐!",
  ui_story_5040_50400101_129_dialog_content = "정말 믿기지가 않네. 아직도 영매 따위한테 속는 사람이 있단 말이야?!",
  ui_story_5040_50400101_130_dialog_content = "게다가 우린 벌써 3년이나 만났어.\n지금 와서 부모님한테 말씀드리는 데 무슨 마법약 같은 게 필요하단 말이야?!",
  ui_story_5040_50400101_131_dialog_content = "나, 나도 다 우리 둘을 위해서 그러는 거잖아!",
  ui_story_5040_50400101_132_dialog_content = "너 그렇게 겁쟁이야? 우리의 미래에 그렇게 자신이 없어?!",
  ui_story_5040_50400101_133_dialog_content = "우리 사이가 지금도 고작 그런 물건에 의지해야 하는 거냐고! 아도니스!",
  ui_story_5040_50400101_134_dialog_content = "너 하는 걸 보니까 아무래도 이 결혼...",
  ui_story_5040_50400101_135_dialog_content = "<color=#e8d9bb>스슥──</color>",
  ui_story_5040_50400101_136_dialog_content = "<size=45>크오오!</size>",
  ui_story_5040_50400101_137_dialog_content = "<size=45>크에엑!</size>",
  ui_story_5040_50400101_138_dialog_content = "웬 암귀야?",
  ui_story_5040_50400101_139_dialog_content = "여기 암귀가 왜 있어?!",
  ui_story_5040_50400101_140_dialog_content = "이런 녀석들이랑 마주치다니, 정말 귀찮게 됐네.",
  ui_story_5040_50400201_1_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5040_50400201_2_dialog_content = "캬악──!",
  ui_story_5040_50400201_3_dialog_content = "크오오──!",
  ui_story_5040_50400201_4_dialog_content = "뭐야? 어디서 암귀가 이렇게 잔뜩 온 거지?!",
  ui_story_5040_50400201_5_dialog_content = "귀찮긴 하지만, 그래도 조심하는 게 좋겠어.",
  ui_story_5040_50400201_6_dialog_content = "가운데 저 암귀, 왠지 이상해.",
  ui_story_5040_50400201_7_dialog_content = "후... 후우...",
  ui_story_5040_50400201_8_dialog_content = "타라! 뒤에!",
  ui_story_5040_50400201_9_dialog_content = "아도니스, 오지 마! 여긴 우리한테 맡겨!",
  ui_story_5040_50400201_10_dialog_content = "타라 씨, 조심하세요! 저 이상한 암귀, 계속 타라 씨를 보고 있어요!",
  ui_story_5040_50400201_11_dialog_content = "줘...",
  ui_story_5040_50400201_12_dialog_content = "나한테... 줘...",
  ui_story_5040_50400201_13_dialog_content = "가, 갖고 싶어... 나 줘...",
  ui_story_5040_50400201_14_dialog_content = "무슨 소리야?!",
  ui_story_5040_50400201_15_dialog_content = "(통용어를 하고 있잖아?)",
  ui_story_5040_50400201_16_dialog_content = "타라, 그 약병을 던져버려.",
  ui_story_5040_50400201_17_dialog_content = "그게 무슨...",
  ui_story_5040_50400201_18_dialog_content = "<color=#e8d9bb>콰앙!</color>",
  ui_story_5040_50400201_19_dialog_content = "타라!!",
  ui_story_5040_50400201_20_dialog_content = "위험해, 피해!",
  ui_story_5040_50400201_21_dialog_content = "<color=#e8d9bb>치이익──</color>",
  ui_story_5040_50400201_22_dialog_content = "으앗!",
  ui_story_5040_50400201_23_dialog_content = "야...약이...",
  ui_story_5040_50400201_24_dialog_content = "캬악──",
  ui_story_5040_50400201_25_dialog_content = "끄에엑!",
  ui_story_5040_50400201_27_dialog_content = "암귀가 도망가는데?",
  ui_story_5040_50400201_28_dialog_content = "작은 녀석들은 아직 남았어.",
  ui_story_5040_50400201_29_dialog_content = "아도니스, 약혼녀를 잘 지켜 줘.",
  ui_story_5040_50400202_1_dialog_content = "이제 끝났네. 다들 괜찮아?",
  ui_story_5040_50400202_2_dialog_content = "타라! 타라!",
  ui_story_5040_50400202_3_dialog_content = "큰일 났어요! 기절했나 봐요!",
  ui_story_5040_50400202_4_dialog_content = "둘 다 비켜 봐. 내가 봐줄 테니까.",
  ui_story_5040_50400202_5_dialog_content = "중상은 아니야. 도망친 그 암귀가 딱히 큰 해를 입히진 않았어.",
  ui_story_5040_50400202_6_dialog_content = "보이는 건 그냥 찰과상이야.",
  ui_story_5040_50400202_7_dialog_content = "다친 데는 없는데 정신을 잃은 건가요? 혹시 머리라도 부딪힌 건 아닐까요?",
  ui_story_5040_50400202_8_dialog_content = "일단 진정해. 당장 겉보기에 문제는 없으니까.\n아무튼 안전한 곳으로 데려가서 쉬게 해 주자.",
  ui_story_5040_50400202_9_dialog_content = "아, 그러고 보니까 병에 들어 있던 약이 타라 씨한테 쏟아졌네요...",
  ui_story_5040_50400202_10_dialog_content = "혹시 뭐 안 좋은 성분이라도 들어있진 않겠죠?!",
  ui_story_5040_50400202_11_dialog_content = "저, 저도 모르죠... 아도니스 씨 당신이 주문한 거잖아요. 전 배달만 했을 뿐이에요.",
  ui_story_5040_50400202_12_dialog_content = "아무튼 일단 진정해. 일단 타라 씨부터 쉴 만한 곳으로 데리고 가자.",
  ui_story_5040_50400202_13_dialog_content = "음... 그럼 여러분, 번거롭겠지만 저희 집으로 가시죠...",
  ui_story_5040_50400202_14_dialog_content = "전 아직 배달이 남았으니 먼저 실례할게요. 타라 씨를 잘 챙겨주세요.",
  ui_story_5040_50400202_15_dialog_content = "<color=#e8d9bb>똑똑똑.</color>",
  ui_story_5040_50400202_16_dialog_content = "아도니스? 왜 이런 시간에...",
  ui_story_5040_50400202_17_dialog_content = "이게 무슨 일이냐?!",
  ui_story_5040_50400202_18_dialog_content = "아버지, 말하자면 길어요... 일단 좀 들어갈게요.",
  ui_story_5040_50400202_19_dialog_content = "아도니스, 다른 사람들은 네 친구들이니? 이 여자애는... 타라잖아?",
  ui_story_5040_50400202_20_dialog_content = "안녕하세요. 잠깐 실례할게요.",
  ui_story_5040_50400202_21_dialog_content = "어머니, 타라가 다쳤어요. 아까 암귀를 만나서...\n일단은 좀 쉬게 해 주세요. 자세한 설명은 나중에 할게요.",
  ui_story_5040_50400202_22_dialog_content = "암귀?! 집에 응급처치용 약초가 있을 거야. 넌 어디 안 다쳤니?!",
  ui_story_5040_50400202_23_dialog_content = "괜찮아요. 그냥 찰과상이고, 조금 놀랐을 뿐이에요. 다른 사람들도 괜찮아요.",
  ui_story_5040_50400202_24_dialog_content = "타라를 눕히고 올 테니까 이야기 나누고 계세요.",
  ui_story_5040_50400202_25_dialog_content = "휴... 그러니까 어떻게 된 거냐면요...",
  ui_story_5040_50400202_26_dialog_content = "정말 어이가 없구나!",
  ui_story_5040_50400202_27_dialog_content = "그런 중요한 일을 왜 우리한테 말 안 한 거니?",
  ui_story_5040_50400202_28_dialog_content = "타라가 안 다쳤으면 우리 몰래 결혼하고 북방을 떠날 생각이었니?",
  ui_story_5040_50400202_29_dialog_content = "전...",
  ui_story_5040_50400202_30_dialog_content = "그냥 생각만 좀 단순한 녀석인 줄 알았는데, 이렇게까지 바보였다니!",
  ui_story_5040_50400202_31_dialog_content = "노비오 선생님이 가르쳐 주신 건 전부 어디다 팔아먹은 거냐!",
  ui_story_5040_50400202_32_dialog_content = "네가 정말 북방을 떠나도 살 수 있다고 생각한다면 어디 마음대로 해 봐라!\n다시는 돌아오지 마!",
  ui_story_5040_50400202_33_dialog_content = "우리한테 너 같은 아들은 없었던 거니까!",
  ui_story_5040_50400202_34_dialog_content = "아, 아버지, 어머니... 그런 뜻이 아니었어요!",
  ui_story_5040_50400202_35_dialog_content = "쓸데없는 변명 마라. 듣고 싶지 않으니까!",
  ui_story_5040_50400202_36_dialog_content = "너희 아버지는 지금 화가 나서 괜히 그러시는 거야.",
  ui_story_5040_50400202_37_dialog_content = "하지만 아도니스... 넌 정말 우릴 속상하게 만드는구나.",
  ui_story_5040_50400202_38_dialog_content = "......",
  ui_story_5040_50400202_39_dialog_content = "하아....",
  ui_story_5040_50400202_40_dialog_content = "(이, 이런 자리에 있어보는 건 또 처음이네...)",
  ui_story_5040_50400202_41_option_content = "(아도니스를 위로한다)",
  ui_story_5040_50400202_42_dialog_content = "너무 속상해하지 마. 부모님은 그냥 화가 나신 거니까.",
  ui_story_5040_50400202_43_dialog_content = "누구나 이런 일이 있으면 화를 내는 것도 당연하잖아.",
  ui_story_5040_50400202_44_dialog_content = "그래도 부모 자식 사이니까, 서로 잘 이야기하면 분명히 말이 통할 거야.",
  ui_story_5040_50400202_45_dialog_content = "휴... 부모님의 이해도 못 받고, 타라도 다치게 만들고...",
  ui_story_5040_50400202_46_dialog_content = "전 정말 실패자입니다...",
  ui_story_5040_50400202_47_dialog_content = "(이런... 자기부정의 소용돌이에 빠진 모양이네...)",
  ui_story_5040_50400202_48_option_content = "(예리아에게 도움을 청한다)",
  ui_story_5040_50400202_49_dialog_content = "예리아 씨, 어떡하죠?",
  ui_story_5040_50400202_50_dialog_content = "응? 뭐가?",
  ui_story_5040_50400202_51_dialog_content = "(뭐야, 예리아 씨, 설마 딴생각하고 있었나?!\n사람이 이런 상황에서도 딴생각을 할 수 있는 거였어?!)",
  ui_story_5040_50400202_52_dialog_content = "이럴 땐 뭐라고 하면 좋을까요?",
  ui_story_5040_50400202_53_dialog_content = "본인 문제잖아. 남이 이러쿵저러쿵 말해도 소용없어.",
  ui_story_5040_50400202_54_dialog_content = "지금 듣기 좋은 말을 해 봤자 문제는 해결되지 않아.",
  ui_story_5040_50400202_55_dialog_content = "(확실히 맞는 말이지만... 그렇다고 아무것도 안 할 순 없잖아!)",
  ui_story_5040_50400202_56_dialog_content = "(으으... 이 분위기, 정말 무섭네.)",
  ui_story_5040_50400202_57_dialog_content = "죄송합니다... 두 분께 추한 모습을 보였네요.",
  ui_story_5040_50400202_58_dialog_content = "아니야. 우리가 도울 일이 있으면 얼마든지 말해.",
  ui_story_5040_50400202_59_dialog_content = "휴, 전부 제 잘못인걸요.",
  ui_story_5040_50400202_60_dialog_content = "특별히 멀리서 와주셨는데 제대로 대접도 못 해드려서 죄송합니다...",
  ui_story_5040_50400202_61_dialog_content = "후훗, 지금은 그런 말할 때가 아니잖아.",
  ui_story_5040_50400202_62_dialog_content = "PlayerName, 아도니스랑 산책이라도 하면서 기분전환하고 와.\n난 타라 옷 갈아입혀 줄 테니까.",
  ui_story_5040_50400202_63_dialog_content = "알겠어요.\n그럼 가자, 아도니스 씨.",
  ui_story_5040_50400202_64_dialog_content = "네...",
  ui_story_5040_50400202_65_dialog_content = "......",
  ui_story_5040_50400202_66_dialog_content = "너도 슬슬 일어나지 그래?",
  ui_story_5040_50400202_67_dialog_content = "?!",
  ui_story_5040_50400202_68_dialog_content = "어떻게 알았어?",
  ui_story_5040_50400202_69_dialog_content = "다칠 리가 없잖아. 그 암귀, 애초에 널 제대로 공격하지도 않았어.",
  ui_story_5040_50400202_70_dialog_content = "그런데 이렇게 한참 기절하는 게 말이 돼?",
  ui_story_5040_50400202_71_dialog_content = "......",
  ui_story_5040_50400202_72_dialog_content = "난 나로세르한테 부탁받은 일만 끝내면 돼. 다른 일은 관심 없어.",
  ui_story_5040_50400202_73_dialog_content = "애초에 나랑 상관도 없으니까.",
  ui_story_5040_50400202_74_dialog_content = "그래도 인정상 한 마디만 할게. 이제부터 어떻게 할 생각이야?",
  ui_story_5040_50400202_75_dialog_content = "난... 하아...",
  ui_story_5040_50400202_76_dialog_content = "솔직히 나도 잘 모르겠어. 사막에 있을 땐 고민할 일도 전혀 없었는데... 골치 아파.",
  ui_story_5040_50400202_77_dialog_content = "아도니스랑 같이 있으면 즐겁다는 건 부정하지 않아.\n하지만 저렇게 의지할 수 없는 걸 보면, 정말 이 결혼을 하는 게 맞는 건지 확신이 안 서.",
  ui_story_5040_50400202_78_dialog_content = "인간성 같은 건 하루아침에 변하는 게 아니야.\n둘이 그렇게 오래 만났으면, 그걸 이제 와서 안 건 아닐 거잖아?",
  ui_story_5040_50400202_79_dialog_content = "당연하지.",
  ui_story_5040_50400202_80_dialog_content = "3년 전에 난 북방 유적을 탐색하다가 암귀의 습격을 당했어.\n겨우 도망치던 중에 길에서 쓰러져 버렸지.",
  ui_story_5040_50400202_80X1_dialog_content = "그때 아도니스가 날 구해줬고, 집으로 데려가 줬어.",
  ui_story_5040_50400202_81_dialog_content = "그날은 폭설이 내렸어. 만약 아도니스가 없었다면 아마 난 끝장이었을 거야.",
  ui_story_5040_50400202_82_dialog_content = "휴... 그 뒤로 우린 정말 많은 얘길 나눴는데, 하나같이 서로가 지금까지 모르던 것들이었어.",
  ui_story_5040_50400202_83_dialog_content = "사막에 돌아와서도 우린 계속 편지를 주고받았어.",
  ui_story_5040_50400202_84_dialog_content = "아도니스는 세심하고 자상해...\n난 부모님 없이 큰 애라서 누가 나한테 그렇게 잘해준 건 처음이었어.",
  ui_story_5040_50400202_85_dialog_content = "그래서 진심으로 감동했어.",
  ui_story_5040_50400202_86_dialog_content = "으음~ 그랬구나.",
  ui_story_5040_50400202_87_dialog_content = "근데 그 뒤로 북방을 떠나자는 이야기를 꺼낼 때마다 아도니스는 항상 머뭇거렸어.\n난 아도니스가 왠지 좀 변한 것 같아.",
  ui_story_5040_50400202_88_dialog_content = "전에는 안 그랬거든. 뭔가를 결심하는 게 그렇게 어려운 거란 말이야?",
  ui_story_5040_50400202_89_dialog_content = "저렇게 겁 많고 우유부단한 사람은 정말 처음이야! 정말 날 좋아하긴 하는 거야?!",
  ui_story_5040_50400202_90_dialog_content = "난 우리 결혼식을 오래전부터 준비했어...\n그리고 아주 특별한 선물도 준비했는데. 이젠... 휴...",
  ui_story_5040_50400202_91_dialog_content = "내가 물어볼 말은 아니긴 한데, 혹시 너 전에도 연애해 본 적 있어?",
  ui_story_5040_50400202_92_dialog_content = "전에? 없어. 아도니스는 내 첫사랑이야.",
  ui_story_5040_50400202_93_dialog_content = "그럼 그렇지. 아무래도 넌 아도니스한테 환상을 품고 있는 것 같네.",
  ui_story_5040_50400202_94_dialog_content = "사랑은 무척 아름다운 일일 수도 있겠지. 하지만 서로의 본질도 존중해야만 해.\n모든 개인은 복잡한 존재고, 흑백이 분명하게 가려지지 않는 법이거든.",
  ui_story_5040_50400202_95_dialog_content = "무, 무슨 말이야...? 이해가 잘 안돼.",
  ui_story_5040_50400202_96_dialog_content = "후훗, 조만간 알게 될지도 몰라.",
  ui_story_5040_50400202_97_dialog_content = "......",
  ui_story_5040_50400202_98_dialog_content = "잠깐만! 떠올랐어! 좋은 생각이 있어!",
  ui_story_5040_50400202_99_dialog_content = "?",
  ui_story_5040_50400202_102_dialog_content = "정했어!",
  ui_story_5040_50400202_103_dialog_content = "기억상실인 척하는 거야!\n처음부터 다시 시작해서 아도니스가 어떤 태도를 보일지 봐야겠어!",
  ui_story_5040_50400202_104_dialog_content = "......",
  ui_story_5040_50400202_105_dialog_content = "너 진심이니?",
  ui_story_5040_50400202_106_dialog_content = "제발 도와줘!",
  ui_story_5040_50400202_107_dialog_content = "너희 결혼 안 할 거면, 나 이제 가도 될 것 같은데?",
  ui_story_5040_50400202_108_dialog_content = "아, 안 돼! 돌아가서 나로세르한테 뭐라고 해명하려고?!",
  ui_story_5040_50400202_109_dialog_content = "지금 협박하는 거야?",
  ui_story_5040_50400202_110_dialog_content = "다, 당연히 아니지! 어떻게 그러겠어!\n우리 멋진 예리아 언니~ 내 평생 소원이니까 제발 좀 도와줘!",
  ui_story_5040_50400202_111_dialog_content = "나로세르 체면도 있고, 같은 고향 사람끼리 돕고 살아야지! 제발!",
  ui_story_5040_50400202_112_dialog_content = "정말 잘도 시켜 먹네.",
  ui_story_5040_50400202_113_dialog_content = "진짜 귀찮아.",
  ui_story_5040_50400202_114_dialog_content = "야호! 예리아 최고!",
  ui_story_5040_50400202_115_dialog_content = "대신 너희 일은 너희가 알아서 해. 난 그냥 옆에서 보기만 할 거니까.",
  ui_story_5040_50400202_116_dialog_content = "네 연기가 잘 될지 어떨지는 전부 너한테 달렸어.",
  ui_story_5040_50400202_117_dialog_content = "<color=#e8d9bb>다음 날</color>",
  ui_story_5040_50400202_118_dialog_content = "예리아 씨, 아도니스 씨, 좋은 아침.",
  ui_story_5040_50400202_119_dialog_content = "안녕, 아이테르 군.",
  ui_story_5040_50400202_120_dialog_content = "안녕하세요. 전 타라가 일어났는지 좀 보러...",
  ui_story_5040_50400202_121_dialog_content = "하암~",
  ui_story_5040_50400202_122_dialog_content = "타라! 일어났구나?! 몸 상태는 어때?",
  ui_story_5040_50400202_123_dialog_content = "......?",
  ui_story_5040_50400202_124_dialog_content = "왜 그래? 왜 그런 눈으로 보는 거야?",
  ui_story_5040_50400202_125_dialog_content = "...누구?",
  ui_story_5040_50400202_126_dialog_content = "무슨 소리야? 타라...",
  ui_story_5040_50400202_127_dialog_content = "건들지 마! 나 그쪽 누군지 모른다구.",
  ui_story_5040_50400202_128_dialog_content = "여긴 어디야? 넌 또 누군데?",
  ui_story_5040_50400202_129_dialog_content = "분명히 어제 예리아랑 같이 콜로서스로 북방에 왔었는데...\n이상하네, 그러고 보니까 북방엔 왜 온 거지?",
  ui_story_5040_50400202_130_dialog_content = "타라, 그런 농담은...",
  ui_story_5040_50400202_131_dialog_content = "하나도 재미없어!",
  ui_story_5040_50400202_132_dialog_content = "아도니스 씨, 괜찮아?",
  ui_story_5040_50400202_133_dialog_content = "(이상하네... 타라한테서 감정의 기복이 전혀 느껴지질 않아... 설마 일부러 그러는 건가?)",
  ui_story_5040_50400202_134_dialog_content = "(연애 같은 건 잘 모르겠지만... 왠지 사실대로 말하면 큰일 날 것 같네... 일단 내버려 두자.)",
  ui_story_5040_50400202_135_dialog_content = "미안... 내가 잘못했어. 다 내 잘못이야.",
  ui_story_5040_50400202_136_dialog_content = "애초부터 무슨 약 따위에 의지하려는 게 잘못된 거였어!",
  ui_story_5040_50400202_137_dialog_content = "약 때문에 타라가 기억상실증에 걸린 거라고 생각하는 거야?",
  ui_story_5040_50400202_138_dialog_content = "영매가 그 약은 만능이라고 했어요. 어떤 효과든지 있을 거예요!\n그러니까 약 말고는 다른 이유가 없어요!",
  ui_story_5040_50400202_139_dialog_content = "분명히 타라는 제가 싫어서 절 잊어버리고 싶다고 생각했고, 약이 그걸 들어준 거겠죠!",
  ui_story_5040_50400202_140_dialog_content = "다 저 때문이에요!",
  ui_story_5040_50400202_141_dialog_content = "그럼 그 영매한테 물어보러 가면 되지 않을까?",
  ui_story_5040_50400202_142_dialog_content = "여기서 그냥 울고 있어봤자 아무 소용도 없잖아.",
  ui_story_5040_50400202_143_dialog_content = "영매?",
  ui_story_5040_50400202_144_dialog_content = "아, 그렇네요! 생각났습니다. 그 영매는 가끔 시장에 노점을 차리거든요.",
  ui_story_5040_50400202_145_dialog_content = "가요, 지금 바로!",
  ui_story_5040_50400202_146_dialog_content = "휴, 휴우... 바로 이 사람입니다!",
  ui_story_5040_50400202_147_dialog_content = "(빠, 빨리도 달리네...)",
  ui_story_5040_50400202_148_dialog_content = "음? 당신은?",
  ui_story_5040_50400202_149_dialog_content = "저번에 만능 마법약을 샀던 사람입니다. 급하게 좀 물어볼 게 있습니다!",
  ui_story_5040_50400202_150_dialog_content = "음... 아! 그거!",
  ui_story_5040_50400202_151_dialog_content = "어땠어? 내가 공들여 만든 약인데, 효과는 괜찮았나?",
  ui_story_5040_50400202_152_dialog_content = "짧게 설명할게요. 제 약혼자가 실수로 그 약을 써 버려서, 지금 기억을 잃고 말았습니다...\n지금 당장 해독약을 주세요!",
  ui_story_5040_50400202_153_dialog_content = "하? 그럴 리가...",
  ui_story_5040_50400202_154_dialog_content = "그 약은 뭐든지 효과가 있다고 했잖아요? 뭐든지 소원이 이루어진다고 말이에요!",
  ui_story_5040_50400202_155_dialog_content = "그, 그거야 분명히 그렇게 말하긴 했지.",
  ui_story_5040_50400202_156_dialog_content = "다만 해독제가 필요한 거라면 좀 곤란하게 됐어.",
  ui_story_5040_50400202_157_dialog_content = "네? 왜죠?!",
  ui_story_5040_50400202_158_dialog_content = "그 약은 아무도 본 적이 없는, 레디젤 사막에서 가장 희귀한 분홍색 샌드버그의\n빛나는 비늘로 만드는 것이기 때문이지!",
  ui_story_5040_50400202_159_dialog_content = "내가 그 사막에서 온 사람이야. 그런 거 들어본 적 없는데?",
  ui_story_5040_50400202_160_dialog_content = "!",
  ui_story_5040_50400202_161_dialog_content = "크흠, 너희 같은 일반인들이 알 수 있는 거면 그게 희귀한 거겠어?!",
  ui_story_5040_50400202_162_dialog_content = "그 신비한 분홍색 샌드버그는 보통 사람들은 평생 한 번도 못 보는 거라고!",
  ui_story_5040_50400202_163_dialog_content = "(이 영매, 거짓말을 하고 있네... 게다가 샌드버그를 보고 싶은 사람이 어디 있어?!)",
  ui_story_5040_50400202_164_dialog_content = "그 비늘은 일곱 가지 색으로 빛나고, 몸은 분홍색인 데다가,\n조개껍데기처럼 화려하게 반짝이지!",
  ui_story_5040_50400202_165_dialog_content = "아무튼 해독제를 만들려면 그 비늘이 필요해. 너희가 알아서 구해 봐!",
  ui_story_5040_50400202_166_dialog_content = "그, 그런 힘든 일을 떠맡기면 어떡해요?!",
  ui_story_5040_50400202_167_dialog_content = "내가 필요한 것도 아닌데 왜? 이것도 호의로 알려준 거라고.\n그러니까 얼른 가라. 남의 장사 초 치지 말고.",
  ui_story_5040_50400202_168_dialog_content = "......",
  ui_story_5040_50400202_169_dialog_content = "안 돼요... 이제 다 끝났어요...",
  ui_story_5040_50400202_170_dialog_content = "심부름이라면 얼마든지 할 수 있지만, 샌드버그와 싸우라니... 저한테는 무리입니다.",
  ui_story_5040_50400202_171_dialog_content = "가끔 집에 나오는 벌레조차 무서운데, 어떻게 사막에 가서 샌드버그를 찾겠어요?!",
  ui_story_5040_50400202_172_dialog_content = "음, 너처럼 겁이 많은 남자는 확실히 흔치 않지.",
  ui_story_5040_50400202_173_dialog_content = "(...제발 불 난 집에 기름 좀 붓지 마요!)",
  ui_story_5040_50400202_174_dialog_content = "일단 좋게 좋게 생각하자. 적어도 타라는 무사하잖아.\n게다가 잃어버린 건 왠지 너에 관한 기억뿐인 것 같아.",
  ui_story_5040_50400202_175_dialog_content = "그럼 샌드버그를 찾는다는 비현실적인 생각은 하지 말고,\n차라리 타라의 마음을 어떻게 되찾을 지나 생각해 봐.",
  ui_story_5040_50400202_176_dialog_content = "맞아. 모든 걸 잊은 건 아니잖아. 타라 씨만 무사하다면 얼마든지 가능성은 있어.",
  ui_story_5040_50400202_177_dialog_content = "두 사람이 오랫동안 연인 사이였던 데는 이유가 있을 거라 생각해.\n그러니까 처음부터 다시 관계를 만드는 것도 어렵진 않을 거야.",
  ui_story_5040_50400202_178_dialog_content = "그래요. 두 분 말은 맞아요.",
  ui_story_5040_50400202_179_dialog_content = "하지만 지금 전 어디서부터 시작해야 할지 전혀 모르겠어요...\n타라한테 전 이미 낯선 사람인걸요...",
  ui_story_5040_50400202_180_dialog_content = "그 얘기가 나와서 말인데, 너희 잊은 건 아니지?\n난 이번에 나로세르를 대신해서 결혼식에 참석하러 온 거였어.",
  ui_story_5040_50400202_181_dialog_content = "관월제는 애초부터 결혼식을 올리는 사람이 많아.\n게다가 자기 결혼식에 쿠리어를 부르고 싶어하는 사람도 많고.",
  ui_story_5040_50400202_182_dialog_content = "그거 저도 들어봤어요.\n쿠리어가 결혼식에 참석하면 행복과 희망의 상징이 된다면서요.",
  ui_story_5040_50400202_183_dialog_content = "맞아. 그래서 쿠리어 길드에서도 최근 몇 년간 예비 신혼부부나 커플을\n대상으로 관월제 이벤트를 기획했거든.",
  ui_story_5040_50400202_184_dialog_content = "안 그래도 이 시기는 바쁘니까, 그렇게 해서라도 쿠리어들의 부담을 덜어주려는 거지.",
  ui_story_5040_50400202_185_dialog_content = "네? 그런 건 또 처음 듣는데요.",
  ui_story_5040_50400202_186_dialog_content = "응, 당연하지. 「커플」 대상으로 기획한 이벤트를 「모쏠」한테 알려줄 리가 없잖아.",
  ui_story_5040_50400202_187_dialog_content = "으윽!",
  ui_story_5040_50400202_188_dialog_content = "무슨 뜻이죠?",
  ui_story_5040_50400202_189_dialog_content = "내가 말한 이벤트는 쿠리어를 결혼식에 초대하는 풍습을 대체하기 위한 건데,\n신혼부부에게 행운을 준다는 점에는 변함이 없어.",
  ui_story_5040_50400202_190_dialog_content = "지부마다 이벤트 내용은 달라.\n그리고 조건을 충족하면 쿠리어 길드의 깃털 도장을 찍어줄 거야.",
  ui_story_5040_50400202_191_dialog_content = "그러니까 이참에 너도 타라랑 같이 쿠리어 길드 이벤트에 참여해 보는 게 어때?\n겸사겸사 바깥세상 구경도 할 수 있잖아.",
  ui_story_5040_50400202_192_dialog_content = "북방을... 떠나는 건가요?",
  ui_story_5040_50400202_193_dialog_content = "기억상실은 보통 외부의 자극으로 과거의 기억을 깨우거나 할 수 있어.\n이것도 일종의 민간요법 같은 거야.",
  ui_story_5040_50400202_194_dialog_content = "아무튼 그런 방법도 있다는 얘기지.\n이벤트는 그냥 계기일 뿐이고, 어떻게 할지는 너한테 달렸어.",
  ui_story_5040_50400202_195_dialog_content = "틀어박혀 있으면 혼자 고민만 이어질 뿐이야.\n바깥에 안 나가면 해결 방법이 있는지 어떻게 알 수 있겠어?",
  ui_story_5040_50400202_196_dialog_content = "나가서 돌아다니다 보면 기억을 되찾는 방법을 찾을 수 있을지도 모르잖아.\n뭐, 나랑은 상관없는 일이지만,",
  ui_story_5040_50400202_197_dialog_content = "나도 예리아 씨 말이 맞는 같아!",
  ui_story_5040_50400202_198_dialog_content = "나도 오랫동안 혼자 지낸 경험이 있거든.\n그때 내가 가진 상식은 전부 들어서 배운 것들뿐이었어.",
  ui_story_5040_50400202_199_dialog_content = "근데 그 뒤로 바깥세상에 나와 보니까, 대륙엔 내가 모르는 게 정말 많다는 걸 알았어.",
  ui_story_5040_50400202_200_dialog_content = "여러 곳을 돌아다니다 보면 기억을 되찾을 수 있을지도 모르고,\n병에 대해서도 뭔가 알 수 있을지도 몰라!",
  ui_story_5040_50400202_201_dialog_content = "두 분...",
  ui_story_5040_50400202_202_dialog_content = "정말... 휴... 뭐라고 감사를 드려야 할지...",
  ui_story_5040_50400202_203_dialog_content = "저흴 그렇게나 신경 써 주셔서 정말 감사합니다...\n역시 지금 가장 중요한 건 타라의 병을 고치는 거겠죠.",
  ui_story_5040_50400202_204_dialog_content = "그래요! 전 저희의 사랑이 그렇게 약하지 않다고 생각해요!\n비록 한 번 잃었지만, 반드시 되찾을 수 있을 거예요!",
  ui_story_5040_50400202_205_dialog_content = "......",
  ui_story_5040_50400202_206_dialog_content = "......",
  ui_story_5040_50400202_207_dialog_content = "여기까지가 제 생각이에요!",
  ui_story_5040_50400202_208_dialog_content = "전 두 분이 동의하지 않으실 거 알아요. 하지만 전...",
  ui_story_5040_50400202_209_dialog_content = "그래, 가라.",
  ui_story_5040_50400202_210_dialog_content = "네?",
  ui_story_5040_50400202_211_dialog_content = "너희가 각지를 다녀본 뒤에도 계속 함께하고 싶다면, 그땐 우리도 진지하게 생각해 보마.",
  ui_story_5040_50400202_212_dialog_content = "지, 진짜요?",
  ui_story_5040_50400202_213_dialog_content = "정말 감사합니다! 아버지, 어머니!",
  ui_story_5040_50400202_214_dialog_content = "하지만 넌 태어나서 한 번도 북방을 나간 적이 없잖니.\n바깥세상은 위험하니까 꼭 조심하렴.",
  ui_story_5040_50400202_215_dialog_content = "<size=33>예리아 씨, 부모님들이 왜 갑자기 마음을 바꾸신 걸까요?</size>",
  ui_story_5040_50400202_216_dialog_content = "그러게, 왜 그럴까?",
  ui_story_5040_50400202_217_dialog_content = "선생님, 잠깐 말씀 좀 나눌 수 있을까요?",
  ui_story_5040_50400202_218_dialog_content = "음? 당신은...",
  ui_story_5040_50400202_219_dialog_content = "전 쿠리어 길드의 장로, 예리아라고 해요.",
  ui_story_5040_50400202_220_dialog_content = "아, 무슨 일이십니까? 혹시 제 못난 아들 얘기라면...",
  ui_story_5040_50400202_221_dialog_content = "전 선생님을 이해할 수 있어요.",
  ui_story_5040_50400202_222_dialog_content = "자녀가 행복하길 바라지 않는 부모는 없어요.\n선생님은 아드님의 순수하고 앳된 점이 걱정되시는 거겠죠.",
  ui_story_5040_50400202_223_dialog_content = "지금까지 집도 떠난 적 없던 아이가 갑자기 유랑 생활을 하겠다니 말이에요.",
  ui_story_5040_50400202_224_dialog_content = "저라도 같은 입장이라면 받아들일 수 없었을 거예요.",
  ui_story_5040_50400202_225_dialog_content = "휴... 맞습니다. 삶이 어디 그리 쉬운 일이겠습니까!",
  ui_story_5040_50400202_226_dialog_content = "아도니스는 어릴 적부터 노비오 선생님의 지도를 받아서\n세심하고 총명하게 자랐지만, 너무 순진한 게 탈이었습니다.",
  ui_story_5040_50400202_227_dialog_content = "경험이 없으면 모든 게 그저 좋게만 보일 뿐이지요.",
  ui_story_5040_50400202_228_dialog_content = "그럼 이번 기회에 경험하게 해보는 건 어떨까요?",
  ui_story_5040_50400202_229_dialog_content = "아기새도 부모 곁을 떠나지 않으면 생존 능력을 익힐 수 없어요.",
  ui_story_5040_50400202_230_dialog_content = "사람이 충분히 강해지지 못하면, 스스로 행복을 찾을 능력을 얻지 못해요.\n결국 수동적으로 받기만 하는 사람이 되죠.",
  ui_story_5040_50400202_231_dialog_content = "그에 비한다면 어디서 누구와 사는지 같은 건 그리 큰 문제도 아닐 거예요.",
  ui_story_5040_50400202_232_dialog_content = "전 선생님께서도 이 점을 이해하실 거라 생각해요. 어떠세요?",
  ui_story_5040_50400202_233_dialog_content = "(예리아 씨가 무슨 말을 했을진 모르겠지만, 문제가 해결됐으니 잘됐지 뭐.)",
  ui_story_5040_50400301_1_dialog_content = "편지 왔습니다! 받아주세요!",
  ui_story_5040_50400301_2_dialog_content = "고마워, 키아. 이렇게 늦게까지 일하고 있어?",
  ui_story_5040_50400301_3_dialog_content = "이제 곧 관월제잖아요. 할 수 있는 데까지 최대한 배달해야죠.\n다들 편지를 애타게 기다리고 있을 테니까요.",
  ui_story_5040_50400301_4_dialog_content = "역시 신입이라 그런지 열심이네. 그럼 힘내.",
  ui_story_5040_50400301_5_dialog_content = "(휴... 벌써 시간이 이렇게 됐네.)",
  ui_story_5040_50400301_6_dialog_content = "(드디어 끝났구나. 오늘은 여기까지 해야지.)",
  ui_story_5040_50400301_7_dialog_content = "(타라 씨가 기억상실증에 걸렸다고 아도니스 씨가 낮에 그러시던데...\n혹시 어제 그 암귀와 관련이 있는 걸까?)",
  ui_story_5040_50400301_8_dialog_content = "(왠지 걱정이 되네. 돌아가는 길에 어제 그곳에 들러 봐야겠어.)",
  ui_story_5040_50400301_9_dialog_content = "(분명 이 근처였을 텐데...)",
  ui_story_5040_50400301_10_dialog_content = "(어라?)",
  ui_story_5040_50400301_11_dialog_content = "(여기 얼음은... 왜 보라색일까? 혹시 이게 어제 그 약의 흔적인 걸까?)",
  ui_story_5040_50400301_12_dialog_content = "(보라색 흔적이 숲속까지 이어져 있네.)",
  ui_story_5040_50400301_13_dialog_content = "(에라, 모르겠다... 가서 확인해 보자!)",
  ui_story_5040_50400301_14_dialog_content = "<color=#e8d9bb>까악── 까악──</color>",
  ui_story_5040_50400301_15_dialog_content = "(엄청 어둡네... 역시 돌아갈까... 조금 무서운데...)",
  ui_story_5040_50400301_16_dialog_content = "(잠깐만... 흔적이 여기서 끊겼다는 건...)",
  ui_story_5040_50400301_17_dialog_content = "아...",
  ui_story_5040_50400301_18_dialog_content = "<size=50>꺄아앗!</size>",
  ui_story_5040_50400301_19_dialog_content = "거, 거기 누구야?!",
  ui_story_5040_50400301_20_dialog_content = "도... 도와...",
  ui_story_5040_50400301_21_dialog_content = "도와... 줘...",
  ui_story_5040_50400301_22_dialog_content = "누, 누가 말하는 거죠?!",
  ui_story_5040_50400301_23_dialog_content = "나...나!",
  ui_story_5040_50400301_24_dialog_content = "암귀?!",
  ui_story_5040_50400301_25_dialog_content = "하...하지 마...",
  ui_story_5040_50400301_26_dialog_content = "해치지... 않아...",
  ui_story_5040_50400301_27_dialog_content = "네? 통용어를 할 수 있는 건가요? 당신... 어제 타라 씨를 공격한 암귀군요!",
  ui_story_5040_50400301_28_dialog_content = "나... 너... 해치지... 않아...",
  ui_story_5040_50400301_29_dialog_content = "오지 마세요! 뭘 하려는 거죠?!",
  ui_story_5040_50400301_30_dialog_content = "도...도와...",
  ui_story_5040_50400301_31_dialog_content = "도와...줘...",
  ui_story_5040_50400301_32_dialog_content = "네?",
  ui_story_5040_50400301_33_dialog_content = "나... 기억... 없어...",
  ui_story_5040_50400301_34_dialog_content = "나... 누군지... 몰라...",
  ui_story_5040_50400301_35_dialog_content = "무서워...",
  ui_story_5040_50400301_36_dialog_content = "너무... 무서워...",
  ui_story_5040_50400301_37_dialog_content = "자기가 누군지 모르겠다고요? 그럼 어젠 왜 우릴 습격한 거죠?",
  ui_story_5040_50400301_38_dialog_content = "습격... 안... 했어...",
  ui_story_5040_50400301_39_dialog_content = "물약이... 필요... 했어...",
  ui_story_5040_50400301_40_dialog_content = "물약?",
  ui_story_5040_50400301_41_dialog_content = "시장에... 숨어있을... 때...",
  ui_story_5040_50400301_42_dialog_content = "그 물약... 만능이라고... 들었어...",
  ui_story_5040_50400301_43_dialog_content = "그래서... 그... 물약으로... 기억... 찾고 싶어.",
  ui_story_5040_50400301_44_dialog_content = "하지만... 너희가... 가져갔어...",
  ui_story_5040_50400301_45_dialog_content = "그런 거였군요.",
  ui_story_5040_50400301_46_dialog_content = "근데 암귀가 어떻게 기억이 있는 거죠... 당신 설마 원래는 오로리안이었던 건가요?",
  ui_story_5040_50400301_47_dialog_content = "아마... 그래... 하지만... 잊어... 버렸어...",
  ui_story_5040_50400301_48_dialog_content = "나... 무서워...",
  ui_story_5040_50400301_49_dialog_content = "(다들 암귀와는 엮이지 않는 게 좋다고 해...\n하지만 왠지 거짓말을 하는 것 같지는 않아...)",
  ui_story_5040_50400301_50_dialog_content = "(근데 암귀를 도와줬다는 사실을 들키면 쿠리어 일도 할 수 없게 되겠지...?\n어쩌면 잡혀갈지도 몰라...)",
  ui_story_5040_50400301_51_dialog_content = "추워...",
  ui_story_5040_50400301_52_dialog_content = "으으... 정말!",
  ui_story_5040_50400301_53_dialog_content = "일어나요. 저랑 같이 가요.",
  ui_story_5040_50400301_54_dialog_content = "고마...워...!",
  ui_story_5040_50400301_55_dialog_content = "먼저 말해 두는데요. 이상한 행동을 하면 즉시 언령한테 시켜서 사람을 부를 거예요!",
  ui_story_5040_50400301_56_dialog_content = "응!",
  ui_story_5040_50400301_57_dialog_content = "...이렇게... 그리고...",
  ui_story_5040_50400301_58_dialog_content = "여기도 좀 더 가리죠.",
  ui_story_5040_50400301_59_dialog_content = "좋아요! 이 정도면 괜찮겠네요!",
  ui_story_5040_50400301_60_dialog_content = "된... 거야...?",
  ui_story_5040_50400301_61_dialog_content = "근데 정말 이 옷으로 할 건가요? 이 옷은 제가 전에 신부 들러리 할 때 입었던 드레스예요.",
  ui_story_5040_50400301_62_dialog_content = "근데 이렇게 입으니까 확실히 오로리안 같네요. 드레스가 좀 뜬금없긴 하지만요.",
  ui_story_5040_50400301_63_dialog_content = "고...마워... 드레스... 좋아.",
  ui_story_5040_50400301_64_dialog_content = "뭐, 됐어요. 마음에 든다면 입으세요.\n전 키아예요. 당신을 뭐라고 부를까요? 이름은 기억하고 있나요?",
  ui_story_5040_50400301_65_dialog_content = "모르...겠어.",
  ui_story_5040_50400301_66_dialog_content = "그럼 일단 세이블이라고 불러도 될까요?",
  ui_story_5040_50400301_67_dialog_content = "그...그래...",
  ui_story_5040_50400301_68_dialog_content = "옛날 일은 하나도 기억이 안 나는 건가요?",
  ui_story_5040_50400301_69_dialog_content = "응...",
  ui_story_5040_50400301_70_dialog_content = "계속 북방에 있었나요?",
  ui_story_5040_50400301_71_dialog_content = "아니... 아마... 아주 먼 곳에서... 왔어.",
  ui_story_5040_50400301_72_dialog_content = "그렇군요. 저도 생각 좀 해 볼게요.",
  ui_story_5040_50400301_73_dialog_content = "<color=#e8d9bb>다음날</color>",
  ui_story_5040_50400301_74_dialog_content = "준비됐어?",
  ui_story_5040_50400301_75_dialog_content = "아도니스 씨, 타라 씨, 이번 여행은 멀리 가게 될 테니까, 준비물을 잘 챙겨 줘.",
  ui_story_5040_50400301_76_dialog_content = "네! 청어 통조림, 사슴고기 통조림, 상어고기 통조림도 모두 한 달 치 챙겼습니다.",
  ui_story_5040_50400301_77_dialog_content = "건어물도 동결 건조 바다표범 고기에 단새우, 드래곤피시 껍질 말림 두 달 치가 있어요.",
  ui_story_5040_50400301_78_dialog_content = "그리고 급할 때 쓸 휴대용 난로와 망치, 칼, 삽, 주전자, 장화, 방한우비도...",
  ui_story_5040_50400301_79_dialog_content = "혹시나 해서 말하는 건데, 우린 백야성 가는 거지, 비경 탐사 가는 거 아니야.",
  ui_story_5040_50400301_80_dialog_content = "엄청나네... 대체 백야성을 어떤 곳이라고 생각한 거야?",
  ui_story_5040_50400301_81_dialog_content = "하지만 이번엔 백야성, 자난성, 레디젤 사막에 갈 거잖아요.\n그러니까 최대한 만반의 준비를 해야죠.",
  ui_story_5040_50400301_82_dialog_content = "그건 그렇긴 한데 아마 필요 없지 않을까?\n앞으로 가는 곳들 모두 음식이 부족할 일은 없을 테니까.",
  ui_story_5040_50400301_83_dialog_content = "......",
  ui_story_5040_50400301_84_dialog_content = "뭐야? 여행? 그것도 모르는 사람이랑?!",
  ui_story_5040_50400301_85_dialog_content = "타라, 진정해. 여행이라고는 하지만...\n사실 다 네가 빨리 기억을 되찾을 수 있게 하기 위해서야.",
  ui_story_5040_50400301_86_dialog_content = "설마 넌 예전 일들을 다시 떠올리고 싶지 않은 거야?",
  ui_story_5040_50400301_87_dialog_content = "당연히 기억하고 싶지. 하지만 이건 너무 터무니없잖아.",
  ui_story_5040_50400301_88_dialog_content = "게다가 내가 잃어버린 건 너에 대한 기억뿐이야.",
  ui_story_5040_50400301_89_dialog_content = "그건 그렇지만... 너와 나 사이의 추억은 내게도, 너한테도 매우 소중한 거야.",
  ui_story_5040_50400301_90_dialog_content = "음...",
  ui_story_5040_50400301_91_dialog_content = "물론 네 마음은 존중해. 하지만 난 이번 여행을 통해 네 기억을 되찾아 주고 싶어.",
  ui_story_5040_50400301_92_dialog_content = "넌 어떻게 생각해? 네가 싫다면 나도 억지로 권하지 않을게.",
  ui_story_5040_50400301_93_dialog_content = "(정말... 왜 결국 마지막엔 마음이 약해지는 걸까.)",
  ui_story_5040_50400301_94_dialog_content = "걱정하지 마, 타라 넌 내가 돌봐줄 테니까! 아무 걱정 안 해도 돼!",
  ui_story_5040_50400301_95_dialog_content = "넌 그냥 여행을 즐겨주면 돼.",
  ui_story_5040_50400301_96_dialog_content = "아는 사람도 아닌데 나한테 잘해준다고 감동 같은 건 안 해.",
  ui_story_5040_50400301_97_dialog_content = "난 집에 갈 거야.",
  ui_story_5040_50400301_98_dialog_content = "물론 집에 가야지. 마지막 목적지는 사막이거든.",
  ui_story_5040_50400301_99_dialog_content = "나머지 장소는 그냥 즐기면 돼.\n어떻게 하면 기억을 되찾을 수 있을지는 가면서 함께 생각하자. 어때?",
  ui_story_5040_50400301_100_dialog_content = "음... 알았어.",
  ui_story_5040_50400301_101_dialog_content = "그럼 준비됐으면 출발하자. 내가 백야성까지 바래다줄게.\n나도 마침 나로세르한테 가서 보고해야 하니까.",
  ui_story_5040_50400301_102_dialog_content = "PlayerName 씨! 잠시만요!",
  ui_story_5040_50400301_103_dialog_content = "어라?",
  ui_story_5040_50400301_104_dialog_content = "휴... 휴우... 겨우 따라잡았네요!",
  ui_story_5040_50400301_105_dialog_content = "어머, 북방의 아기새잖아? 숨차는 모습도 정말 귀엽다니까.",
  ui_story_5040_50400301_106_dialog_content = "예리아 장로님, 놀리지 마세요!\n크흠, 여러분 백야성 가는 거 맞죠? 저희도 함께 가도 될까요?",
  ui_story_5040_50400301_107_dialog_content = "「저희」?",
  ui_story_5040_50400301_108_dialog_content = "아기새가 말하는 「저희」라면, 암귀랑 똑 닮은 그 이상한 여자애를 말하는 걸까?",
  ui_story_5040_50400301_109_dialog_content = "어, 어떻게 사람한테 암귀를 닮았다고 할 수가 있어요?!",
  ui_story_5040_50400301_110_dialog_content = "이쪽은 세이블이라고 해요! 어, 음... 그러니까... 제 먼 친척이에요!",
  ui_story_5040_50400301_111_dialog_content = "아...안...녕...",
  ui_story_5040_50400301_112_dialog_content = "(이 여자애한테서 강한 다크매터가 느껴져. 절대 착각이 아니야.)",
  ui_story_5040_50400301_113_dialog_content = "(하지만 뭔가 이상한 점도 딱히 없어 보여... 일단은 상황을 지켜보자.)",
  ui_story_5040_50400301_114_dialog_content = "검은 아기새였구나. 게다가 옷도 참 특이하네.",
  ui_story_5040_50400301_115_dialog_content = "세, 세이블은 드레스를 아주 좋아해요!\n모처럼 놀러 가는 거라 열심히 꾸미고 왔거든요.",
  ui_story_5040_50400301_116_dialog_content = "(이유는 모르겠지만 세이블은 확실히 드레스를 좋아하는 것 같아...\n드레스에 무슨 사연이라도 있는 걸까?)",
  ui_story_5040_50400301_117_dialog_content = "너희도 백야성에 갈 거니?",
  ui_story_5040_50400301_118_dialog_content = "기념일도 됐고 해서 세이블을 여러 곳에 데려가 주고 싶어요.\n태워주시면 안 될까요? 마침 백야성으로 배달할 편지도 있거든요.",
  ui_story_5040_50400301_119_dialog_content = "물론 괜찮지. 그럼 준비됐으면 출발할까?",
  ui_story_5040_50400301_120_dialog_content = "<color=#e8d9bb>스카이워커호</color>",
  ui_story_5040_50400301_121_dialog_content = "근데 예리아 씨는 안 쉬어도 괜찮아요?",
  ui_story_5040_50400301_122_dialog_content = "후훗, 독서도 나한테는 휴식이야.",
  ui_story_5040_50400301_123_dialog_content = "조금도 피곤하지 않아.",
  ui_story_5040_50400301_124_dialog_content = "아이테르 군, 피곤하면 가서 자.",
  ui_story_5040_50400301_125_dialog_content = "예리아 씨는 대단하네요. 읽고 있는 책도 전 하나도 이해가 안 돼요.",
  ui_story_5040_50400301_126_dialog_content = "사람마다 전공이 다른 법이니까. 난 그저 고서를 좋아할 뿐이야.",
  ui_story_5040_50400301_127_dialog_content = "오로리안을 상대하는 것보다 훨씬 쉬운걸.",
  ui_story_5040_50400301_128_dialog_content = "네?",
  ui_story_5040_50400301_129_dialog_content = "참, 백야성에 도착하면 나로세르한테 가실 거죠?",
  ui_story_5040_50400301_130_dialog_content = "서로 해야 할 일도 있고, 돌아가면 먼저 상황도 설명해 줘야겠지.",
  ui_story_5040_50400301_131_dialog_content = "꺄아악!",
  ui_story_5040_50400301_132_dialog_content = "?!",
  ui_story_5040_50400301_133_dialog_content = "암귀예요! 예리아 장로님, PlayerName 씨, 조심하세요!",
  ui_story_5040_50400301_134_dialog_content = "사...살려줘...!",
  ui_story_5040_50400301_135_dialog_content = "콜로서스에 왜 암귀가 있어?! 아까 같이 탄 건가?",
  ui_story_5040_50400301_136_dialog_content = "이야기는 나중에 하고, 일단 더러운 녀석들부터 치워버리자.",
  ui_story_5040_50400302_1_dialog_content = "<color=#e8d9bb>암귀를 처리한 후, 일행은 잠시 휴식을 취했고. 잠시 후 무사히 백야성에 도착했다.</color>",
  ui_story_5040_50400302_2_dialog_content = "휴, 백야성 입성 검사는 정말 엄격하다니까. 다행히 우리한테는 그렇게 심하진 않았지만.",
  ui_story_5040_50400302_3_dialog_content = "(아이테르가 없었다면 세이블의 정체를 들켰을지도 몰라. 역시 따라오길 잘했어...)",
  ui_story_5040_50400302_4_dialog_content = "PlayerName 씨, 예리아 장로님!\n전 배달하는 김에 세이블을 데리고 구경 좀 시켜줄게요! 먼저 실례할게요!",
  ui_story_5040_50400302_5_dialog_content = "빠, 빨리도 가네!",
  ui_story_5040_50400302_6_dialog_content = "......",
  ui_story_5040_50400302_7_dialog_content = "우와... 여기가 바로 백야성인가요? 북방과는 전혀 다른 분위기네요!",
  ui_story_5040_50400302_8_dialog_content = "타라, 안 그래?",
  ui_story_5040_50400302_9_dialog_content = "...난 처음 온 것도 아닌데.",
  ui_story_5040_50400302_10_dialog_content = "그, 그렇구나.",
  ui_story_5040_50400302_11_dialog_content = "자, 일단 먼저 나로세르한테 가 보자.",
  ui_story_5040_50400302_12_dialog_content = "나로세르! 오랜만이야!",
  ui_story_5040_50400302_13_dialog_content = "어머... 아도니스!",
  ui_story_5040_50400302_14_dialog_content = "정말 오랜만이네요. 백야성엔 무슨 일이죠?\n노비오 선생님과 당신 부모님도 다들 잘 지내고 계신가요?",
  ui_story_5040_50400302_15_dialog_content = "응, 다들 잘 지내셔.",
  ui_story_5040_50400302_16_dialog_content = "이쪽이 바로 내가 편지에서 얘기했던 타라야.",
  ui_story_5040_50400302_17_dialog_content = "......",
  ui_story_5040_50400302_18_dialog_content = "나로세르, 우리가 백야성에 돌아온 건 말이지...",
  ui_story_5040_50400302_19_dialog_content = "<color=#e8d9bb>나로세르에게 상황 설명을 한 후──</color>",
  ui_story_5040_50400302_20_dialog_content = "어떻게 그런 일이 있을 수 있죠?",
  ui_story_5040_50400302_21_dialog_content = "기억을 잃는 마법의 물약 같은 건 처음 들어봐요.",
  ui_story_5040_50400302_22_dialog_content = "휴, 그래서 나도 곤란한 상황이야.",
  ui_story_5040_50400302_23_dialog_content = "제가 뭔가 도울 일이 있을까요? 우린 친구잖아요. 부담 없이 말해 보세요.",
  ui_story_5040_50400302_24_dialog_content = "사실 우린 예리아 씨의 제안으로 각 도시의 쿠리어 길드 관월제 행사에\n참가해서 깃털 도장을 모으기로 했어.",
  ui_story_5040_50400302_25_dialog_content = "그렇게 여러 곳을 둘러보다 보면 타라의 기억상실을 치료할 단서를 찾을 수 있을지도 모르니까.",
  ui_story_5040_50400302_26_dialog_content = "아, 깃털 도장 말이군요.",
  ui_story_5040_50400302_27_dialog_content = "확실히 쿠리어 길드에선 매년 관월제 날에 젊은 커플을 위한\n도전 이벤트를 개최하고 있어요.",
  ui_story_5040_50400302_28_dialog_content = "다만...",
  ui_story_5040_50400302_29_dialog_content = "왜 그래? 뭐 곤란한 일이라도 있어?",
  ui_story_5040_50400302_30_dialog_content = "우린 오래 알고 지낸 사이잖아요.\n제가 윈터 팰리스에서 여왕 폐하의 가르침을 받을 때, 자주 노비오 선생님과 당신을 봤었죠,",
  ui_story_5040_50400302_31_dialog_content = "그래서 전 당신이 타라 씨를 평생의 반려자로 삼겠다는 결심이\n심사숙고 끝에 내린 결론이었으면 좋겠네요.",
  ui_story_5040_50400302_32_dialog_content = "관월제도, 쿠리어 길드 행사도 어디까지나 형식일 뿐이니까요.",
  ui_story_5040_50400302_33_dialog_content = "응, 알고 있어.",
  ui_story_5040_50400302_34_dialog_content = "관월제를 기회로 삼고 싶은 거라면, 저도 두 사람을 도울게요.",
  ui_story_5040_50400302_35_dialog_content = "고마워, 나로세르!",
  ui_story_5040_50400302_36_dialog_content = "그리고 관월제 이벤트라면...",
  ui_story_5040_50400302_37_dialog_content = "이건 올해 쿠리어 길드가 관월제를 기념해서 발행할 우표예요.\n이걸 다 팔면 도전에 성공한 것으로 인정돼요.",
  ui_story_5040_50400302_38_dialog_content = "알았어, 별거 아니네! 그렇지, 타라?",
  ui_story_5040_50400302_39_dialog_content = "뭐, 그렇겠지.",
  ui_story_5040_50400302_40_dialog_content = "근데 난 그런 섬세한 업무 같은 건 해본 적 없어.",
  ui_story_5040_50400302_41_dialog_content = "우리 둘이 힘을 합치면 분명히 문제없을 거야.\n자, 지금 바로 팔러 가자!",
  ui_story_5040_50400302_42_dialog_content = "그럼 행운을 빌게.",
  ui_story_5040_50400302_43_dialog_content = "수고하셨어요, PlayerName 님, 예리아.",
  ui_story_5040_50400302_44_dialog_content = "다만 아도니스는 왠지 다른 도시의 쿠리어 길드에도 가려는 것 같네요.\nPlayerName 님, 번거로우시겠지만 동행을 부탁드려도 될까요?",
  ui_story_5040_50400302_45_dialog_content = "물론이지! 돕는 김에 끝까지 도와야지.",
  ui_story_5040_50400302_46_dialog_content = "그럼 넌 가서 좀 쉬어 둬.",
  ui_story_5040_50400302_47_dialog_content = "앞으로 있을 시험은 내가 봐 주면 되니까.",
  ui_story_5040_50400302_48_dialog_content = "그리고 예리아는 잠깐 저랑 얘기 좀 해요.",
  ui_story_5040_50400302_49_dialog_content = "......",
  ui_story_5040_50400302_50_dialog_content = "저한테 할 말 없나요?",
  ui_story_5040_50400302_51_dialog_content = "후훗, 무슨 말?",
  ui_story_5040_50400302_52_dialog_content = "시치미 떼지 마세요. 레디젤 렌치에서 백야성으로 보낸 이 소포들은 다 뭐죠?",
  ui_story_5040_50400302_53_dialog_content = "음~ 뭘까? 사실 나도 딱히 들여다보진 않았어.",
  ui_story_5040_50400302_54_dialog_content = "제대로 확인도 안 하고 배송을 시키다니... 덕분에 저랑 에호랑 정신없이 바빴잖아요.",
  ui_story_5040_50400302_55_dialog_content = "관월제는 가뜩이나 배송 물량도 많아서, 지금 백야성 쿠리어 길드는 마비 직전이에요.",
  ui_story_5040_50400302_56_dialog_content = "상부에는 보고하지 않았어요. 보고했으면 당신은 분명히 불려 가서 잔소리를 들었겠죠.",
  ui_story_5040_50400302_57_dialog_content = "너한테 빚진 셈 쳐. 그래서 내가 대신 북방에 다녀왔잖아.",
  ui_story_5040_50400302_58_dialog_content = "휴, 아도니스가 저런 일을 겪을 줄은 몰랐네요.",
  ui_story_5040_50400302_59_dialog_content = "두 사람 이번 일, 당신이 끝까지 잘 좀 도와주세요.",
  ui_story_5040_50400302_60_dialog_content = "정말 귀찮네... 나도 이해가 안 된다니까.\n분명히 안 어울리는데 왜 굳이 서로 함께하려고 하는 걸까.",
  ui_story_5040_50400302_61_dialog_content = "당신도 항상 모든 개인이란 복잡한 존재라고 말하곤 했잖아요?",
  ui_story_5040_50400302_62_dialog_content = "당신도 이해할 거예요, 예리아. 우린 그 누구도 영원히 혼자 살아갈 순 없어요.",
  ui_story_5040_50400302_63_dialog_content = "타라, 여기 있는 우표들은 개별 포장하면 돼.",
  ui_story_5040_50400302_64_dialog_content = "기억나? 넌 매년 나한테 관월제 우표를 보내줬잖아.\n난 전부 소중히 간직하고 있었어.",
  ui_story_5040_50400302_65_dialog_content = "그래? 기억 안 나.",
  ui_story_5040_50400302_66_dialog_content = "괜찮아. 앞으로는 내가 너한테 우표를 보낼 테니까.\n그나저나 올해 디자인도 꽤 멋지네.",
  ui_story_5040_50400302_67_dialog_content = "앗... 봉투!",
  ui_story_5040_50400302_68_dialog_content = "조심해!",
  ui_story_5040_50400302_69_dialog_content = "다행이야, 땅에는 안 떨어졌네.",
  ui_story_5040_50400302_70_dialog_content = "나한테 이런 섬세한 일은 무리야. 항상 잘 못했다고. 총 같은 거 팔아먹는 거면 또 모를까.",
  ui_story_5040_50400302_71_dialog_content = "아하하, 물론 그럴 수 있어. 사람마다 잘하는 게 다른 거잖아.\n다섯 손가락도 저마다 다르게 생겼는걸.",
  ui_story_5040_50400302_72_dialog_content = "그럼 우표 포장은 내가 할 테니까 넌 손님을 맡아줘.",
  ui_story_5040_50400302_73_dialog_content = "그거라면 아마 문제없을 거야.",
  ui_story_5040_50400302_74_dialog_content = "<color=#e8d9bb>얼마 후</color>",
  ui_story_5040_50400302_75_dialog_content = "저도 올해 기념우표 하나 주세요!",
  ui_story_5040_50400302_76_dialog_content = "내 건 아직이야?",
  ui_story_5040_50400302_77_dialog_content = "조금만 더 기다려주세요. 관월제 우표는 기념 한정판이니까 꼼꼼하게 잘 포장해야죠.",
  ui_story_5040_50400302_78_dialog_content = "자~ 여기 받으세요!",
  ui_story_5040_50400302_79_dialog_content = "타라, 일은 할만해?",
  ui_story_5040_50400302_80_dialog_content = "입만 떠드는 건데 어려울 게 뭐 있어. 넌 우표에 더 신경 써.",
  ui_story_5040_50400302_81_dialog_content = "후훗, 장사가 잘되는 모양이네.",
  ui_story_5040_50400302_82_dialog_content = "응! 아직까진 잘 되고 있어.",
  ui_story_5040_50400302_83_dialog_content = "어디 보자... 얼마 안 남은 것 같네, 다행이야.",
  ui_story_5040_50400302_84_dialog_content = "자, 마지막 1세트... 끝!",
  ui_story_5040_50400302_85_dialog_content = "휴, 어떻게든 끝났네.",
  ui_story_5040_50400302_86_dialog_content = "축하해.",
  ui_story_5040_50400302_87_dialog_content = "그거 축하에 진심이 전혀 안 느껴지잖아.",
  ui_story_5040_50400302_88_dialog_content = "하암... 실례합니다. 여기가 쿠리어 길드 우표를 파는 곳인가요?",
  ui_story_5040_50400302_89_dialog_content = "맞아요. 근데 어쩌죠? 마지막 하나가 마침 방금 팔렸거든요.",
  ui_story_5040_50400302_90_dialog_content = "올해 우표도 무척 귀엽지만, 제가 사고 싶은 건 다른 거예요.",
  ui_story_5040_50400302_91_dialog_content = "혹시 작년 관월제 기념우표는 아직 남아있을까요?\n괜찮다면... 제가 비싼 값에 사고 싶네요.",
  ui_story_5040_50400302_92_dialog_content = "그건...",
  ui_story_5040_50400302_93_dialog_content = "저희는 임시로 일을 돕는 거라서 잘 모르겠네요...\n예리아 씨, 혹시 아세요?",
  ui_story_5040_50400302_94_dialog_content = "쿠리어 길드 우표는 재발행되지 않아. 재고도 없고.",
  ui_story_5040_50400302_95_dialog_content = "공식 경로로 입수하는 건 불가능해.",
  ui_story_5040_50400302_96_dialog_content = "그런가요... 이걸 어쩌죠...",
  ui_story_5040_50400302_97_dialog_content = "무슨 곤란한 일이라도 있으신가요?",
  ui_story_5040_50400302_98_dialog_content = "휴... 사실 전 친구의 부탁을 받고 우표를 사러 온 거예요.",
  ui_story_5040_50400302_99_dialog_content = "그 친구의 애인은 일루미나에 살고 있는데,\n친구는 매년 애인에게 관월제 우표를 보냈어요.",
  ui_story_5040_50400302_100_dialog_content = "다만 친구의 가문은 보수적이라서, 두 사람 사이를 심하게 반대하고 있어요.",
  ui_story_5040_50400302_101_dialog_content = "그래서 제게 부탁해서 몰래 우표를 사서 편지를 보낼 수밖에 없어요.",
  ui_story_5040_50400302_102_dialog_content = "으음~ 딱 백야성다운 느낌이네.",
  ui_story_5040_50400302_103_dialog_content = "어? 백야성에도 우표를 보내는 풍습이 있어?",
  ui_story_5040_50400302_104_dialog_content = "백야성에서는 관월제가 되면 연인끼리 서로 우표를 보내.\n다만 귀족들 사이에서는 좀 더 사치스러운 방법이 있다고 들었어.",
  ui_story_5040_50400302_105_dialog_content = "으음~ 전 그런 요란한 낭비보다는 이불 속에서 잠이나 더 자는 게 좋은걸요.",
  ui_story_5040_50400302_106_dialog_content = "아무튼 지금 문제는 그 친구의 애인이 왠지 작년 기념우표를\n실수로 잃어버린 것 같다는 거예요.",
  ui_story_5040_50400302_107_dialog_content = "그 애인은 무척 속상해하면서 자책하고 있다고 해요.\n그래서 친구는 애인을 달래주려고 제게 같은 우표를 다시 사달라고 부탁했어요.",
  ui_story_5040_50400302_108_dialog_content = "고작 우표잖아요. 다른 걸로 대신하면 안 되는 건가요?",
  ui_story_5040_50400302_109_dialog_content = "그럴 순 없어. 추억이 담긴 물건일 거잖아.\n그건 어떤 호화로운 선물로도 대신할 수 없는 거야.",
  ui_story_5040_50400302_110_dialog_content = "백야성 귀족과 일루미나의 여자애라... 재미있네.",
  ui_story_5040_50400302_111_dialog_content = "분명 어려움도 많았겠지.",
  ui_story_5040_50400302_112_dialog_content = "결코 갈 수 없는 길까진 아니지만, 확실히 험난한 길이겠죠~",
  ui_story_5040_50400302_113_dialog_content = "그 친구는 이미 차근차근 부모님과 친구들을 설득해 왔어요.\n그렇게 해서 저들에게 자신의 결심을 전한 거죠.",
  ui_story_5040_50400302_114_dialog_content = "다만, 아직은 시간이 더 걸릴 거예요.",
  ui_story_5040_50400302_115_dialog_content = "백야성은 역시 듣던 대로 끼리끼리의 결혼을 고집하는구나.",
  ui_story_5040_50400302_116_dialog_content = "그런가요? 하지만 양쪽 모두 출신이 비슷한 대귀족이라 해도\n꼭 행복해진다는 보장은 없어요.",
  ui_story_5040_50400302_117_dialog_content = "전 심판소에서 일하고 있어요.\n거기 있다 보면 귀족들의 이혼 소송 사건을 꾸준히 볼 수 있죠.",
  ui_story_5040_50400302_118_dialog_content = "어느 사건이나 저마다 우여곡절이 있고, 귀족 간의 이해관계가\n복잡하게 얽혀서 해결하기가 쉽지 않아요.",
  ui_story_5040_50400302_119_dialog_content = "그래서 다들 참여하기 싫어하는 소송이에요~",
  ui_story_5040_50400302_120_dialog_content = "귀족들도 감정 문제로 고민이 많은 모양이네요.",
  ui_story_5040_50400302_121_dialog_content = "맞아요. 그래서 전 자기 마음에 솔직해지는 게 가장 좋다고 생각해요.",
  ui_story_5040_50400302_122_dialog_content = "무사안일을 위해 비슷한 출신의 사람과 함께한다고 꼭 행복할 수 있는 건 아니니까요.",
  ui_story_5040_50400302_123_dialog_content = "백야성 귀족의 입에서 그런 말을 듣다니 신기하네.",
  ui_story_5040_50400302_124_dialog_content = "사람마다 선택하는 길이 다른 거라고 할 수 있겠죠.\n애초에 사랑은 한마디로 정의할 수 있는 게 아니니까요. 좋은 건 그냥 좋은 거예요.",
  ui_story_5040_50400302_125_dialog_content = "누군가를 좋아하는 감정은 막을 수 없어요.\n그 사람이 어디에 살든, 출신이 무엇이든 말이죠.",
  ui_story_5040_50400302_126_dialog_content = "그 점은 저도 확실히 느꼈거든요.",
  ui_story_5040_50400302_127_dialog_content = "아주 멋진 말씀이네요! 저도 전적으로 동의해요!",
  ui_story_5040_50400302_128_dialog_content = "호오? 그럼 우리 귀여운 아가씨도 마음에 둔 사람이 있는 걸까?",
  ui_story_5040_50400302_129_dialog_content = "그런 건 아니에요. 그저 얼마 전에 우연히 한 복슬복슬하고 재미있는 녀석을 만났거든요.",
  ui_story_5040_50400302_130_dialog_content = "게다가 그 녀석은 통용어를 할 수 있었어요. 정말 신기한 일이었죠.",
  ui_story_5040_50400302_131_dialog_content = "어제 그 녀석에게 편지를 보냈는데, 언제 답장을 받을 수 있을지 모르겠네요...",
  ui_story_5040_50400302_132_dialog_content = "예리아 씨, 이 아가씨의 친구분을 도울 방법이 없을까요?",
  ui_story_5040_50400302_133_dialog_content = "......",
  ui_story_5040_50400302_134_dialog_content = "나도 딱히 방법은 없어. 대신...",
  ui_story_5040_50400302_135_dialog_content = "그 친구가 어느 정도 대가를 치를 생각이 있다면, 움브라톤의 알루라에게 물어보라고 해.\n알루라는 굉장한 수집가거든.",
  ui_story_5040_50400302_136_dialog_content = "우표 정도는 일도 아닐 거야.",
  ui_story_5040_50400302_137_dialog_content = "그렇군요. 고마워요, 큰 도움이 됐네요!",
  ui_story_5040_50400302_138_dialog_content = "전 그럼 졸려지기 전에 얼른 움브라톤에 다녀와야겠어요.",
  ui_story_5040_50400302_139_dialog_content = "예리아는 정말 뭐든지 다 아는구나.",
  ui_story_5040_50400302_140_dialog_content = "원하는 물건을 구할 수 있으면 좋겠네.",
  ui_story_5040_50400302_141_dialog_content = "뭐, 이걸로 우리 임무도 끝났으니까, 돌아가서 도장 찍어달라고 하자!",
  ui_story_5040_50400302_142_dialog_content = "응...",
  ui_story_5040_50400302_143_dialog_content = "타라? 왜 그래? 어디 불편해?",
  ui_story_5040_50400302_144_dialog_content = "아니, 아무것도 아니야.",
  ui_story_5040_50400302_145_dialog_content = "......",
  ui_story_5040_50400302_146_dialog_content = "<color=#e8d9bb>같은 시간</color>",
  ui_story_5040_50400302_147_dialog_content = "결국 아무 수확도 없었네요...",
  ui_story_5040_50400302_148_dialog_content = "역시 아무것도 생각나지 않는 건가요?",
  ui_story_5040_50400302_149_dialog_content = "미...미안...해...",
  ui_story_5040_50400302_150_dialog_content = "사과 안 해도 돼요. 당신이 잘못한 것도 없잖아요.",
  ui_story_5040_50400302_151_dialog_content = "그럼 단서가 될 만한 다른 건 없을까요...?",
  ui_story_5040_50400302_152_dialog_content = "아... 저...저거...",
  ui_story_5040_50400302_153_dialog_content = "네?",
  ui_story_5040_50400302_154_dialog_content = "저거... 손에... 든... 거...",
  ui_story_5040_50400302_155_dialog_content = "누가요? 뭘 들고 있죠?",
  ui_story_5040_50400302_156_dialog_content = "남자...",
  ui_story_5040_50400302_157_dialog_content = "우...표...",
  ui_story_5040_50400302_158_dialog_content = "우표? 방금 지나간 사람 말인가요? 저건 관월제 우표예요.",
  ui_story_5040_50400302_159_dialog_content = "저걸 보고 뭔가 생각난 건가요?",
  ui_story_5040_50400302_160_dialog_content = "나... 있어...",
  ui_story_5040_50400302_161_dialog_content = "네? 어디서 얻은 거죠? 이건 아주 오래전에 발행된 우표 같네요!",
  ui_story_5040_50400302_162_dialog_content = "나... 아마... 많이... 가지고 있어...",
  ui_story_5040_50400302_163_dialog_content = "뭘요? 비슷한 우표를요?",
  ui_story_5040_50400302_164_dialog_content = "응...",
  ui_story_5040_50400302_165_dialog_content = "우표를 많이 가지고 있었다는 건, 자주 편지를 보냈다는 뜻일까요?",
  ui_story_5040_50400302_166_dialog_content = "잘됐네요. 그럼 같이 쿠리어 길드에 가서 수취인불명 우편을 찾아봐요.\n뭔가 찾을 수 있을지도 모르잖아요.",
  ui_story_5040_50400302_167_dialog_content = "고, 고마워... 키...아...",
  ui_story_5040_50400302_168_dialog_content = "<color=#e8d9bb>얼마 후</color>",
  ui_story_5040_50400302_169_dialog_content = "없나요?",
  ui_story_5040_50400302_170_dialog_content = "전부... 아...니야...",
  ui_story_5040_50400302_171_dialog_content = "음, 전에 살던 곳이 백야성이 아니었을지도 모르겠네요.",
  ui_story_5040_50400302_172_dialog_content = "그래도 뭔가 단서가 생겼으니, 아무것도 없는 상태로 찾는 것보다는 훨씬 낫겠죠.",
  ui_story_5040_50400302_173_dialog_content = "PlayerName 씨를 따라 일루미나 지부랑 레디젤 렌치 지부에도 가 보기로 해요.",
  ui_story_5040_50400302_174_dialog_content = "걱정하지 마요. 분명히 찾을 수 있을 거예요.",
  ui_story_5040_50400302_175_dialog_content = "키...아...",
  ui_story_5040_50400302_176_dialog_content = "고마, 워.",
  ui_story_5040_50400302_177_dialog_content = "왜, 왜... 이렇게... 날... 도와줘?",
  ui_story_5040_50400302_178_dialog_content = "저도 잘 모르겠어요. 아마 곤란한 사람을 내버려 둘 수 없어서 그런 거겠죠.",
  ui_story_5040_50400302_179_dialog_content = "(나 아무래도 정신이 나간 게 분명해... 암귀를 돕는다니...\n대체 무슨 생각을 하고 있는 거야?!)",
  ui_story_5040_50400302_180_dialog_content = "(이럴 때 에메랄드 선생님이라면 어떻게 하셨을까...?)",
  ui_story_5040_50400401_1_dialog_content = "<color=#e8d9bb>아도니스 일행이 무사히 임무를 마치고 나로세르에게 보고한 뒤</color>",
  ui_story_5040_50400401_2_dialog_content = "이게 쿠리어 길드 깃털 도장이야? 처음 봐.",
  ui_story_5040_50400401_3_dialog_content = "아주 정교하게 새겨진 도장이군요!",
  ui_story_5040_50400401_4_dialog_content = "타라, 이것 좀 봐!",
  ui_story_5040_50400401_5_dialog_content = "...뭐야, 친한 척하지 마.",
  ui_story_5040_50400401_6_dialog_content = "깃털 도장은 아주 큰 가치가 있는 건 아니지만, 기념의 의미는 있는 물건이야.",
  ui_story_5040_50400401_7_dialog_content = "예전에 아직 길드가 세워지기 전부터 쿠리어는 많은 곳에서 기쁨을 상징했거든.",
  ui_story_5040_50400401_8_dialog_content = "귀족들의 결혼식에도 쿠리어를 부르나요?",
  ui_story_5040_50400401_9_dialog_content = "백야성 귀족들이야말로 풍습에 집착하는 녀석들이야.\n심지어 거금을 주고서라도 쿠리어를 입회인으로 부르는 귀족도 있어.",
  ui_story_5040_50400401_10_dialog_content = "그것 역시 쿠리어 길드가 그 풍습을 다른 이벤트로 대체하려는 이유 중 하나야.",
  ui_story_5040_50400401_11_dialog_content = "특히 백야성은 관월제가 기원한 곳이기 때문에, 풍습도 더 깊게 뿌리내리고 있어.",
  ui_story_5040_50400401_12_dialog_content = "이상해. 사막에서는 그런 기념일 같은 건 전혀 신경 안 쓰는데.",
  ui_story_5040_50400401_13_dialog_content = "격조 있고 좋지 않아? 낭만적이잖아.",
  ui_story_5040_50400401_14_dialog_content = "백야성 같은 계급사회에서 의식이란 지배 계급이 하층 계급을 제어하는 수단이야.",
  ui_story_5040_50400401_15_dialog_content = "그렇기 때문에 더 중시하는 거지.",
  ui_story_5040_50400401_16_dialog_content = "심오한 이야기네요...",
  ui_story_5040_50400401_17_dialog_content = "예리아는 항상 내가 모르는 소리만 한다니까.",
  ui_story_5040_50400401_18_dialog_content = "그럼 다음은...",
  ui_story_5040_50400401_19_dialog_content = "예리아, 잠깐 산책이나 하자. 기분전환 좀 하고 싶어.",
  ui_story_5040_50400401_20_dialog_content = "그럼 나도...",
  ui_story_5040_50400401_21_dialog_content = "조용히 있고 싶으니까 PlayerName 네가 그쪽 좀 데려 가.",
  ui_story_5040_50400401_22_dialog_content = "알겠어. 나야 뭐 상관없지만.",
  ui_story_5040_50400401_23_dialog_content = "......",
  ui_story_5040_50400401_24_dialog_content = "하아...",
  ui_story_5040_50400401_25_dialog_content = "연극에 지친 거야?",
  ui_story_5040_50400401_26_dialog_content = "내가 계속 이래도 되는 건지 모르겠어.\n왠지 아도니스는 내가 정말로 기억상실증이라고 믿는 것 같아.",
  ui_story_5040_50400401_27_dialog_content = "너무 혼란스러워. 함께 우표를 팔았을 때의 아도니스는...\n내가 아는 세심하고 상냥한 아도니스였어.",
  ui_story_5040_50400401_28_dialog_content = "하지만 그렇다고 해서 우리 사이의 문제가 해결되는 것도 아니고,\n중요한 일 앞에선 어차피 또 약해지고 소심해질 거야.",
  ui_story_5040_50400401_29_dialog_content = "어쩌면 우린 애초부터 전혀 다른 사람들이라서, 함께하지 말았어야 했을지도 몰라...",
  ui_story_5040_50400401_30_dialog_content = "그치만 난 아직 아도니스가 좋아서, 이 사실을 인정하고 싶지 않은 거겠지.",
  ui_story_5040_50400401_31_dialog_content = "우린 자신이 어떤 사람이 될지는 결정할 수 있지만, 다른 사람의 생각을 조종할 순 없어.",
  ui_story_5040_50400401_32_dialog_content = "스스로 누군가와 친밀한 관계가 되겠다고 선택했다면, 그에 따른 결과도 받아들여야 해.",
  ui_story_5040_50400401_33_dialog_content = "감정이 깊어질수록, 잃었을 때의 아픔도 클 테니까.",
  ui_story_5040_50400401_34_dialog_content = "...너도 그런 감정이 있었어?",
  ui_story_5040_50400401_35_dialog_content = "당연히 없었지. 상처받을 줄 알면서 뭐 하러 시작해?",
  ui_story_5040_50400401_36_dialog_content = "하지만 즐거움도 많았는걸. 아도니스랑 같이 있는 대부분의 시간이 즐거웠어.",
  ui_story_5040_50400401_37_dialog_content = "그건 모종의 정서적 결핍이 일으키는 감정이 투사되는 거야.\n본질적으로는 그저 가치의 교환일 뿐이라고.",
  ui_story_5040_50400401_38_dialog_content = "그리고 넌 상대가 주는 가치가 이젠 네 기대에 미치지 못한다고 생각하겠지. 안 그래?",
  ui_story_5040_50400401_39_dialog_content = "난...",
  ui_story_5040_50400401_40_dialog_content = "그런 건 몰라. 그래도 우리 사이의 감정을 그렇게 노골적으로 표현하고 싶진 않아.",
  ui_story_5040_50400401_41_dialog_content = "마음대로 해.",
  ui_story_5040_50400401_42_dialog_content = "다만 자신이 뭘 원하는지는 직접 겪어봐야 알 때가 많아.\n이미 이렇게 된 이상, 너도 조급해할 건 없어.",
  ui_story_5040_50400401_43_dialog_content = "어차피 네 일인데, 남들이 뭐라고 하든 상관없잖아.",
  ui_story_5040_50400401_44_dialog_content = "그냥 천천히 지켜보고, 네 마음이 가는 대로 결정하면 돼.",
  ui_story_5040_50400401_45_dialog_content = "......",
  ui_story_5040_50400401_46_dialog_content = "여기가 움브라톤이야. 백야성과는 분위기가 완전 다르지?",
  ui_story_5040_50400401_47_dialog_content = "그렇네요...",
  ui_story_5040_50400401_48_dialog_content = "봐, 백야성은 이 바로 위에 있어.",
  ui_story_5040_50400401_49_dialog_content = "움브라톤 사람들한테 이런 기념일은 아마 물건을 팔아먹을 절호의 기회일걸.",
  ui_story_5040_50400401_50_dialog_content = "여긴 이상한 사람도 많지만, 대신 재밌는 것도 많아.",
  ui_story_5040_50400401_51_dialog_content = "아도니스 씨는 뭐 관심 있는 거 있어?",
  ui_story_5040_50400401_52_dialog_content = "......",
  ui_story_5040_50400401_53_dialog_content = "(이런, 완전히 의욕을 잃었네.)",
  ui_story_5040_50400401_54_dialog_content = "휴... 이제 정말 어떻게 해야 할지 모르겠어요.",
  ui_story_5040_50400401_55_dialog_content = "왠지 뭘 해도 전부 틀린 것 같아요.\n제가 앞으로 어떻게 해야 할지 알 수 있게... 정말 조금이라도 변화가 있었으면 좋겠는데요...",
  ui_story_5040_50400401_56_dialog_content = "......",
  ui_story_5040_50400401_57_dialog_content = "저흰 예전에는 뭐든지 얘기하고, 서로 모르는 세상을 알아가며 정말 즐거웠어요...\n그런데 지금은 왜 이렇게 돼버린 걸까요...",
  ui_story_5040_50400401_58_dialog_content = "PlayerName 씨, 아이테르라면 주변에 아시는 여성분들도 많겠죠?\n지금 제 마음을 이해하실 수 있나요?",
  ui_story_5040_50400401_59_dialog_content = "벼, 별로 그렇지도 않은데...",
  ui_story_5040_50400401_60_dialog_content = "근데... 난 두 사람의 감정이 충분히 깊다면,\n어떤 어려움이라도 이겨낼 수 있을 거라 생각해.",
  ui_story_5040_50400401_61_dialog_content = "나도 좋은 친구가 둘 있는데, 함께 정말 많은 어려움을 극복해 왔어.\n심지어 목숨이 위험한 순간들도 함께 헤쳐 나왔고 말이야.",
  ui_story_5040_50400401_62_dialog_content = "우린 그러면서 점점 서로를 믿게 됐고, 서로를 위해 희생하는 것조차 두려워하지 않게 됐어.",
  ui_story_5040_50400401_63_dialog_content = "난 두 사람도 분명히 서로 그럴 거라 생각해.",
  ui_story_5040_50400401_64_dialog_content = "저, 저도 물론 타라를 위해서라면 뭐든지 할 수 있어요. 목숨을 바칠 수도 있고요.",
  ui_story_5040_50400401_65_dialog_content = "하지만 전 성격이 우유부단하고, 바로 결정을 내릴 수 없는 것도 많아서...\n타라는 제가 남자답지 않다고 생각하겠죠.",
  ui_story_5040_50400401_66_dialog_content = "그렇게 말하면 안 돼. 성격은 사람마다 다른 거잖아.\n게다가 남자가 꼭 어때야 한다고 누가 정했는데?",
  ui_story_5040_50400401_67_dialog_content = "아도니스 씨가 타라 씨 마음에 드니까 두 사람이 함께할 수 있었던 거잖아.\n그리고 세상에 완벽한 사람은 없어.",
  ui_story_5040_50400401_68_dialog_content = "크흑... 타라도 그렇게 생각해 줬으면 얼마나 좋았을까요!",
  ui_story_5040_50400401_69_dialog_content = "자, 자, 울지 말고.",
  ui_story_5040_50400401_70_dialog_content = "오오오~",
  ui_story_5040_50400401_71_dialog_content = "이야, 그림 좋네.",
  ui_story_5040_50400401_72_dialog_content = "영감이 떠올랐어! 실버!",
  ui_story_5040_50400401_73_dialog_content = "세상의 관습에 얽매여 낮에는 떳떳하게 서로를 만날 수 없는 두 사람...",
  ui_story_5040_50400401_74_dialog_content = "지금도 떳떳하게 껴안고 있는데?",
  ui_story_5040_50400401_75_dialog_content = "연인들에게 있어서 가장 중요한 관월제 날조차,\n움브라톤의 으슥한 구석에서 밀회할 수밖에 없는 처지...",
  ui_story_5040_50400401_76_dialog_content = "여기 사람 많은데?",
  ui_story_5040_50400401_77_dialog_content = "난 저 친구들을 위해 뭐라도 힘이 돼 주고 싶어.\n겸사겸사 비즈니스 기회도 잡고 말이야! 어때, 좋은 생각이지?",
  ui_story_5040_50400401_78_dialog_content = "그래, 참 좋네.",
  ui_story_5040_50400401_79_dialog_content = "야, 너희 지금 무슨 오해를...",
  ui_story_5040_50400401_80_dialog_content = "거기 형씨, 느낌 좋은데? 이름이 어떻게 되시나?",
  ui_story_5040_50400401_81_dialog_content = "저, 저요? 아도니스라고 하는데요.",
  ui_story_5040_50400401_82_dialog_content = "아도니스, 당신 꽤 분위기 있는 사람이네. 옆에 있는 녀석이랑은 확실히 차이가 있어.",
  ui_story_5040_50400401_83_dialog_content = "가만히 있는 나는 왜 까는데?",
  ui_story_5040_50400401_84_dialog_content = "넌 사랑하는 사람을 위해서라면 무엇이든 할 수 있는 타입이겠지. 확실히 알 수 있다고.",
  ui_story_5040_50400401_85_dialog_content = "나도, 내 막대사탕도 느꼈어.",
  ui_story_5040_50400401_86_dialog_content = "그럼 군말은 생략하고, 우린 관월제를 기념해서 아주 희귀한 그림들을 들여왔는데,\n그중 한 작품이 너한테 아주 잘 어울릴 것 같아.",
  ui_story_5040_50400401_87_dialog_content = "함께할 수 없는 연인들의 사랑을 다룬 그림이지.",
  ui_story_5040_50400401_88_dialog_content = "지금 마침 관월제 특별 행사를 하고 있어서 할인가에 제공하고 있다고!",
  ui_story_5040_50400401_89_dialog_content = "아, 그게... 전...",
  ui_story_5040_50400401_90_dialog_content = "알고 있어. 갖고 싶다는 거지? 맞지?",
  ui_story_5040_50400401_91_dialog_content = "그런 것 같네.",
  ui_story_5040_50400401_92_dialog_content = "전...",
  ui_story_5040_50400401_93_dialog_content = "어이, 너희 둘! 거기까지 해!",
  ui_story_5040_50400401_94_dialog_content = "움브라톤에 처음 온 사람을 놀리지 말라고!",
  ui_story_5040_50400401_95_dialog_content = "PlayerName, 정직한 사람은 바르게 돈을 버는 법이야.\n우린 그저 합리적인 비즈니스 토크 중이었다고.",
  ui_story_5040_50400401_96_dialog_content = "누가 봐도 비합리적이잖아!",
  ui_story_5040_50400401_97_dialog_content = "제대로 반박해주고 싶지만, 지금 무슨 소리가 들렸어.",
  ui_story_5040_50400401_98_dialog_content = "<size=45>꺄아아악!</size>",
  ui_story_5040_50400401_99_dialog_content = "뭐죠?!",
  ui_story_5040_50400401_100_dialog_content = "아, 암귀가 나타났어요!",
  ui_story_5040_50400401_101_dialog_content = "이건 또 어디서 온 암귀야?",
  ui_story_5040_50400401_102_dialog_content = "<size=45>그어어──</size>",
  ui_story_5040_50400401_103_dialog_content = "귀찮은 녀석, 남의 장사를 방해하고 말이야.",
  ui_story_5040_50400401_104_dialog_content = "아, 암귀?!",
  ui_story_5040_50400401_105_dialog_content = "아도니스 씨는 숨어 있어! 암귀는 우리가 어떻게든 할 테니까.",
  ui_story_5040_50400402_1_dialog_content = "저 녀석들... 일만 터졌다 하면 빨리도 도망간다니까.",
  ui_story_5040_50400402_2_dialog_content = "아도니스 씨, 괜찮아?",
  ui_story_5040_50400402_3_dialog_content = "괘, 괜찮아요.",
  ui_story_5040_50400402_4_dialog_content = "죄송해요. 아무 도움도 못 드리고... 암귀를 보자마자 다리가 풀려 버렸네요...",
  ui_story_5040_50400402_5_dialog_content = "괜찮아, 누구나 암귀와 싸우는 데 익숙한 건 아니니까.",
  ui_story_5040_50400402_6_dialog_content = "그래도 호넷이랑 실버도 갔으니 다행이야. 쟤들이랑 얽히면 귀찮아진다고.",
  ui_story_5040_50400402_7_dialog_content = "마음 약한 사람은 더 잘 속이는 녀석들이니까, 다음에 만나면 확실하게 거절해야 돼.",
  ui_story_5040_50400402_8_dialog_content = "휴... 전 항상 이랬는걸요.",
  ui_story_5040_50400402_9_dialog_content = "어머, 아까 관월제 우표 파시던 분 아닌가요?",
  ui_story_5040_50400402_10_dialog_content = "네?",
  ui_story_5040_50400402_11_dialog_content = "아도니스 씨 말하는 거야? 아까 같이 있던 건 타라라고 해.\n그리고 쿠리어 길드의 장로 예리아 씨도 있었고.",
  ui_story_5040_50400402_12_dialog_content = "그런 이름이었군요.",
  ui_story_5040_50400402_13_dialog_content = "근데 누구시죠...?",
  ui_story_5040_50400402_14_dialog_content = "안녕하세요, 전 티나라고 해요. 백야성 심판소의 심판관이랍니다.\n제 소개를 잊고 있었네요. 실례가 많았어요.",
  ui_story_5040_50400402_15_dialog_content = "난 PlayerName, 반가워.",
  ui_story_5040_50400402_16_dialog_content = "오전에 제가 관월제 우표에 대해 아도니스 씨와 그분들께 여쭤봤거든요.",
  ui_story_5040_50400402_17_dialog_content = "그리고 그 쿠리어님 덕분에 움브라톤에서 우표를 구할 수 있었어요.",
  ui_story_5040_50400402_18_dialog_content = "정말요? 그거 다행이네요! 전부 예리아 씨가 알려주신 덕분이지만요.",
  ui_story_5040_50400402_19_dialog_content = "아무튼 작년 우표를 찾았으니까, 친구분과 그 애인분도 분명히 기뻐하겠네요.",
  ui_story_5040_50400402_20_dialog_content = "네, 바로 우표를 주러 갔는데, 친구도 정말 좋아하는 것 같았어요.",
  ui_story_5040_50400402_21_dialog_content = "우표를 소중하게 챙겨서는 고맙다고 하더니,\n연인한테 편지를 쓰러 뒤도 안 돌아보고 방으로 가더라니까요.",
  ui_story_5040_50400402_22_dialog_content = "소개받았던 그분은 그 외에도 희귀한 소장품을 많이 가지고 계셔서,\n마침 한 번 더 보러 가려던 참에 두 분과 만나게 됐네요.",
  ui_story_5040_50400402_23_dialog_content = "그나저나... 안색이 안 좋으신 것 같은데, 무슨 일이 있었나요?",
  ui_story_5040_50400402_24_dialog_content = "그게... 사실은...",
  ui_story_5040_50400402_25_dialog_content = "으음, 그런 거였군요.\n어쩐지 오전엔 서로 분위기가 조금 어색한 것 같았어요.",
  ui_story_5040_50400402_26_dialog_content = "그럼 이제 곧 일루미나로 가시는 거죠?\n아니면 제가 친구의 애인한테 부탁해서 해독제에 대해 알아봐 달라고 할까요?",
  ui_story_5040_50400402_27_dialog_content = "네?",
  ui_story_5040_50400402_28_dialog_content = "사실 친구의 애인은 자난성의 블랙 엄브렐라 연구소에서 일하고 있거든요.",
  ui_story_5040_50400402_29_dialog_content = "약에 관한 거라면 뭔가 알고 있을지도 몰라요.\n그 사람을 찾아가서 제 이름을 말하면 될 거예요.",
  ui_story_5040_50400402_30_dialog_content = "도움이 될지는 모르겠지만, 조금이라도 힘이 됐으면 좋겠네요.",
  ui_story_5040_50400402_31_dialog_content = "정말 고맙습니다!",
  ui_story_5040_50400402_32_dialog_content = "일루미나에 도착하면 바로 가서 물어볼게요!",
  ui_story_5040_50400402_33_dialog_content = "다행이네, 아도니스 씨. 이제 또 희망이 보이잖아!",
  ui_story_5040_50400402_34_dialog_content = "그럼 행운을 빌게요.",
  ui_story_5040_50400402_35_dialog_content = "하암... 조금 졸리네요. 아무래도 이제 돌아가서 자야 할 때가 된 것 같아요.",
  ui_story_5040_50400402_36_dialog_content = "이건 아도니스 씨가 남을 도와줘서 보답을 받은 거야.\n그럼 자난성에 도착하면 연구소로 가 보자.",
  ui_story_5040_50400402_37_dialog_content = "네! 고마워요, PlayerName 씨.",
  ui_story_5040_50400402_38_dialog_content = "<color=#e8d9bb>그날 밤</color>",
  ui_story_5040_50400402_39_dialog_content = "휴, 결국 여기서도 아무것도 못 찾은 건가요...",
  ui_story_5040_50400402_40_dialog_content = "나... 열심히... 하고 있어...",
  ui_story_5040_50400402_41_dialog_content = "서두르라는 게 아니에요. 천천히 생각해도 돼요.",
  ui_story_5040_50400402_42_dialog_content = "하지만 움브라톤도 이 정도면 꽤 둘러봤으니까, 이제 슬슬 돌아가는 게 좋겠어요.",
  ui_story_5040_50400402_43_dialog_content = "밤에는 백야성이 더 안전하니까요.",
  ui_story_5040_50400402_44_dialog_content = "움브라톤... 백야...성...",
  ui_story_5040_50400402_45_dialog_content = "백...야...",
  ui_story_5040_50400402_46_dialog_content = "왜 그러죠? 갑자기 백야성 쪽은 왜요?",
  ui_story_5040_50400402_47_dialog_content = "뭔가 떠오른 건가요?",
  ui_story_5040_50400402_48_dialog_content = "백야...성... 아주... 멀어...",
  ui_story_5040_50400402_49_dialog_content = "누굴... 위해... 왔어...",
  ui_story_5040_50400402_50_dialog_content = "누구랑... 약속했어... 백야...성에서... 만나겠다고...",
  ui_story_5040_50400402_51_dialog_content = "근데... 안 왔어...",
  ui_story_5040_50400402_52_dialog_content = "네? 전에 다른 곳에서 백야성으로 온 적이 있다는 건가요?",
  ui_story_5040_50400402_53_dialog_content = "응... 그런... 느낌이... 들어...",
  ui_story_5040_50400402_54_dialog_content = "그럼 당신은 백야성 출신이 아니군요. 어디에서 온 건지는 기억이 나나요?",
  ui_story_5040_50400402_55_dialog_content = "아주... 먼 곳... 같아...",
  ui_story_5040_50400402_56_dialog_content = "음... 아주 먼 곳인가요.",
  ui_story_5040_50400402_57_dialog_content = "그래요. 일단은 너무 무리하진 마요.\n백야성이 아니라는 걸 알았으니까, 이젠 다른 곳을 가 보면 되겠죠.",
  ui_story_5040_50400402_58_dialog_content = "PlayerName 씨 일행은 내일 자난성으로 출발하는 것 같아요.\n우리도 같이 가기로 해요.",
  ui_story_5040_50400402_59_dialog_content = "자난성의 쿠리어 길드에 가 보면 또 뭔가 새로운 발견이 있을지도 몰라요.",
  ui_story_5040_50400402_60_dialog_content = "응...",
  ui_story_5040_50400402_61_dialog_content = "<color=#e8d9bb>다음날</color>",
  ui_story_5040_50400402_62_dialog_content = "자, 다들 준비됐어? 놓고 가는 물건은 없지?",
  ui_story_5040_50400402_63_dialog_content = "후훗, 일루미나에 가는 것도 오랜만이네. 그쪽 아기새들은 어떻게 지내고 있으려나.",
  ui_story_5040_50400402_64_dialog_content = "그쪽 쿠리어들도 고생하게 만들지는 말아 주세요.",
  ui_story_5040_50400402_65_dialog_content = "일루미나는 고도로 군사화된 곳이라고 전에 타라한테 들었어요.\n예전부터 쭉 한번 가 보고 싶었어요.",
  ui_story_5040_50400402_66_dialog_content = "난 일루미나의 신형 트럭이 보고 싶어.",
  ui_story_5040_50400402_67_dialog_content = "그럼 출발하자!",
  ui_story_5040_50400502_1_dialog_content = "우와... 여기가 자난성이군요!",
  ui_story_5040_50400502_2_dialog_content = "나도 한 번밖에 안 와봤어.",
  ui_story_5040_50400502_3_dialog_content = "뭐랄까, 자난성은 언제 와도 변하질 않는 것 같다니까.",
  ui_story_5040_50400502_4_dialog_content = "PlayerName 넌 일루미나에 자주 왔어?",
  ui_story_5040_50400502_5_dialog_content = "자주까진 아니지만, 친한 친구가 일루미나 사람이거든. 그래서 같이 몇 번 온 적 있어.",
  ui_story_5040_50400502_6_dialog_content = "근데 그 친구도 지금은 휴가 중이라 아마 못 만날 것 같네.",
  ui_story_5040_50400502_7_dialog_content = "자난성에는 관월제가 없나요? 거리에 기념일 분위기가 전혀 없네요.",
  ui_story_5040_50400502_8_dialog_content = "물론 있지. 게다가 확실히 뿌리내리고 있어.",
  ui_story_5040_50400502_9_dialog_content = "다만 지역이 다르면 사람들의 생활 스타일도 달라지는 법이야.\n일루미나는 백야성처럼 체면에 연연하지 않거든.",
  ui_story_5040_50400502_10_dialog_content = "이곳 사람들은 보다 현실적이고 절제된 삶을 살고 있어.\n관월제가 되면 대부분의 여자들은 직접 만든 시나몬롤을 좋아하는 사람한테 선물해.",
  ui_story_5040_50400502_11_dialog_content = "그리고 남자는 옷소매 안쪽에 하트를 그리고, 그 안에 좋아하는 사람의 이름을 써.",
  ui_story_5040_50400502_12_dialog_content = "뭔가 귀엽네요.",
  ui_story_5040_50400502_13_dialog_content = "그러게요, 정말 낭만적이네요! 저도 해야겠어요!",
  ui_story_5040_50400502_14_dialog_content = "야...",
  ui_story_5040_50400502_15_dialog_content = "그러고 보니 예리아 씨는 정말 뭐든지 잘 알고 있네요.",
  ui_story_5040_50400502_16_dialog_content = "예리아 장로님은 옛날에 여러 곳을 가셨다고 해요.\n근데 장로님이 그시절 얘기를 하는 건 들은 적이 거의 없지만요.",
  ui_story_5040_50400502_17_dialog_content = "다 지난 일이잖아. 얘기할 게 뭐 있어.\n그것보다 저기 저 사람, 내가 잘못 본 게 아니라면...",
  ui_story_5040_50400502_18_dialog_content = "?!",
  ui_story_5040_50400502_19_dialog_content = "일루미나의 아기새 같은데.",
  ui_story_5040_50400502_20_dialog_content = "도브? 지금 배달 시간 아니야?",
  ui_story_5040_50400502_21_dialog_content = "으으, 지금 배달 중이잖아. 공휴일에도 꾸구구 안 하고 말이야.",
  ui_story_5040_50400502_22_dialog_content = "난 그저 내 페이스대로 일하고 있을 뿐이라구.",
  ui_story_5040_50400502_23_dialog_content = "그 말 엄청 의심스러운데...",
  ui_story_5040_50400502_24_dialog_content = "일루미나의 선배님이신가요? 이야기는 많이 들었어요. 전부 부정적인 얘기였지만요.",
  ui_story_5040_50400502_25_dialog_content = "어떻게 그렇게 말할 수가 있어? 나도 열심히 일하고 있다구.\n기념일이라고 소포가 산처럼 쌓인 게 잘못이지.",
  ui_story_5040_50400502_26_dialog_content = "절대 다 못 배달해. 힘들어 죽겠어 구구.",
  ui_story_5040_50400502_27_dialog_content = "그러니까 역시 땡땡이치고 있다는 거잖아.",
  ui_story_5040_50400502_28_dialog_content = "뭐, 일단 그 얘기는 됐어. 도브 너 혹시 관월제 깃털 도장 알아?",
  ui_story_5040_50400502_29_dialog_content = "깃털 도장? 그거 나한테 있는데.",
  ui_story_5040_50400502_30_dialog_content = "뭐?!",
  ui_story_5040_50400502_31_dialog_content = "선배들은 전부 배달 때문에 바빠서 길드에 없어. 그래서 나보고 보관하라고 주고 갔어.",
  ui_story_5040_50400502_32_dialog_content = "역시 아무리 봐도 네가 땡땡이쳐서 다른 사람들이 야근하게 된 것 같단 말이지...",
  ui_story_5040_50400502_33_dialog_content = "근데 그건 왜 물어?",
  ui_story_5040_50400502_34_dialog_content = "사실 저흰 깃털 도장을 찍어달라고 온 겁니다.\n일루미나 쿠리어 길드의 도장을 받으려면 뭘 해야 하죠?",
  ui_story_5040_50400502_35_dialog_content = "아... 그렇구나.",
  ui_story_5040_50400502_36_dialog_content = "그거야 쉽지. 나 대신 나머지 소포를 배달해 주면 돼.",
  ui_story_5040_50400502_37_dialog_content = "...그거 규정에 맞는 거야?",
  ui_story_5040_50400502_38_dialog_content = "어차피 도장은 지금 내가 들고 있으니까, 규정 같은 건 내가 정할 수 있는 거잖아.",
  ui_story_5040_50400502_39_dialog_content = "조금 미안하긴 하지만, 너희가 도와준다면 진심으로 감사할게.",
  ui_story_5040_50400502_40_dialog_content = "알겠습니다! 맡겨만 주세요!",
  ui_story_5040_50400502_41_dialog_content = "<color=#e8d9bb>잠시 후</color>",
  ui_story_5040_50400502_42_dialog_content = "......",
  ui_story_5040_50400502_43_dialog_content = "......",
  ui_story_5040_50400502_44_dialog_content = "......",
  ui_story_5040_50400502_45_dialog_content = "확실히 꽤 있네.",
  ui_story_5040_50400502_46_dialog_content = "이...이건 꽤 있는 정도가 아니잖아요!\n대체 어떻게 소포가 이렇게 쌓일 때까지 내버려 둘 수 있는 거야?!",
  ui_story_5040_50400502_47_dialog_content = "우리 둘이서 밥도 안 먹고 잠도 안 자고 3일을 배달해도 안 끝나겠는데...",
  ui_story_5040_50400502_48_dialog_content = "미안... 설마 이렇게 많을 줄은 몰랐어...",
  ui_story_5040_50400502_49_dialog_content = "휴, 어쩔 수 없지. 다 같이 하자.",
  ui_story_5040_50400502_50_dialog_content = "저도 도울게요. 이참에 세이블도 데리고 이곳저곳 둘러보면 되니까요.",
  ui_story_5040_50400502_51_dialog_content = "죄송합니다. 저희 일인데 또 여러분께 폐를 끼치네요.",
  ui_story_5040_50400502_52_dialog_content = "제일 많은 부분은 우리가 할게. 난 힘 쓰는 일이라면 잘하거든.",
  ui_story_5040_50400502_53_dialog_content = "그럼 난 책을 읽으면서 응원하고 있을게.",
  ui_story_5040_50400502_54_dialog_content = "예리아 장로님... 아니, 그게 나을 수도 있겠네요.\n괜히 다른 문제가 더 생기지 않게 말이죠...",
  ui_story_5040_50400502_55_dialog_content = "좋아! 그럼 바로 시작하자!",
  ui_story_5040_50400502_56_dialog_content = "앗...!",
  ui_story_5040_50400502_57_dialog_content = "야, 너무 느리잖아. 아도니스!",
  ui_story_5040_50400502_58_dialog_content = "미, 미안, 계단이 너무 가팔라서...",
  ui_story_5040_50400502_59_dialog_content = "조심해야지!",
  ui_story_5040_50400502_60_dialog_content = "지금 갖고 있는 소포를 분류해 줘. 이 근처는 네가 가고, 먼 곳은 내가 갈게.",
  ui_story_5040_50400502_61_dialog_content = "안 돼. 그럼 네 일이 너무 많잖아.",
  ui_story_5040_50400502_62_dialog_content = "여기저기 뛰어다니는 건 익숙해. 그리고 이렇게 하면 더 효율적이고.",
  ui_story_5040_50400502_63_dialog_content = "아, 알겠어...",
  ui_story_5040_50400502_64_dialog_content = "비, 비비안 씨! 택배 왔어!",
  ui_story_5040_50400502_65_dialog_content = "어머, PlayerName? 오늘 바이스는...",
  ui_story_5040_50400502_66_dialog_content = "알고 있어! 그럼 잘 배송했으니까 먼저 갈게!",
  ui_story_5040_50400502_67_dialog_content = "왜 당신이 배달하고 있는 거죠?",
  ui_story_5040_50400502_68_dialog_content = "...도브, 당신 업무 평가는 이제 끝장인 줄 아세요.",
  ui_story_5040_50400502_69_dialog_content = "안녕하세요, 편지 왔습니다~",
  ui_story_5040_50400502_70_dialog_content = "휴, 이쪽 건 이걸로 끝이에요.",
  ui_story_5040_50400502_71_dialog_content = "키아... 대단해...",
  ui_story_5040_50400502_72_dialog_content = "후훗, 이건 애초부터 제 일이잖아요.",
  ui_story_5040_50400502_73_dialog_content = "중간에 뭔가 낯익은 게 있으면 바로 알려주세요.",
  ui_story_5040_50400502_74_dialog_content = "<color=#e8d9bb>몇 시간 뒤</color>",
  ui_story_5040_50400502_75_dialog_content = "난... 이제 한계야...",
  ui_story_5040_50400502_76_dialog_content = "휴... 휴우... PlayerName 씨 분량은 다 끝난 건가요?",
  ui_story_5040_50400502_77_dialog_content = "응... 겨우 다 했네...",
  ui_story_5040_50400502_78_dialog_content = "여기저기 다녀온 건 사실이지만, 그래도 너희 둘 다 체력이 너무 약하잖아.",
  ui_story_5040_50400502_79_dialog_content = "수고했어. 아무래도 임무는 무사히 마친 모양이네.",
  ui_story_5040_50400502_80_dialog_content = "키아는 아직 안 왔나요?",
  ui_story_5040_50400502_81_dialog_content = "걘 걱정할 필요 없어. 진작에 끝났을 거야. 북방의 아기새는 업무 효율이 높거든.",
  ui_story_5040_50400502_82_dialog_content = "아마 지금쯤 그 검은 아기새랑 같이 거리를 구경하고 있겠지.",
  ui_story_5040_50400502_83_dialog_content = "헤헤, 역시 PlayerName 너라니까.",
  ui_story_5040_50400502_84_dialog_content = "도브?! 너 계속 근처에서 빈둥대고 있었어?",
  ui_story_5040_50400502_85_dialog_content = "빈둥댄 거 아니거든. 나도 일하고 있었다구.",
  ui_story_5040_50400502_86_dialog_content = "임무는 잘 끝냈어요. 그럼 이제 도장을 찍어주시겠어요?",
  ui_story_5040_50400502_87_dialog_content = "물론이지! 자, 따끈따끈한 깃털 도장이야!",
  ui_story_5040_50400502_88_dialog_content = "쾅!",
  ui_story_5040_50400502_89_dialog_content = "하하, 이제 일루미나 깃털 도장도 찍었네!",
  ui_story_5040_50400502_90_dialog_content = "그게 무슨 의미가 있는지는 모르겠지만.",
  ui_story_5040_50400502_91_dialog_content = "왜 없겠어. 우리도 이렇게 조금씩 서로 익숙해졌잖아.",
  ui_story_5040_50400502_92_dialog_content = "누, 누가 익숙해졌다는 거야?",
  ui_story_5040_50400502_93_dialog_content = "근데 이제 도장도 다 찍었잖아. 그럼 또 어딜 가지?",
  ui_story_5040_50400502_94_dialog_content = "모처럼 자난성에 왔는데, 다 같이 맛있는 거라도 먹고 영화도 보는 건 어떨까요?",
  ui_story_5040_50400502_95_dialog_content = "그래야 기념일 같잖아요!",
  ui_story_5040_50400502_96_dialog_content = "일루미나의 음식은 언제든지 먹을 수 있어.",
  ui_story_5040_50400502_97_dialog_content = "편지를 배달할 때 지하성에서 최신 자동소총을 보냈다는 얘길 들었어.\n난 정비소에 가서 그걸 좀 보고 싶어.",
  ui_story_5040_50400502_98_dialog_content = "관월제에 정비소에 가겠다고? 그건 전혀 낭만적이지가 않잖아...",
  ui_story_5040_50400502_99_dialog_content = "싫으면 각자 움직이면 되지.",
  ui_story_5040_50400502_100_dialog_content = "......",
  ui_story_5040_50400502_101_dialog_content = "둘 다 진정해. 그 전에 그것보다 더 중요한 일이 있잖아?",
  ui_story_5040_50400502_102_dialog_content = "아니면 두 사람, 여기 온 목적을 잊어버린 걸까?",
  ui_story_5040_50400502_103_dialog_content = "그래, 타라 씨의 기억상실을 치료할 단서를 찾으러\n블랙 엄브렐라 연구소에 가겠다고 했잖아.",
  ui_story_5040_50400502_104_dialog_content = "아... 맞아요.",
  ui_story_5040_50400502_105_dialog_content = "......",
  ui_story_5040_50400502_106_dialog_content = "서두르는 게 좋겠어. 날이 저물기 전에 할 일부터 끝내자.",
  ui_story_5040_50400601_1_dialog_content = "(여기도 정말 오랜만에 오는 것 같네.)",
  ui_story_5040_50400601_2_dialog_content = "...그래서 결국 찾아오게 되었습니다. 부탁드립니다.",
  ui_story_5040_50400601_3_dialog_content = "이야기는 이미 들었어요. 티나 씨와 여러분께 정말 감사드려요!",
  ui_story_5040_50400601_4_dialog_content = "일루미나와 백야성은 원래 미묘한 관계라서, 저희 사이에도 어려움이 참 많았어요.",
  ui_story_5040_50400601_5_dialog_content = "하지만 저흴 응원해주는 사람도 있거든요. 티나 씨도 그중 한 명이에요.",
  ui_story_5040_50400601_6_dialog_content = "백야성의 귀족인데도 줄곧 저희의 사랑을 응원해 주셨죠.",
  ui_story_5040_50400601_7_dialog_content = "티나 씨는 컨디션을 유지하려면 아주 오랜 시간의 수면이 필요하다고 들었어요.\n그런데도 저흴 위해서 우표를 찾아 주셨던 거예요.",
  ui_story_5040_50400601_8_dialog_content = "음, 티나 씨는 확실히 좀 독특한 분 같더군요.",
  ui_story_5040_50400601_9_dialog_content = "항상 예의도 바르고, 아주 상냥하기도 해요.",
  ui_story_5040_50400601_10_dialog_content = "근데 뭔가 고민도 있는 것 같았어요. 심판소의 업무는 무척 「기묘」하다고 들었거든요.",
  ui_story_5040_50400601_11_dialog_content = "다음엔 또 언제 만날 수 있을지 모르겠지만,\n전 티나 씨에 대해서도 더 알고 싶다고 생각하고 있어요.",
  ui_story_5040_50400601_12_dialog_content = "하지만 티나 씨 이야기를 들어보니 두 분도 여러 가지로 힘드신 것 같던데요.",
  ui_story_5040_50400601_13_dialog_content = "맞아. 왜 그냥 둘이 같이 훌쩍 떠나버리지 않는 건데?",
  ui_story_5040_50400601_14_dialog_content = "서로 해야 할 일이 있으니까요. 우린 자신의 일이 먼저고, 애인은 그다음이에요.",
  ui_story_5040_50400601_15_dialog_content = "저나 그 사람이나 모두 책임감이 강한 사람들이에요. 그래서 서로 끌린 거죠.",
  ui_story_5040_50400601_16_dialog_content = "서로가 진심으로 서로를 대한다면, 물리적 거리나 주변의 반대는 문제가 안 돼요.\n어차피 마음은 이어져 있으니까요.",
  ui_story_5040_50400601_17_dialog_content = "마음이... 이어져 있다고?",
  ui_story_5040_50400601_18_dialog_content = "저도 그렇게 생각해요.\n서로가 정말로 사랑한다면, 다른 그 무엇도 문제가 되지 않을 거예요.",
  ui_story_5040_50400601_19_dialog_content = "후훗, 그렇군요. 그럼 본론으로 들어갈까요?\n이쪽이 타라 씨군요. 상황은 대충 알겠어요.",
  ui_story_5040_50400601_20_dialog_content = "다만 전 지금 여기서 실습 연구원으로 일하고 있어서요.\n자세한 건 동료에게 가서 물어봐야 하니 잠시만 기다려 주세요.",
  ui_story_5040_50400601_21_dialog_content = "네, 그럼 부탁할게요!",
  ui_story_5040_50400601_22_dialog_content = "<size=33>예리아, 나 꾀병인 거 들키진 않겠지?</size>",
  ui_story_5040_50400601_23_dialog_content = "계속 못 하겠으면 그냥 인정하면 되는 거 아냐?",
  ui_story_5040_50400601_24_dialog_content = "<size=33>그럴 순 없어! 그럼 앞으로 창피해서 어떻게 살아!</size>",
  ui_story_5040_50400601_25_dialog_content = "네가 생각해 낸 방법이잖아. 이제 와서 창피하다는 거야?",
  ui_story_5040_50400601_26_dialog_content = "<size=33>절대 안 돼. 아무튼 무슨 일 생기면 좀 도와줘!</size>",
  ui_story_5040_50400601_27_dialog_content = "......",
  ui_story_5040_50400601_28_dialog_content = "(역시 기억상실은 연기였구나. 나도 일단은 모르는 척하고 있어야겠네.)",
  ui_story_5040_50400601_29_dialog_content = "예리아 씨, 무슨 일이에요?",
  ui_story_5040_50400601_30_dialog_content = "아무것도 아니야! 그냥 이 연구실 대단한 것 같다고 얘기하고 있었어!",
  ui_story_5040_50400601_31_dialog_content = "당연하지. 여기 책임자인 미자드 씨는 엄청 대단하면서도 수수께끼 같은 사람이거든.",
  ui_story_5040_50400601_32_dialog_content = "타라, 왜 떨고 있는 거야?",
  ui_story_5040_50400601_33_dialog_content = "얜 여기가 좀 추운가 봐.",
  ui_story_5040_50400601_34_dialog_content = "네? 여기가 춥나...?",
  ui_story_5040_50400601_35_dialog_content = "여러분, 이쪽으로 오세요. 실험실의 선배님을 소개해 드릴게요.",
  ui_story_5040_50400601_36_dialog_content = "고마워.",
  ui_story_5040_50400601_37_dialog_content = "유라 선배님, 이쪽이 아까 제가 말씀드렸던 타라 씨예요. 기억을 잃어버렸다고 해요.",
  ui_story_5040_50400601_38_dialog_content = "도움을 주신다니 정말 감사드려요. 잘 부탁드립니다.",
  ui_story_5040_50400601_39_dialog_content = "오~ 여러분이 제 동료를 도와주셨다고 들었습니다.\n답례해야 하는 건 당연한 일이니까 고마워하실 필요는 없어요.",
  ui_story_5040_50400601_40_dialog_content = "타라 양, 조금 가까이에서 봐도 될까요?",
  ui_story_5040_50400601_41_dialog_content = "그, 그래.",
  ui_story_5040_50400601_42_dialog_content = "오늘은 아쉽지만 미자드 씨가 안 계셔서요.\n기억상실증은 제 전문 분야는 아니지만, 그래도 어느 정도는 알고 있답니다.",
  ui_story_5040_50400601_43_dialog_content = "(휴... 다행이다.)",
  ui_story_5040_50400601_44_dialog_content = "음... 보기엔 별문제가 없는 것 같은데...\n그럼 기본적인 신체 상태부터 테스트해 보도록 할까요.",
  ui_story_5040_50400601_45_dialog_content = "어떤 테스트죠?",
  ui_story_5040_50400601_46_dialog_content = "(유라의 미소는... 왠지 무섭단 말이지...)",
  ui_story_5040_50400601_47_dialog_content = "긴장할 것 없어요. 약간의 자극으로 근육을 풀어주는 것뿐이니까요.",
  ui_story_5040_50400601_48_dialog_content = "캬악──!",
  ui_story_5040_50400601_49_dialog_content = "아, 아니지...?",
  ui_story_5040_50400602_1_dialog_content = "휴! 암귀로 테스트할 거였으면 먼저 좀 말해!",
  ui_story_5040_50400602_2_dialog_content = "야! 이런 테스트인지 미리 말했어야지!",
  ui_story_5040_50400602_3_dialog_content = "이런, 죄송합니다. 하지만 전 여러분께 이 정도는 아무것도 아닐 줄 알았거든요.",
  ui_story_5040_50400602_4_dialog_content = "누가 봐도 무척 흥미로운 조합이잖아요.\n북방 분, 사막 분, 아인족 쿠리어... 심지어 아이테르까지 있으니까요.",
  ui_story_5040_50400602_5_dialog_content = "지금 그게 중요한 게 아니잖아. 우린 타라 씨의 병을 고치러 온 거야.",
  ui_story_5040_50400602_6_dialog_content = "내 몸에 무슨 문제가 있는 거야?",
  ui_story_5040_50400602_7_dialog_content = "현재로서는 몸에 이상은 없는 것 같군요.",
  ui_story_5040_50400602_8_dialog_content = "검사도 했고, 그럼 이젠 또 뭘 하는데?",
  ui_story_5040_50400602_9_dialog_content = "으음, 기억상실의 계기에 대해 다른 정보는 없나요?",
  ui_story_5040_50400602_10_dialog_content = "그러니까... 만능 물약을 만든 영매 말로는 그 약이 아주 귀한 원료로 만든 거라고 했어요.",
  ui_story_5040_50400602_11_dialog_content = "레디젤 사막의 분홍색 샌드버그라고 했었나...\n아무튼 아주 보기 드문 희귀종이라고 하더군요.",
  ui_story_5040_50400602_12_dialog_content = "분홍색... 샌드버그요?",
  ui_story_5040_50400602_13_dialog_content = "네.",
  ui_story_5040_50400602_14_dialog_content = "유라, 알아?",
  ui_story_5040_50400602_15_dialog_content = "......",
  ui_story_5040_50400602_16_dialog_content = "그 샌드버그가 또 모습을 드러냈단 말인가요...?",
  ui_story_5040_50400602_17_dialog_content = "<size=33>그럴 리가 없는데... 말도 안 돼!</size>",
  ui_story_5040_50400602_18_dialog_content = "<size=33>타라?</size>",
  ui_story_5040_50400602_19_dialog_content = "<size=33>분홍색 샌드버그 비늘은 내가 가지고 있어. 영매한테 있을 리가 없잖아!</size>",
  ui_story_5040_50400602_20_dialog_content = "<size=33>그 샌드버그가 진짜로 존재했다는 거야? 그렇다고 비늘이 설마 한 장뿐이겠어?</size>",
  ui_story_5040_50400602_21_dialog_content = "<size=33>내가 알기로 그 분홍색 샌드버그의 비늘이 시장에 풀린 건 한 장뿐이었어.\n그게 어떻게 또 나타난 거지?</size>",
  ui_story_5040_50400602_22_dialog_content = "전 식물 분야의 전문가입니다.\n전에 어떤 포자를 찾을 때 미자드 씨한테서 이야기를 들은 적이 있었죠.",
  ui_story_5040_50400602_23_dialog_content = "그 포자는 연구했던 사람이 거의 없고, 책에만 기록이 있었는데,\n분홍색 샌드버그의 비늘에 기생한다고 하더군요.",
  ui_story_5040_50400602_24_dialog_content = "어쨌든 미자드 씨는 그 샌드버그에 대해 말했었고,\n레디젤 사막에서도 목격되었다고 합니다만, 실제로 본 사람은 매우 드물더군요.",
  ui_story_5040_50400602_25_dialog_content = "일반 샌드버그보다 더 포악하고, 접근할 수 있는 사람이 없기 때문에\n그 비늘도 매우 귀해서, 시장엔 한 장밖에 유통되지 않았다고 합니다.",
  ui_story_5040_50400602_26_dialog_content = "만약 여러분이 그 비늘을 구할 수 있다면, 제가 해독제를 연구해 볼 수 있을 것 같군요.",
  ui_story_5040_50400602_27_dialog_content = "그 이외의 방법은 죄송하지만 저도 당장은 떠오르는 게 없네요.",
  ui_story_5040_50400602_28_dialog_content = "......",
  ui_story_5040_50400602_29_dialog_content = "......",
  ui_story_5040_50400602_30_dialog_content = "음, 그럼 이제 우리 목표도 확실해졌네.",
  ui_story_5040_50400602_31_dialog_content = "예리아 씨?",
  ui_story_5040_50400602_32_dialog_content = "이따가 어차피 사막 갈 거잖아? 그럼 레디젤 렌치 지부의 임무는\n분홍색 샌드버그를 쓰러트리고 비늘을 구해오는 거로 하자.",
  ui_story_5040_50400602_33_dialog_content = "잠깐만, 지금 그거 진심으로 하는 소리야?",
  ui_story_5040_50400602_34_dialog_content = "그런 샌드버그를 본 사람이 있기는 해?\n난 지금까지 사막에서 살면서 한 번도 못 들어봤어. 넌 들어봤어?",
  ui_story_5040_50400602_35_dialog_content = "나도 없는데.",
  ui_story_5040_50400602_36_dialog_content = "근데 왜 그런 임무를 주겠다는 거야?!",
  ui_story_5040_50400602_37_dialog_content = "타라의 기억상실을 고칠 방법이 그것밖에 없다면, 전 해 보고 싶어요.",
  ui_story_5040_50400602_38_dialog_content = "뭐?",
  ui_story_5040_50400602_39_dialog_content = "아도니스, 너 미쳤어?",
  ui_story_5040_50400602_40_dialog_content = "사실 나도 절망하고 있어... 난 능력도 보잘것없고 겁도 많아.\n집에 나오는 벌레조차 무서워하는 나한테... 전설의 샌드버그라니...",
  ui_story_5040_50400602_41_dialog_content = "하지만 나 때문에 네가 이렇게 된 이상, 이대로 가만히 있을 순 없어.",
  ui_story_5040_50400602_42_dialog_content = "그리고 내가 겁쟁이라서 네가 화난 거 알아. 그러니까 난 자신을 바꾸고 싶어.",
  ui_story_5040_50400602_43_dialog_content = "이번만큼은 도망치면 안 돼.",
  ui_story_5040_50400602_44_dialog_content = "정말 감동적이네.",
  ui_story_5040_50400602_45_dialog_content = "아도니스, 사실 나...",
  ui_story_5040_50400602_46_dialog_content = "음, 아주 감동적이야. 그러니까 넌 네가 샌드버그를 이길 수 있을 것 같다는 거지?",
  ui_story_5040_50400602_47_dialog_content = "물론 지금 당장은 무리인 건 알아요! 그러니 훈련시켜 주세요. 단련이 필요해요!",
  ui_story_5040_50400602_48_dialog_content = "암귀와 맞서는 것부터 시작해도 상관없어요. 전 강해져야 해요!",
  ui_story_5040_50400602_49_dialog_content = "너 싸울 수 있어?",
  ui_story_5040_50400602_50_dialog_content = "너희 아버지가 말씀하신 거 들었어. 전에 노비오 씨한테 루미나틱스 배운 적 있다며?",
  ui_story_5040_50400602_51_dialog_content = "네, 어렸을 때 도서관에 갈 때마다 노비오 선생님께서 자주 가르쳐 주셨죠.",
  ui_story_5040_50400602_52_dialog_content = "그리 강하지는 않지만, 그래도 기초는 가지고 있어요.",
  ui_story_5040_50400602_53_dialog_content = "흐음~",
  ui_story_5040_50400602_54_dialog_content = "예리아 씨, 그 표정 뭔가 무서운데요.",
  ui_story_5040_50400602_55_dialog_content = "걱정하지 마. 우린 일단은 한배에 탄 사이니까, 곤란하게 만들거나 하진 않아.",
  ui_story_5040_50400602_56_dialog_content = "아무튼 일은 쉽게 됐네.\n네가 마음을 먹은 이상, 일단 암귀랑 싸우는 것부터 시작해 볼까...",
  ui_story_5040_50400602_57_dialog_content = "지, 지금부터 제가 암귀랑 싸우는 건가요?",
  ui_story_5040_50400602_58_dialog_content = "혼자 암귀랑 싸우게 만드는 건 너무 잔혹하잖아. 후훗, 나한테 다른 방법이 있어.",
  ui_story_5040_50400602_59_dialog_content = "그 애한테 상대가 되어 달라고 하면 괜찮을지도 몰라.",
  ui_story_5040_50400701_1_dialog_content = "예리아 장로님, 갑자기 저희는 왜 부르신 거죠?",
  ui_story_5040_50400701_2_dialog_content = "예리아 씨, 설마 그 애라는 게...",
  ui_story_5040_50400701_3_dialog_content = "구우...?",
  ui_story_5040_50400701_4_dialog_content = "으음~ 괜찮아 보이지 않아?\n키아의 친척인 이 검은 아기새, 분위기나 행동이나 암귀랑 아주 비슷하잖아.",
  ui_story_5040_50400701_5_dialog_content = "아도니스의 전투 연습 상대로 제격이지 않아?",
  ui_story_5040_50400701_6_dialog_content = "음, 확실히 세이블은 오로리안 같지 않게 피부가 검긴 하지만,\n그렇다고 사람한테 암귀 역할을 하라는 건 좀 너무하잖아요.",
  ui_story_5040_50400701_7_dialog_content = "(...근데 솔직히 이 세이블이란 애는 확실히 암귀와 뭔가 관계가 있을 거야.)",
  ui_story_5040_50400701_8_dialog_content = "(하지만 키아가 데려온 아이고, 지금까진 아직 이상한 행동도 안 하니까...\n조금만 더 상황을 지켜보자.)",
  ui_story_5040_50400701_9_dialog_content = "전...투...?",
  ui_story_5040_50400701_10_dialog_content = "세이블은 싸울 수 없어요. 다치기라도 하면 어떡하려고 그래요?",
  ui_story_5040_50400701_11_dialog_content = "긴장 풀어. 진짜로 싸우는 게 아니야. 그냥 아도니스의 배짱을 좀 길러주는 것뿐이야.",
  ui_story_5040_50400701_12_dialog_content = "아도니스 넌 어때?",
  ui_story_5040_50400701_13_dialog_content = "음... 조금 실례인 것 같지만... 세이블 씨가 힘을 빌려준다면 정말 고마울 거예요.",
  ui_story_5040_50400701_14_dialog_content = "지금 제 상황에서 진짜 암귀를 상대한다면, 아마 좋은 꼴은 못 보겠죠.",
  ui_story_5040_50400701_15_dialog_content = "게다가 전 평소에 루미나틱스를 거의 쓰지 않아서 익숙하지가 않아요.\n평소 밖에서는 항상 타라가 절 지켜줬고요.",
  ui_story_5040_50400701_16_dialog_content = "각자 잘하는 게 있는 법이잖아. 너도 너무 억지부리진 마.",
  ui_story_5040_50400701_17_dialog_content = "<size=33>널 지키는 게 나한테 부담되는 일도 아니었으니까...</size>",
  ui_story_5040_50400701_18_dialog_content = "뭐?",
  ui_story_5040_50400701_19_dialog_content = "아, 아무튼 이대로는 안 돼. 어떻게든 난 달라지고 말 거야.",
  ui_story_5040_50400701_20_dialog_content = "부탁드립니다, 키아 씨! 도와주세요!",
  ui_story_5040_50400701_21_dialog_content = "음... 세이블, 어떻게 할까요?",
  ui_story_5040_50400701_22_dialog_content = "도...도움이 될... 수 있다면...",
  ui_story_5040_50400701_23_dialog_content = "나... 도와...줄게!",
  ui_story_5040_50400701_24_dialog_content = "무리할 필요는 없어요. 그냥 연습이니까요.",
  ui_story_5040_50400701_25_dialog_content = "무리... 아...니야...",
  ui_story_5040_50400701_26_dialog_content = "힘이 될... 수 있어서... 기뻐...",
  ui_story_5040_50400701_27_dialog_content = "고맙습니다! 세이블 씨!",
  ui_story_5040_50400701_28_dialog_content = "크어어──",
  ui_story_5040_50400701_29_dialog_content = "환청인가? 방금 진짜로 암귀 소리가 난 것 같은데?",
  ui_story_5040_50400701_30_dialog_content = "네?!",
  ui_story_5040_50400701_31_dialog_content = "<size=45>크에엑!</size>",
  ui_story_5040_50400701_32_dialog_content = "위험해! 암귀야!",
  ui_story_5040_50400701_33_dialog_content = "어, 어디서 나타난 거죠?!",
  ui_story_5040_50400701_34_dialog_content = "신기하네. 왠지 너랑 검은 아기새한테 끌린 것 같은데?",
  ui_story_5040_50400701_35_dialog_content = "아니면 그저 우연일까?",
  ui_story_5040_50400701_36_dialog_content = "으윽...",
  ui_story_5040_50400701_37_dialog_content = "(설마 세이블한테 유인된 걸까?)",
  ui_story_5040_50400701_38_dialog_content = "암...귀...?",
  ui_story_5040_50400701_39_dialog_content = "다른 데 정신팔지 말고, 일단은 이 해충들을 치우는 데 집중하자.",
  ui_story_5040_50400701_40_dialog_content = "아도니스, 조심해! 내 뒤에 숨어!",
  ui_story_5040_50400701_41_dialog_content = "아, 알았어.",
  ui_story_5040_50400702_1_dialog_content = "전부 쓰러트린 것 같네. 다들 괜찮아?",
  ui_story_5040_50400702_2_dialog_content = "별 일 없어. 암귀 한두 마리 정도는 아무것도 아닌걸.",
  ui_story_5040_50400702_3_dialog_content = "저, 저도 괜찮아요.",
  ui_story_5040_50400702_4_dialog_content = "너흰 익숙하겠지만, 저기 두 사람은 아닌 것 같네.",
  ui_story_5040_50400702_5_dialog_content = "으으...",
  ui_story_5040_50400702_6_dialog_content = "무...무서워...",
  ui_story_5040_50400702_7_dialog_content = "(이런 두 사람을 서로 싸우게 해서 정말 배짱을 키울 수 있을까?)",
  ui_story_5040_50400702_8_dialog_content = "잠깐 쉴래? 아니면 바로 시작할까?",
  ui_story_5040_50400702_9_dialog_content = "휴, 휴식은 필요 없어요.",
  ui_story_5040_50400702_10_dialog_content = "피...필요 없어...!",
  ui_story_5040_50400702_11_dialog_content = "세이블, 무리하지 마세요.",
  ui_story_5040_50400702_12_dialog_content = "둘 다 꽤나 용감하네. 그럼 바로 시작하자.",
  ui_story_5040_50400702_13_dialog_content = "<color=#e8d9bb>잠시 후</color>",
  ui_story_5040_50400702_14_dialog_content = "......",
  ui_story_5040_50400702_15_dialog_content = "......",
  ui_story_5040_50400702_16_dialog_content = "저기, 언제 시작할 거야? 벌써 15분은 지난 것 같은데.",
  ui_story_5040_50400702_17_dialog_content = "시, 시작합니다!",
  ui_story_5040_50400702_18_dialog_content = "...!!",
  ui_story_5040_50400702_19_dialog_content = "싸우려는 자세로는 전혀 안 보이잖아.",
  ui_story_5040_50400702_20_dialog_content = "이번엔 진짜입니다!",
  ui_story_5040_50400702_21_dialog_content = "아...알겠어...",
  ui_story_5040_50400702_22_dialog_content = "<color=#e8d9bb>1시간 뒤</color>",
  ui_story_5040_50400702_23_dialog_content = "이번에야말로 진짜로 갑니다!",
  ui_story_5040_50400702_24_dialog_content = "가, 각오하세요!",
  ui_story_5040_50400702_25_dialog_content = "(엄청 졸리네. 이대로라면 한숨 잘 수 있을 것 같아.",
  ui_story_5040_50400702_26_dialog_content = "아도니스. 진짜 무리할 필요 없어.",
  ui_story_5040_50400702_27_dialog_content = "세이블, 힘내세요!",
  ui_story_5040_50400702_28_dialog_content = "......",
  ui_story_5040_50400702_29_dialog_content = "설마 진짜로 암귀가 눈앞에 있어서 싸워야 할 때도\n한 시간이나 멍하니 서 있어야 공격할 수 있는 건 아니지?",
  ui_story_5040_50400702_30_dialog_content = "넌 지금 사랑하는 사람을 위해서 암귀와 싸우는 거잖아.",
  ui_story_5040_50400702_31_dialog_content = "지금 만약 타라가 싸울 수 없게 된 상황에서 암귀가 나타난다면,\n지금처럼 망설이고 있을 수 있겠어?",
  ui_story_5040_50400702_32_dialog_content = "그 뒤에 어떤 결과가 너흴 기다리고 있을지 말할 필요는 없겠지?",
  ui_story_5040_50400702_33_dialog_content = "저...전...",
  ui_story_5040_50400702_34_dialog_content = "아니면 타라가 다쳐도 상관없다는 거야?\n결국 네 그 우유부단함은 극복할 수 없는 걸까?",
  ui_story_5040_50400702_35_dialog_content = "그, 그럴 리가 없잖아요!",
  ui_story_5040_50400702_36_dialog_content = "겁만 먹고 한 발짝도 내딛지 못하면, 동료는 생명의 위험에 처하게 돼.\n누가 그런 사람과 함께 있고 싶겠어?",
  ui_story_5040_50400702_37_dialog_content = "<size=33>야! 그렇게 자극하는 건 너무하잖아.</size>",
  ui_story_5040_50400702_38_dialog_content = "<size=33>왠지 불쌍해졌어요. 세이블, 당신도 좀 도와줘요.</size>",
  ui_story_5040_50400702_39_dialog_content = "<size=45>캬악! 캬오오──!</size>",
  ui_story_5040_50400702_40_dialog_content = "<size=55>으아아아악!</size>",
  ui_story_5040_50400702_41_dialog_content = "<color=#e8d9bb>퍽──</color>",
  ui_story_5040_50400702_42_dialog_content = "하... 하아...",
  ui_story_5040_50400702_43_dialog_content = "으으...",
  ui_story_5040_50400702_44_dialog_content = "세, 세이블! 괜찮아요?",
  ui_story_5040_50400702_45_dialog_content = "괜...찮...아...",
  ui_story_5040_50400702_46_dialog_content = "진짜로 공격한 거야?",
  ui_story_5040_50400702_47_dialog_content = "발전했네, 아도니스 씨! 적어도 계속 숨어있던 것보단 훨씬!",
  ui_story_5040_50400702_48_dialog_content = "전혀 피해를 입히지 못한 공격 방식이었지만, 그래도 아이테르 군 말대로 큰 발전이야.",
  ui_story_5040_50400702_49_dialog_content = "실전에선 전혀 못 맞혔겠지만.",
  ui_story_5040_50400702_50_dialog_content = "중요한 건 발전이 있었다는 거야! 자신을 바꾸는 게 가장 어려운 거라고!",
  ui_story_5040_50400702_51_dialog_content = "고마워... 타라!",
  ui_story_5040_50400702_52_dialog_content = "흑흑... 여러분... 정말 고마워요! 세이블 씨도 고마워요!",
  ui_story_5040_50400702_53_dialog_content = "천...만에...",
  ui_story_5040_50400702_54_dialog_content = "느낌이 좋네. 그럼 이 기세로 훈련을 계속하자.",
  ui_story_5040_50400702_55_dialog_content = "예리아 씨, 오늘은 그만두자. 벌써 날도 어두워졌잖아. 다들 피곤할 거야.",
  ui_story_5040_50400702_56_dialog_content = "아도니스 씨 훈련은 조금씩 하는 걸로 하고, 오늘은 자난성으로 돌아가자.",
  ui_story_5040_50400702_57_dialog_content = "음, 아이테르 군이 그렇게 말한다면 어쩔 수 없지.",
  ui_story_5040_50400702_58_dialog_content = "으...",
  ui_story_5040_50400702_59_dialog_content = "어라? 왜 그래요? 어디 아픈가요?",
  ui_story_5040_50400702_60_dialog_content = "아...아니야...",
  ui_story_5040_50400702_61_dialog_content = "생각...났어...",
  ui_story_5040_50400702_62_dialog_content = "네?",
  ui_story_5040_50400702_63_dialog_content = "사막... 사막이야...",
  ui_story_5040_50400702_64_dialog_content = "사막? 레디젤 사막이요?",
  ui_story_5040_50400702_65_dialog_content = "모르...겠어... 근데...",
  ui_story_5040_50400702_66_dialog_content = "사막... 생각났어...",
  ui_story_5040_50400702_67_dialog_content = "아까 아도니스 씨의 공격이 기억을 자극한 걸까요?",
  ui_story_5040_50400702_68_dialog_content = "만약 레디젤 사막이라면 잘됐네요. 마침 다음 목적지니까요.",
  ui_story_5040_50400702_69_dialog_content = "......",
  ui_story_5040_50400702_70_dialog_content = "다들 피곤하지? 오늘은 여기서 해산하고 쉬자.",
  ui_story_5040_50400702_71_dialog_content = "저 때문에 다들... 정말 어떻게 감사해야 할지 모르겠네요.",
  ui_story_5040_50400702_72_dialog_content = "우리 둘 문제인데 다들 여기저기 데리고 다녀서 미안해.",
  ui_story_5040_50400702_73_dialog_content = "타라, 우리 가서 일루미나 특산품 같은 거 좀 사서 다 같이 간식으로 먹자.\n지금은 그런 거 말고는 딱히 보답할 다른 방법도 없는 것 같아.",
  ui_story_5040_50400702_74_dialog_content = "하하, 그렇게 신경 쓸 거 없어.",
  ui_story_5040_50400702_75_dialog_content = "(일루미나의 특산품을... 간식으로 먹을 수 있나?)",
  ui_story_5040_50400702_76_dialog_content = "그래! 그럼 어두워지기 전에 가자!",
  ui_story_5040_50400702_77_dialog_content = "나... 가고 싶어...",
  ui_story_5040_50400702_78_dialog_content = "키아, 둘이서만 얘기하고 싶은 게 있는데, 좀 괜찮을까?",
  ui_story_5040_50400702_79_dialog_content = "네? 예리아 장로님, 갑자기 무슨... 물론 괜찮지만요.",
  ui_story_5040_50400702_80_dialog_content = "하지만 세이블이...",
  ui_story_5040_50400702_81_dialog_content = "PlayerName 군도 있잖아. 같이 돌아가 달라고 하면 돼.",
  ui_story_5040_50400702_82_dialog_content = "아니면 검은 아기새한테 뭔가 다른 사람에겐 말할 수 없는 비밀이라도 있니?",
  ui_story_5040_50400702_83_dialog_content = "그런 거 없어요!",
  ui_story_5040_50400702_84_dialog_content = "그럼 PlayerName 씨, 부탁드릴게요. 세이블을 데리고 먼저 돌아가 주세요.",
  ui_story_5040_50400702_85_dialog_content = "응, 알았어.",
  ui_story_5040_50400702_86_dialog_content = "저기...",
  ui_story_5040_50400702_87_dialog_content = "왜 그래?",
  ui_story_5040_50400702_88_dialog_content = "돌아서... 가자...",
  ui_story_5040_50400702_89_dialog_content = "돌아서?",
  ui_story_5040_50400702_90_dialog_content = "어디 가고 싶은 곳이 있어서 그래?",
  ui_story_5040_50400702_91_dialog_content = "나, 전에... 편지... 주웠어...",
  ui_story_5040_50400702_92_dialog_content = "주인한테... 돌려주고... 싶어.",
  ui_story_5040_50400702_93_dialog_content = "편지? 어디서 주웠는데? 그럼 쿠리어 길드에 갖다주면 되는 거 아니야?",
  ui_story_5040_50400702_94_dialog_content = "아도니스랑... 연습하고... 나서... 주웠어.",
  ui_story_5040_50400702_95_dialog_content = "아, 그럼 성 밖에서 주운 거네? 쿠리어가 깜빡 떨어트렸나 보다.",
  ui_story_5040_50400702_96_dialog_content = "쿠리어 길드에 안 가져가도 괜찮을까?",
  ui_story_5040_50400702_97_dialog_content = "주소... 써...있어.",
  ui_story_5040_50400702_98_dialog_content = "안...갖다주면... 많이... 기다릴...거야...",
  ui_story_5040_50400702_99_dialog_content = "그것도 그렇네. 이제 곧 관월제니까. 빨리 갖다주고 싶은 거지?",
  ui_story_5040_50400702_100_dialog_content = "도브가 네 반만큼이라도 책임감이 있었으면 얼마나 좋아.",
  ui_story_5040_50400702_101_dialog_content = "그럼 갈까? 나랑 같이 가자. 주소 어딘지 내가 좀 볼게.",
  ui_story_5040_50400702_102_dialog_content = "(근데 이 편지, 왠지 색이 바란 것 같네. 최근에 보낸 건 아닌 것 같아.)",
  ui_story_5040_50400702_103_dialog_content = "<color=#e8d9bb>똑똑똑.</color>",
  ui_story_5040_50400702_104_dialog_content = "아마... 여기...야.",
  ui_story_5040_50400702_105_dialog_content = "응, 주소는 여기가 맞아.",
  ui_story_5040_50400702_106_dialog_content = "누구십니까?",
  ui_story_5040_50400702_107_dialog_content = "실례합니다. 길에서 편지를 주웠는데요. 받을 사람 주소가 여기라서요.",
  ui_story_5040_50400702_108_dialog_content = "네? 저희 집이요? 좀 볼 수 있을까요?",
  ui_story_5040_50400702_109_dialog_content = "이, 이건...!",
  ui_story_5040_50400702_110_dialog_content = "여기가 맞죠?",
  ui_story_5040_50400702_111_dialog_content = "이 편지... 어디서 얻으신 거죠?!",
  ui_story_5040_50400702_112_dialog_content = "이 친구가 성 밖에서 주웠어요.",
  ui_story_5040_50400702_113_dialog_content = "도, 도움이... 됐어?",
  ui_story_5040_50400702_114_dialog_content = "뭐, 뭐라고 말씀드려야 할지...",
  ui_story_5040_50400702_115_dialog_content = "이건 저희 할머니 앞으로 온 편지예요.",
  ui_story_5040_50400702_116_dialog_content = "할머니요?",
  ui_story_5040_50400702_117_dialog_content = "네. 할머니는 돌아가실 때까지 계속 이 편지를 기다렸어요.\n하지만 결국 받지 못하고 돌아가셨죠.",
  ui_story_5040_50400702_118_dialog_content = "이건 할머니의 첫사랑이 보낸 편지예요.\n상대는 백야성 사람이었고... 그래서 결국 서로 맺어지지 못하셨죠.",
  ui_story_5040_50400702_119_dialog_content = "하지만 할아버지는 일찍 돌아가셨고, 할머니는 그 첫사랑과 한참 뒤에 다시 연락이 닿으셨어요.",
  ui_story_5040_50400702_120_dialog_content = "두 분은 계속 좋은 친구로서 편지를 주고받으셨어요.\n그리고 앞으로도 쭉 편지를 써서 서로의 안부를 묻기로 약속하셨어요.",
  ui_story_5040_50400702_121_dialog_content = "그런데 어느 날 편지가 오지 않게 되었고, 할머니도 곧 병에 걸리셨어요.",
  ui_story_5040_50400702_122_dialog_content = "그런데 설마...",
  ui_story_5040_50400702_123_dialog_content = "휴... 정말 운명의 장난이군요.",
  ui_story_5040_50400702_124_dialog_content = "그런 일이 있었군요...",
  ui_story_5040_50400702_125_dialog_content = "세이블, 넌 자기도 모르게 아주 좋은 일을 한 거야.",
  ui_story_5040_50400702_126_dialog_content = "정말 감사합니다! 편지는 개봉하지 않고 할머니의 무덤에 놓아 드려야겠어요.",
  ui_story_5040_50400702_127_dialog_content = "......",
  ui_story_5040_50400702_128_dialog_content = "아마 이것도 관월제의 기적이겠죠.\n부디 그분의 이야기가 할머니께 닿았으면 좋겠습니다...",
  ui_story_5040_50400702_129_dialog_content = "사랑...?",
  ui_story_5040_50400702_130_dialog_content = "네. 사랑에 얼마나 큰 힘이 있는지 가끔은 저도 놀랍다니까요.",
  ui_story_5040_50400702_131_dialog_content = "사랑은 상처를 주기도 하지만, 사람을 구하기도 하니까요.",
  ui_story_5040_50400702_132_dialog_content = "아무튼... 두 분 오늘 정말 감사했습니다.",
  ui_story_5040_50400702_133_dialog_content = "별말씀을요. 답례라면 이 친구가 받아야죠.",
  ui_story_5040_50400702_134_dialog_content = "천...만에...",
  ui_story_5040_50400702_135_dialog_content = "이제 다른 일 없으면 우리도 얼른 돌아가자.",
  ui_story_5040_50400702_136_dialog_content = "응...",
  ui_story_5040_50400702_137_dialog_content = "<color=#e8d9bb>같은 시간</color>",
  ui_story_5040_50400702_138_dialog_content = "예리아 장로님, 하실 말씀이 뭐죠?",
  ui_story_5040_50400702_139_dialog_content = "......",
  ui_story_5040_50400702_140_dialog_content = "북방의 아기새, 계속 묻고 싶었는데, 대체 언제 친척이 생긴 걸까?",
  ui_story_5040_50400702_141_dialog_content = "!!",
  ui_story_5040_50400702_142_dialog_content = "세이블... 말씀하시는 건가요?",
  ui_story_5040_50400702_143_dialog_content = "그럼 또 있어?",
  ui_story_5040_50400702_144_dialog_content = "그게...",
  ui_story_5040_50400702_145_dialog_content = "(엄청난 위압감이야!)",
  ui_story_5040_50400702_146_dialog_content = "난 이리저리 돌려 말하는 건 재미없다고 생각해.\n모처럼의 기회니까 단도직입적으로 물어볼게.",
  ui_story_5040_50400702_147_dialog_content = "쟤 오로리안 아니지?",
  ui_story_5040_50400702_148_dialog_content = "......!",
  ui_story_5040_50400702_149_dialog_content = "더 분명하게 말하자면, 통용어를 할 수 있는 암귀겠지.",
  ui_story_5040_50400702_150_dialog_content = "예리아 장로님...",
  ui_story_5040_50400702_151_dialog_content = "으음~ 우리 키아, 쿠리어가 된지도 얼마 안 됐는데, 배짱 하나는 내 상상 이상이네.",
  ui_story_5040_50400702_152_dialog_content = "정말 다시 봐야겠어.",
  ui_story_5040_50400702_153_dialog_content = "예리아 장로님! 제가 이러면 안 되는 건 알아요. 하지만...\n제발 일단은 비밀로 해 주세요!",
  ui_story_5040_50400702_154_dialog_content = "내가 비밀을 지켜 줘야 할 이유가 있을까? 왜 그런 선심을 써야 하지?",
  ui_story_5040_50400702_155_dialog_content = "맞아요. 그럴 이유도 없고, 전 이런 걸 도와달라고 할 자격도 없어요.",
  ui_story_5040_50400702_156_dialog_content = "전 그냥 간청하는 거예요...",
  ui_story_5040_50400702_157_dialog_content = "......",
  ui_story_5040_50400702_158_dialog_content = "세이블은 기억을 잃고 저한테 도와달라고 했어요.",
  ui_story_5040_50400702_159_dialog_content = "도와봤자 아무 이익도 없고, 오히려 위험해지겠죠.\n오로리안과 암귀는 언제나 적이었으니까요... 그건 저도 알아요.",
  ui_story_5040_50400702_160_dialog_content = "하지만 전 모두의 마음을 잇는 다리가 되고 싶어서 쿠리어가 됐어요.\n그저 그런 간단한 이유예요. 세이블한테도 마찬가지고요.",
  ui_story_5040_50400702_161_dialog_content = "너무 불쌍해 보여서 아무 생각 없이 도와주겠다고 약속한 건...\n분명히 제가 순진하고 충동적이었어요.",
  ui_story_5040_50400702_162_dialog_content = "하지만 전 제 마음을 솔직하게 따르고 그런 결정을 내렸어요.\n물론 책임도 질 거예요. 필요하다면... 대가도 치를 거고요.",
  ui_story_5040_50400702_163_dialog_content = "만약 내가 저 애를 공격한다면, 넌 날 막을 거니?",
  ui_story_5040_50400702_164_dialog_content = "네, 예리아 장로님.",
  ui_story_5040_50400702_165_dialog_content = "전 쿠리어잖아요. 한번 시작한 건 꼭 해낼 거예요.\n그러니 이 일도 제가 무사히 처리할게요.",
  ui_story_5040_50400702_166_dialog_content = "......",
  ui_story_5040_50400702_167_dialog_content = "넌 내 생각보다 더 재밌는 애구나. 조금 유치하긴 해도, 난 성실한 아이는 싫지 않아.",
  ui_story_5040_50400702_168_dialog_content = "그럼 상황을 지켜보는 걸로 하자. 행운을 빌게.",
  ui_story_5040_50400702_169_dialog_content = "그럼... 비밀로 해주신다는 건가요?",
  ui_story_5040_50400702_170_dialog_content = "감사합니다! 예리아 장로님!",
  ui_story_5040_50400702_171_dialog_content = "무슨 일이 있어도 끝까지 책임질게요. 안심하세요!",
  ui_story_5040_50400801_1_dialog_content = "세이블, 네 덕분에 좋은 일을 할 수 있었어. 이제 우리도 빨리 돌아가자.",
  ui_story_5040_50400801_2_dialog_content = "응...",
  ui_story_5040_50400801_3_dialog_content = "괜찮아? 계속 안색이 안 좋은 것 같은데.",
  ui_story_5040_50400801_4_dialog_content = "안...색?",
  ui_story_5040_50400801_5_dialog_content = "응. 이런 말은 좀 그런 것 같지만... 너 왠지 얼굴이 거메진 것 같은데?",
  ui_story_5040_50400801_6_dialog_content = "영양 부족인가? 아니면 어디 불편해?",
  ui_story_5040_50400801_7_dialog_content = "아마... 아닐...거야...",
  ui_story_5040_50400801_8_dialog_content = "캬악──!",
  ui_story_5040_50400801_9_dialog_content = "크오오!",
  ui_story_5040_50400801_10_dialog_content = "뭐야?! 암귀?!",
  ui_story_5040_50400801_11_dialog_content = "자난성 안에서 암귀를 보는 건 처음이잖아!",
  ui_story_5040_50400801_12_dialog_content = "으아아! 살려줘!",
  ui_story_5040_50400801_13_dialog_content = "아! 자...잡았어... 내가!",
  ui_story_5040_50400801_14_dialog_content = "무, 무섭지...않아...",
  ui_story_5040_50400801_15_dialog_content = "세이블! 넌 애를 데리고 뒤로 물러나!",
  ui_story_5040_50400802_1_dialog_content = "둘 다 괜찮아?",
  ui_story_5040_50400802_2_dialog_content = "괘, 괜찮아...",
  ui_story_5040_50400802_3_dialog_content = "으아아앗! 누, 누나 무섭게 생겼어!",
  ui_story_5040_50400802_4_dialog_content = "난...",
  ui_story_5040_50400802_5_dialog_content = "그냥 어린애 말일 뿐이야. 나쁜 뜻은 없으니까 신경 쓰지 마.",
  ui_story_5040_50400802_6_dialog_content = "근데 자난성에 어떻게 암귀가 나타난 거지?",
  ui_story_5040_50400802_7_dialog_content = "휴! 여러분, 도와주셔서 감사합니다!",
  ui_story_5040_50400802_8_dialog_content = "유라?",
  ui_story_5040_50400802_9_dialog_content = "방금 그건 미자드 씨가 실험용으로 준비한 암귀입니다.\n어떻게 된 건지 갑자기 소란을 피우더니 도망쳐 버렸지 뭡니까.",
  ui_story_5040_50400802_10_dialog_content = "사상자가 발생하지 않아서 다행입니다. 두 분 정말 감사합니다.",
  ui_story_5040_50400802_11_dialog_content = "실험용 암귀? 전에 우리 테스트할 때 썼던 그런 거 말이야?",
  ui_story_5040_50400802_12_dialog_content = "네. 미자드 씨는 다양한 유형의 암귀를 잡으셨죠.\n어떤 실험에 쓰는 건지는 모르겠지만...",
  ui_story_5040_50400802_13_dialog_content = "잡아온 암귀들은 빠르게 소모돼 버리더군요.",
  ui_story_5040_50400802_14_dialog_content = "!!!",
  ui_story_5040_50400802_15_dialog_content = "실험용이면 잘 간수해야지! 밖에 나와서 사람을 해치면 큰일이잖아!",
  ui_story_5040_50400802_16_dialog_content = "그러게 말입니다. 전에는 이런 일이 없었는데 말이죠.\n어쩌면 두 분에게 암귀를 끌어당기는 특별한 힘이 있는 건지도 모르겠군요.",
  ui_story_5040_50400802_17_dialog_content = "참, 세이블. 미자드 씨한테 진찰을 받아보는 건 어때?\n연구실엔 다양한 약이 있거든.",
  ui_story_5040_50400802_18_dialog_content = "어디 아프면 약 받으면 돼.",
  ui_story_5040_50400802_19_dialog_content = "피...필요 없어!",
  ui_story_5040_50400802_20_dialog_content = "갑자기... 이, 일이... 생각났어!",
  ui_story_5040_50400802_21_dialog_content = "나... 키아한테... 갈래!",
  ui_story_5040_50400802_22_dialog_content = "어?!",
  ui_story_5040_50400802_23_dialog_content = "후훗, 꽤 재미있는 친구네요.",
  ui_story_5040_50400802_24_dialog_content = "(날도 늦었고, 세이블이랑 다들 잘 돌아갔겠지. 나도 돌아가자.)",
  ui_story_5040_50400802_25_dialog_content = "키...키아!",
  ui_story_5040_50400802_26_dialog_content = "세이블? 왜 여기 있어요? PlayerName 씨랑 같이 있지 않았어요?",
  ui_story_5040_50400802_27_dialog_content = "키아랑... 같이... 있고 싶어.",
  ui_story_5040_50400802_28_dialog_content = "그래요. 그럼 같이 돌아가요.",
  ui_story_5040_50400802_29_dialog_content = "<color=#e8d9bb>꼬르륵──</color>",
  ui_story_5040_50400802_30_dialog_content = "무슨...소리가...났어.",
  ui_story_5040_50400802_31_dialog_content = "아, 제 배에서 난 소리예요. 미안해요.",
  ui_story_5040_50400802_32_dialog_content = "계속 아무것도 못 먹어서 배가 고파졌거든요.",
  ui_story_5040_50400802_33_dialog_content = "나도... 배... 고파.",
  ui_story_5040_50400802_34_dialog_content = "세이블도 배고파요? 그럼 어디서 뭐 좀 먹고 들어갈까요?",
  ui_story_5040_50400802_35_dialog_content = "안 돼... 내 모습... 사람들한테... 못 보여줘...",
  ui_story_5040_50400802_36_dialog_content = "세이블?",
  ui_story_5040_50400802_37_dialog_content = "그런 말 하면 안 돼요. 세이블은 오로리안과 조금 다를 뿐인걸요.\n세이블은 마음씨가 착하잖아요!",
  ui_story_5040_50400802_38_dialog_content = "그럼 제가 가서 빵을 사 올 테니까, 돌아가서 먹을까요?",
  ui_story_5040_50400802_39_dialog_content = "응...",
  ui_story_5040_50400802_40_dialog_content = "그러고 보니 일루미나에 대해서는 뭔가 떠오르는 기억이 없나요?",
  ui_story_5040_50400802_41_dialog_content = "없어...",
  ui_story_5040_50400802_42_dialog_content = "좋아요. 그래도 사막이 생각났다고 했으니까,\n레디젤 사막에 도착하면 잘 둘러보기로 해요.",
  ui_story_5040_50400802_43_dialog_content = "너무 걱정하지 마요.",
  ui_story_5040_50400802_44_dialog_content = "고마워...",
  ui_story_5040_50400802_45_dialog_content = "침, 방금 역 건너편에 오렌지빵 파는 노점이 있는 것 같았어요.\n사 올테니까 여기서 기다리고 있어요.",
  ui_story_5040_50400802_46_dialog_content = "금방 돌아올 테니까 얌전히 있어야 해요.",
  ui_story_5040_50400802_47_dialog_content = "......!",
  ui_story_5040_50400802_48_dialog_content = "지금... 그... 말...",
  ui_story_5040_50400802_49_dialog_content = "금방 돌아올 테니까 얌전히 여기서 기다려 줘.",
  ui_story_5040_50400802_50_dialog_content = "여기 잘 있어. 사면 바로 돌아올 테니까.",
  ui_story_5040_50400802_51_dialog_content = "에드워드, 시간이 한참 됐는데, 왜 아직도 안 오는 거야?",
  ui_story_5040_50400802_52_dialog_content = "왜... 날 보러 안 오는 거야?",
  ui_story_5040_50400802_53_dialog_content = "왜 돌아오지 않는 건데? 내가 뭐 잘못한 거야?",
  ui_story_5040_50400802_54_dialog_content = "<size=45>돌아와!</size>",
  ui_story_5040_50400802_55_dialog_content = "절망하고 있니? 고향을 떠나서 의지할 사람도 없겠지?\n이 씨앗을 받아. 그럼 이제 아무것도 무섭지 않게 될 거야.",
  ui_story_5040_50400802_56_dialog_content = "약자의 고통 따위는 다시는 맛보지 않아도 돼. 넌 네 상상보다 훨씬 더 강해질 수 있어.",
  ui_story_5040_50400802_57_dialog_content = "아아아아악!",
  ui_story_5040_50400802_58_dialog_content = "(관월제에 시나몬롤을 살 수 있다니 정말 운이 좋네. 세이블도 분명히 좋아하겠지.)",
  ui_story_5040_50400802_59_dialog_content = "세이블... 세...",
  ui_story_5040_50400802_60_dialog_content = "꺄악! 언니! 암귀가 있어!",
  ui_story_5040_50400802_61_dialog_content = "암귀가 쓰러져 있어!",
  ui_story_5040_50400802_62_dialog_content = "잠깐만, 이거 암귀인가? 아니면... 뭔가 다른 건가?",
  ui_story_5040_50400802_63_dialog_content = "군단 병사들을 불러올까?",
  ui_story_5040_50400802_64_dialog_content = "!!!",
  ui_story_5040_50400802_65_dialog_content = "잠깐만요!",
  ui_story_5040_50400802_66_dialog_content = "세이블! 세이블, 왜 그래요?!",
  ui_story_5040_50400802_67_dialog_content = "아...",
  ui_story_5040_50400802_68_dialog_content = "세이블, 자, 가요!",
  ui_story_5040_50400802_69_dialog_content = "어이! 잠깐 기다려! 당신들 뭐야?!",
  ui_story_5040_50400802_70_dialog_content = "하... 하아...",
  ui_story_5040_50400802_71_dialog_content = "쉿!",
  ui_story_5040_50400802_72_dialog_content = "...으읍.",
  ui_story_5040_50400802_73_dialog_content = "들키면 큰일이에요!",
  ui_story_5040_50400802_74_dialog_content = "혹시 근처에서 특이한 모습의 암귀를 못 보셨습니까?\n어떤 아가씨랑 같이 움직이고 있었습니다.",
  ui_story_5040_50400802_75_dialog_content = "그거 큰일이네, 아까 보니까 지상으로 도망간 것 같던데.\n병사를 불러서 추격하는 게 어때?",
  ui_story_5040_50400802_76_dialog_content = "네? 벌써 그렇게 멀리 갔다고요? 알겠습니다!\n전 부대원은 추격하라!",
  ui_story_5040_50400802_77_dialog_content = "예리아 장로님... 고마워요.",
  ui_story_5040_50400802_78_dialog_content = "이제 간 것 같네요. 세이블, 어디 다친 곳은 없나요?! 제가 좀 볼게요.",
  ui_story_5040_50400802_79_dialog_content = "괘...괜찮아.",
  ui_story_5040_50400802_80_dialog_content = "미안...해... 걱정하게... 해서...",
  ui_story_5040_50400802_81_dialog_content = "그게 무슨 소리예요.\n당신이 다쳤으면 전 당신을 혼자 두고 간 걸 평생 후회했을 거라구요.",
  ui_story_5040_50400802_82_dialog_content = "...키아.",
  ui_story_5040_50400802_83_dialog_content = "나... 생각났어.",
  ui_story_5040_50400802_84_dialog_content = "생각났다고요? 뭐가 생각났죠?",
  ui_story_5040_50400802_85_dialog_content = "누가... 전에... 너랑... 똑같은 말... 했어...",
  ui_story_5040_50400802_86_dialog_content = "근데... 다시는... 돌아오지... 않았어.",
  ui_story_5040_50400802_87_dialog_content = "난... 그 사람... 찾으러... 아주 먼 곳... 갔어.",
  ui_story_5040_50400802_88_dialog_content = "그 사람... 나... 좋아한다고 했어.",
  ui_story_5040_50400802_89_dialog_content = "근데... 결국... 날... 버렸어.",
  ui_story_5040_50400802_90_dialog_content = "나... 집을 나와서... 무섭고... 외로웠어.",
  ui_story_5040_50400802_91_dialog_content = "그리고...어떤 사람이... 씨앗을... 줬어.",
  ui_story_5040_50400802_92_dialog_content = "...강해질... 수 있다고... 했어.",
  ui_story_5040_50400802_93_dialog_content = "역시 당신은 오로리안이었군요!",
  ui_story_5040_50400802_94_dialog_content = "대체 어떻게 그런 일이 생긴 거죠?!",
  ui_story_5040_50400802_95_dialog_content = "그... 마법의 물약... 내... 의식을... 회복시켜 줬어.",
  ui_story_5040_50400802_96_dialog_content = "난... 다 잊어버렸어... 아무것도... 못 믿어.",
  ui_story_5040_50400802_97_dialog_content = "그냥... 집에 가고... 싶어.",
  ui_story_5040_50400802_98_dialog_content = "세이블...",
  ui_story_5040_50400802_99_dialog_content = "제가 데려다줄게요. 반드시요!",
  ui_story_5040_50400802_100_dialog_content = "내일 레디젤 사막으로 출발해요. 어쩌면 거기가 세이블의 집일지도 몰라요.",
  ui_story_5040_50400802_101_dialog_content = "고마워... 키아.",
  ui_story_5040_50400802_102_dialog_content = "나... 점점... 의식이... 흐릿해.",
  ui_story_5040_50400802_103_dialog_content = "아마... 오래... 못... 버텨.",
  ui_story_5040_50400802_104_dialog_content = "만약... 의식... 없어지면... 네가...",
  ui_story_5040_50400802_105_dialog_content = "그만해요! 그렇게 되기 전에 꼭 집에 데려다줄게요!\n게다가 의식을 유지할 수 있는 다른 방법이 있을지도 몰라요!",
  ui_story_5040_50400802_106_dialog_content = "샌드버그도 있잖아요? 분명히 다른 방법이 있을 거예요.",
  ui_story_5040_50400802_107_dialog_content = "키아...",
  ui_story_5040_50400802_108_dialog_content = "내일 출발해요, 절대 안 늦을 거예요!",
  ui_story_5040_50400802_109_dialog_content = "반드시 집에 보내줄게요.",
  ui_story_5040_50400901_1_dialog_content = "도착했어. 편히 앉아.",
  ui_story_5040_50400901_2_dialog_content = "여기가 바로 쿠리어 길드 레디젤 렌치 지부인가요?",
  ui_story_5040_50400901_3_dialog_content = "외벽은 낡았지만, 내부는 생각했던 것과 다르게 상당히 화려하네요.",
  ui_story_5040_50400901_X3_dialog_content = "맞아, 게다가 위치도 찾기 힘든 곳에 있어!",
  ui_story_5040_50400901_X4_dialog_content = "원래도 레디젤 렌치 캠프 건물들은 위치도 멋대로고 길도 찾기 힘든데...",
  ui_story_5040_50400901_X5_dialog_content = "여긴 그런 골목에서도 몇십 분이나 더 걸어야 도착할 수 있다니까!",
  ui_story_5040_50400901_X6_dialog_content = "그래서 처음 왔을 땐 진짜 한참을 헤맸다고.",
  ui_story_5040_50400901_X7_dialog_content = "헤매긴 했어도 결국엔 도착한 걸 보면, 길 찾기에 소질이 있는 편이네!",
  ui_story_5040_50400901_X8_dialog_content = "난 여기 처음 왔을 때 아무리 찾아도 못 찾겠어서 거의 포기할 뻔했다니까.",
  ui_story_5040_50400901_4_dialog_content = "이 내부 장식들도 두 번째 보는 건데, 아무리 생각해도 좀 의외야.",
  ui_story_5040_50400901_5_dialog_content = "내부가 화려한 것도 화려한 거지만, 고급 장식품이 잔뜩 있어서 진짜 깜짝 놀랐지 뭐야.",
  ui_story_5040_50400901_6_dialog_content = "이런 건 전혀 레디젤 렌치 스타일이 아니잖아!",
  ui_story_5040_50400901_7_dialog_content = "너 설마 날 거칠고 저속한 도적처럼 생각해 왔던 거니?",
  ui_story_5040_50400901_8_dialog_content = "아니요, 제 말은 그게 아니라...",
  ui_story_5040_50400901_9_dialog_content = "뭐, 됐어. 너희 놀리는 건 그만할래~",
  ui_story_5040_50400901_10_dialog_content = "예리아 장로님, 세이블이랑 여길 좀 둘러봐도 될까요?",
  ui_story_5040_50400901_11_dialog_content = "그래. 어디든 마음껏 둘러봐도 좋아~",
  ui_story_5040_50400901_12_dialog_content = "네?",
  ui_story_5040_50400901_13_dialog_content = "대신 다 보고 나면 전부 제자리로 돌아와야 해.",
  ui_story_5040_50400901_14_dialog_content = "네! 알겠어요!",
  ui_story_5040_50400901_15_dialog_content = "세이블, 가 보죠!",
  ui_story_5040_50400901_16_dialog_content = "그럼 나도 차량이랑 무기를 준비하러 가 봐야겠어.",
  ui_story_5040_50400901_17_dialog_content = "조금 있으면 날이 어두워질 테니까, 오늘 밤은 다들 여기서 쉬어.",
  ui_story_5040_50400901_18_dialog_content = "차량 준비요? 콜로서스를 타고 가면 더 빠르게 도착할 수 있지 않을까요?",
  ui_story_5040_50400901_X18_dialog_content = "게다가 크기도 크기니만큼 차량보다 훨씬 안전할 테고요...",
  ui_story_5040_50400901_19_dialog_content = "샌드버그는 지표면과 지하에서 생활하는 생명체야.",
  ui_story_5040_50400901_20_dialog_content = "아주 약삭빠른 녀석들이라 지하 동굴을 통해 빠르게 이동도 하고, 거기에 몸도 숨겨.",
  ui_story_5040_50400901_21_dialog_content = "첫 시도에 붙잡지 못하면, 녀석들 모두 순식간에 도망쳐 버리고 말 거야.",
  ui_story_5040_50400901_X21_dialog_content = "네?!",
  ui_story_5040_50400901_X22_dialog_content = "예리아 씨 말이 맞아.",
  ui_story_5040_50400901_22_dialog_content = "콜로서스가 빠르고 안전하긴 하지만, 샌드버그를 발견하자마자 공격하는 건 불가능하거든.",
  ui_story_5040_50400901_X23_dialog_content = "나도 그래서 고생할 뻔했던 적이 있어서 잘 알아!",
  ui_story_5040_50400901_23_dialog_content = "그랬군요...",
  ui_story_5040_50400901_24_dialog_content = "아도니스, 넌 이 사막이라는 곳에 대해 아직 배워야 할 게 많아.",
  ui_story_5040_50400901_25_dialog_content = "그럼 난 먼저 가 볼게. 내일 아침 일찍 샌드버그를 찾으러 떠나자.",
  ui_story_5040_50400901_26_dialog_content = "<color=#e8d9bb>꼬르륵──</color>",
  ui_story_5040_50400901_27_dialog_content = "앗!",
  ui_story_5040_50400901_28_dialog_content = "하루 종일 바쁘게 뛰어다녔더니, 식사할 시간도 없었네요...",
  ui_story_5040_50400901_29_dialog_content = "<color=#e8d9bb>꼬르르륵──</color>",
  ui_story_5040_50400901_30_dialog_content = "나도 좀 배고파졌어.",
  ui_story_5040_50400901_31_dialog_content = "이왕 레디젤 사막에 왔으니까, 내가 모두한테 레디젤 렌치 스타일 만찬을 준비해 줄게!",
  ui_story_5040_50400901_32_dialog_content = "밖에 모닥불을 피워서 바비큐를 만들어야겠어.",
  ui_story_5040_50400901_33_dialog_content = "나도 돕고 싶어!",
  ui_story_5040_50400901_34_dialog_content = "(나 혼자 남았네.)",
  ui_story_5040_50400901_35_dialog_content = "(역시 타라 씨랑 아도니스 씨는 방해 안 하는 게 좋겠지.\n키아랑 세이블 쪽은 내가 도와줄 게 별로 없어 보이고.)",
  ui_story_5040_50400901_36_dialog_content = "(그나저나 샌드버그면 크기가 어마어마할 거잖아!\n근데 우리 지금 다 합쳐 봐야 몇 명 안 되는데, 정말 괜찮으려나?)",
  ui_story_5040_50400901_37_dialog_content = "(예리아 씨는 엄청 강해 보이고, 타라 씨도 전투 실력이 대단해 보였지만,\n그래도 역시 걱정이 된단 말이지...)",
  ui_story_5040_50400901_38_dialog_content = "(이따가 예리아 씨한테 도와줄 사람을 찾아보는 건 어떻겠냐고 물어봐야겠어.)",
  ui_story_5040_50400901_39_dialog_content = "어머? 아이테르 군, 너무 걱정돼서 여기까지 찾아온 거니?",
  ui_story_5040_50400901_40_dialog_content = "자, 자꾸 그렇게 놀리는 것처럼 부르지 말아 주세요.",
  ui_story_5040_50400901_41_dialog_content = "안심하렴, 이 사막은 내가 우리 집 앞마당처럼 훤히 알고 있거든.",
  ui_story_5040_50400901_42_dialog_content = "벌써 차량 상태 점검도 끝냈고, 보급품도 충분히 준비해 뒀어.\n그러니까 다들 제 앞가림만 제대로 하면 돼.",
  ui_story_5040_50400901_43_dialog_content = "하지만 샌드버그는 아주 위험한 생명체잖아요.\n전 그래도 지금 우리 인원으론 상대하기 힘들지 않을까 걱정이 돼요.",
  ui_story_5040_50400901_44_dialog_content = "도와줄 사람을 좀 찾는 편이 낫지 않을까요? 사메야마나 아주르 씨는 어때요?",
  ui_story_5040_50400901_45_dialog_content = "필요 없어.",
  ui_story_5040_50400901_46_dialog_content = "그래도...",
  ui_story_5040_50400901_47_dialog_content = "그 누구의 도움도 필요 없어.",
  ui_story_5040_50400901_48_dialog_content = "나 하나만으로도 충분해.\n적은 샌드버그 한 마리일 뿐이잖아. 두어대 때리면 끝날 거야.",
  ui_story_5040_50400901_49_dialog_content = "얘기 다 끝났으면 이제 돌아가 주겠니?",
  ui_story_5040_50400901_50_dialog_content = "난 아직 할 일이 남아서 바쁘고, 꼬마 친구 관심은 별로 필요하지 않거든.",
  ui_story_5040_50400901_51_dialog_content = "......",
  ui_story_5040_50400901_52_dialog_content = "알겠어요.",
  ui_story_5040_50400901_S52_dialog_content = "전 스카이워커호로 돌아가 볼게요.",
  ui_story_5040_50400901_53_dialog_content = "(으... 예리아 씨한테 이렇게 쫓겨나 버리다니.)",
  ui_story_5040_50400901_54_dialog_content = "(됐어, 신경 쓰지 말라는데, 그럼 신경 안 써 주면 되는 거잖아!)",
  ui_story_5040_50400901_55_dialog_content = "......",
  ui_story_5040_50400901_X55_dialog_content = "(지금까지 예리아 씨는 일이 생기면 강 건너 불구경하는 식이었지.)",
  ui_story_5040_50400901_X56_dialog_content = "(쿠리어 길드의 장로라곤 하지만, 영 믿음이 안 가.)",
  ui_story_5040_50400901_X57_dialog_content = "(안전을 위해선 역시 레디젤 렌치 사람들한테 메시지를 보내 두는 편이 좋겠어.)",
  ui_story_5040_50400901_X58_dialog_content = "(누구라도 근처에 있어서 답장을 해 준다면 좋겠는데...)",
  ui_story_5040_50400901_56_dialog_content = "<color=#e8d9bb>삑──</color>",
  ui_story_5040_50400901_57_dialog_content = "여긴 오디, PlayerName, 확인했다면 회신해 줘.",
  ui_story_5040_50400901_58_dialog_content = "오디! 너였구나!",
  ui_story_5040_50400901_59_dialog_content = "여기는 PlayerName! 메시지 확인했어. 살았다! 진짜로 누가 답장해 줄 줄은 몰랐어!",
  ui_story_5040_50400901_60_dialog_content = "무슨 일 있어?",
  ui_story_5040_50400901_61_dialog_content = "오디, 너 혹시 분홍색 샌드버그에 대해 아는 것 좀 있어?",
  ui_story_5040_50400901_62_dialog_content = "분홍색... 샌드버그? 음, 들어 본 것 같긴 한데.",
  ui_story_5040_50400901_63_dialog_content = "아, 기억났어. 한 달 전인가? 사메야마 대장이 분홍색 샌드버그 한 마리를 봤다고 그랬었어.",
  ui_story_5040_50400901_64_dialog_content = "그런 색을 가진 샌드버그는 처음 봤다면서 잡아야겠다고 사람들이랑 몰려갔었는데,\n결국엔 녀석을 놓쳤거든.",
  ui_story_5040_50400901_65_dialog_content = "자세한 건 나도 잘 모르니까, 대장을 불러올게. 직접 물어봐.",
  ui_story_5040_50400901_66_dialog_content = "응! 그럼 부탁해!",
  ui_story_5040_50400901_67_dialog_content = "여어, 너였냐? PlayerName.",
  ui_story_5040_50400901_68_dialog_content = "오디가 그러던데, 분홍색 샌드버그에 대해 알고 싶다고?",
  ui_story_5040_50400901_69_dialog_content = "맞아! 혹시 아는 거 있어?",
  ui_story_5040_50400901_70_dialog_content = "아주 빠삭하게 알고 있지. 그 녀석은 내 손에서 살아 도망간 몇 안 되는 샌드버그중 하나거든.",
  ui_story_5040_50400901_71_dialog_content = "한 달 전에 나도 녀석을 사냥하려고 했었는데,\n녀석이 도망치는 바람에 비늘 하나밖에 손에 못 넣었지.",
  ui_story_5040_50400901_72_dialog_content = "쳇, 진짜 아깝게 됐다니까. 비늘 하나만 팔았는데도 짭짤했으니까,\n한 마리를 통으로 잡았으면 떼돈을 벌었을 텐데.",
  ui_story_5040_50400901_73_dialog_content = "그전까지 분홍색 샌드버그라는 걸 본 사람은 아무도 없었다고.\n이 세상에 딱 그거 한 마리밖에 없을지도 몰라. 물건은 귀할수록 비싼 법이고 말이야!",
  ui_story_5040_50400901_74_dialog_content = "근데 네가 왜 분홍색 샌드버그를 찾는 거냐? 설마 예리아랑 같이 있냐?",
  ui_story_5040_50400901_75_dialog_content = "어떻게 알았어?!",
  ui_story_5040_50400901_76_dialog_content = "예리아의 언령이 레디젤 사막에 있는 샌드버그 서식지 몇 곳을\n정신없이 날아다니고 있는 걸 봤거든!",
  ui_story_5040_50400901_77_dialog_content = "이맘때 샌드버그를 찾아 돌아다니고 있는 거면 뻔하잖냐.\n그 커다란 분홍색 녀석을 찾고 있는 거겠지.",
  ui_story_5040_50400901_78_dialog_content = "루미나틱스를 무턱대고 그렇게 강하게 쓰다니, 마구잡이로 들쑤시는 거밖에 더 되냐고.",
  ui_story_5040_50400901_79_dialog_content = "사메야마, 그럼 그 분홍색 샌드버그가 어디 있는지도 알아?",
  ui_story_5040_50400901_80_dialog_content = "당연하지. 근데 맨입으론 안 되지, 애송이. 오는 정이 있어야 가는 정도 있는 거 아니겠냐?",
  ui_story_5040_50400901_81_dialog_content = "그럼... 내가...",
  ui_story_5040_50400901_82_dialog_content = "하하하, 놀라서 벌벌 떨기는. 왜, 내가 널 탈탈 털기라도 할까 걱정이냐?",
  ui_story_5040_50400901_83_dialog_content = "다음에 레디젤 렌치에 올 때, 이브한테 초콜릿 좀 사다 줘라.",
  ui_story_5040_50400901_84_dialog_content = "움브라톤에서 관 어쩌고 하는 명절 때문에 기간 한정 초콜릿을 출시했는데,\n이브가 계속 그걸 먹어 보고 싶다고 하잖아.",
  ui_story_5040_50400901_85_dialog_content = "마침 넌 콜로서스를 타고 여기저기 돌아다닐 수 있으니까, 이브한테 그 초콜릿 좀 사다 주라고.",
  ui_story_5040_50400901_86_dialog_content = "문제없지!",
  ui_story_5040_50400901_87_dialog_content = "그럼 약속이다.",
  ui_story_5040_50400901_88_dialog_content = "아무튼, 전에 그 녀석이랑 맞붙었을 때 보니까, 상당히 영악해서 구석구석 잘도 숨더군.",
  ui_story_5040_50400901_89_dialog_content = "하지만 도망치기 전에 내가 제대로 한 방 먹여서 몸 왼쪽의 비늘들이 다 박살이 났었지.",
  ui_story_5040_50400901_90_dialog_content = "그리고 며칠을 뒤쫓았지만, 결국 흔적을 놓치고 말았다.\n마지막으로 녀석을 본 건 사막 깊은 곳 근처에 있는 오아시스 쪽 구역이었지.",
  ui_story_5040_50400901_91_dialog_content = "지금 그 녀석이 확실히 어디 있는진 나도 몰라.",
  ui_story_5040_50400901_92_dialog_content = "녀석을 노릴 생각이라면 내가 말한 그 장소에 가 보는 것도 좋을 거다.",
  ui_story_5040_50400901_93_dialog_content = "알겠어! 알려 줘서 고마워, 사메야마.",
  ui_story_5040_50400901_94_dialog_content = "예리아가 있으면 그 녀석이랑 맞붙어도 별문젠 없겠지만,\n그래도 꽤 약삭빠른 녀석이니까 조심하라고.",
  ui_story_5040_50400901_95_dialog_content = "그렇게 확신하는 거 보면 예리아 씨에 대해 잘 아나 봐?",
  ui_story_5040_50400901_96_dialog_content = "전혀. 그 녀석은 언제나 혼자 다니고, 다른 사람이랑은 거의 말도 안 해.",
  ui_story_5040_50400901_97_dialog_content = "하지만 레디젤 사막에서 혼자 멀쩡히 잘살고 있는 것만 봐도,\n실력만큼은 확실하단 거 아니겠냐.",
  ui_story_5040_50400901_98_dialog_content = "게다가 몇 안 되는 사막 담당 쿠리어라 평소에 여러모로 도움을 받고 있기도 하고.",
  ui_story_5040_50400901_99_dialog_content = "그러니까 예리아가 있다면 마음 놓고 따라가도 된다는 거다! 틀릴 일은 없으니까!",
  ui_story_5040_50400901_100_dialog_content = "그렇구나...",
  ui_story_5040_50400901_101_dialog_content = "잘 알겠어!",
  ui_story_5040_50400901_102_dialog_content = "그럼 얘기는 여기까지 하자고.\n이브한테 제대로 안 쉬고 있다고 한 소리 들을 것 같으니까.",
  ui_story_5040_50400901_103_dialog_content = "응, 다음에 봐!",
  ui_story_5040_50400901_104_dialog_content = "(일단 지금 바로 예리아 씨를 만나러 가지 않는 게 좋을 것 같네.\n타라 씨랑 아도니스 씨한테 먼저 이 정보들을 알려주고 오자.)",
  ui_story_5040_50400901_105_dialog_content = "(마침 배도 고프니까, 가서 식사 메뉴가 뭔지 확인해 봐야지!)",
  ui_story_5040_50400901_106_dialog_content = "<color=#e8d9bb>같은 시간, 쿠리어 길드 레디젤 렌치 지부</color>",
  ui_story_5040_50400901_107_dialog_content = "아직까지 미송달 상태인 우편물들은 다 여기 쌓여 있을 거예요.",
  ui_story_5040_50400901_108_dialog_content = "레디젤 사막은 넓기도 넓지만, 여기 사람들은 한곳에 가만히 머무는 법이 없어서\n주인 없는 편지도 무척 많거든요.",
  ui_story_5040_50400901_109_dialog_content = "원하는 물건을 찾으려면 아마 한참 찾아야 할 거예요.",
  ui_story_5040_50400901_110_dialog_content = "내가, 도울, 게.",
  ui_story_5040_50400901_111_dialog_content = "같이 열심히 찾아보죠! 일단 편지가 몇 통 정도 있는지 확인부터 해 봐야겠어요.",
  ui_story_5040_50400901_112_dialog_content = "편지, 많아!",
  ui_story_5040_50400901_113_dialog_content = "잠깐만요, 이 편지들 위에 작은 라벨 같은 게 붙어 있어요.",
  ui_story_5040_50400901_114_dialog_content = "「수취인 실종」, 「수취인 불명」, 「수취 거부」...",
  ui_story_5040_50400901_115_dialog_content = "의외로 분류가 다 나뉘어 있었네요!",
  ui_story_5040_50400901_116_dialog_content = "키아, 저거, 봐.",
  ui_story_5040_50400901_117_dialog_content = "여기엔 「같은 우표 사용」이라고 붙어 있네요?",
  ui_story_5040_50400901_118_dialog_content = "라벨 아래에 작게 「동일 발신인으로 추정됨」이라고 적혀 있어요.",
  ui_story_5040_50400901_119_dialog_content = "위에 붙어 있는 우표는 세이블 거랑 똑같아요!",
  ui_story_5040_50400901_120_dialog_content = "이거, 내, 편지들...",
  ui_story_5040_50400901_121_dialog_content = "예상보다 빨리 찾을 수 있어서 다행이에요.",
  ui_story_5040_50400901_122_dialog_content = "그럼 어서 이 편지들을 읽어 보도록 해요.",
  ui_story_5040_50400901_123_dialog_content = "응.",
  ui_story_5040_50400901_124_dialog_content = "「나한테 편지 써 줘서 고마워. 당신이랑 친해져서 정말 기뻐.」",
  ui_story_5040_50400901_125_dialog_content = "「사막은 굉장히 더워서 다들 멀리 떨어져 살아.\n그래서 쿠리어가 있어야 서로 편지라도 주고받을 수 있어.」",
  ui_story_5040_50400901_126_dialog_content = "「만약 당신과 함께할 수 있다면, 이 사막을 떠나야 한대도 난 그렇게 할 거야.」",
  ui_story_5040_50400901_127_dialog_content = "이 편지들은 세이블이랑 그 녀석이 처음 만났을 때 적은 건가 봐요.",
  ui_story_5040_50400901_128_dialog_content = "근데 편지마다 받는 사람 주소도 제각각이고, 보내는 사람 주소도 안 적혀 있네요.",
  ui_story_5040_50400901_129_dialog_content = "혹시 세이블의 집이 이 사막에 있는 건 아닐까요?",
  ui_story_5040_50400901_130_dialog_content = "으...",
  ui_story_5040_50400901_131_dialog_content = "으윽!",
  ui_story_5040_50400901_132_dialog_content = "세이블?!",
  ui_story_5040_50400901_133_dialog_content = "나... 기억났어...",
  ui_story_5040_50400901_134_dialog_content = "우리 집, 사막, 깊은 곳...",
  ui_story_5040_50400901_135_dialog_content = "하지만, 위치, 기억 안 나...",
  ui_story_5040_50400901_136_dialog_content = "괜찮아요. 유용한 단서는 이미 많이 찾았으니까요.\n지금부턴 사막에 사는 사람들한테 물어보면 될 거예요!",
  ui_story_5040_50400901_137_dialog_content = "그러니까 과거를 기억해 내려고 무리하지 말고, 우선 푹 쉬어요.",
  ui_story_5040_50400901_138_dialog_content = "당신 의뢰를 받은 이상, 제가 쿠리어로서 반드시 책임을 질게요.",
  ui_story_5040_50400901_139_dialog_content = "응...",
  ui_story_5040_50400901_140_dialog_content = "세이블, 왜 그래요? 기운이 없어 보이네요.",
  ui_story_5040_50400901_141_dialog_content = "타라, 아도니스... 두 사람, 사이 좋아...",
  ui_story_5040_50400901_142_dialog_content = "서로, 아껴, 서로, 도와...",
  ui_story_5040_50400901_143_dialog_content = "나, 부러워...",
  ui_story_5040_50400901_144_dialog_content = "(세이블은 자기가 사랑한 사람한테 다정하게 대해진 적도 없고, 마음도 보답받지 못했어.)",
  ui_story_5040_50400901_145_dialog_content = "(그러니까 타라 씨랑 아도니스 씨가 행복해하는 모습을 보면 마음이 괴롭겠지...)",
  ui_story_5040_50400901_146_dialog_content = "풀 죽을 필요 없어요! 세이블한테 못되게 군 그 녀석은 끝장났을 거예요!",
  ui_story_5040_50400901_147_dialog_content = "선배들이 그랬는데, 그런 녀석들은 다들 끝이 안 좋대요!",
  ui_story_5040_50400901_148_dialog_content = "혹시 그 두 사람이랑 같이 다니는 게 신경 쓰인다면,\n여길 떠나서 우리 둘만 따로 행동하는 건 어때요?",
  ui_story_5040_50400901_149_dialog_content = "아, 아니야...",
  ui_story_5040_50400901_150_dialog_content = "두 사람, 보고 있으면, 마음, 따뜻해져.",
  ui_story_5040_50400901_151_dialog_content = "가족, 친구, 그리고, 사랑...",
  ui_story_5040_50400901_152_dialog_content = "내가 계속 바라 왔던, 따뜻함...",
  ui_story_5040_50400901_153_dialog_content = "이 따뜻함, 소중해. 그래서, 두 사람, 축복해 줄 거야.",
  ui_story_5040_50400901_154_dialog_content = "음... 알겠어요...",
  ui_story_5040_50400901_155_dialog_content = "<color=#e8d9bb>꼬르르륵──</color>",
  ui_story_5040_50400901_156_dialog_content = "배고파...",
  ui_story_5040_50400901_157_dialog_content = "저도요. 우리 저녁 먹으러 가요!",
  ui_story_5040_50400901_158_dialog_content = "(벌써 시간이 이렇게 됐네. 타라 씨랑 아도니스 씨, 저녁 준비는 잘 됐으려나?)",
  ui_story_5040_50400901_159_dialog_content = "으엣취──!",
  ui_story_5040_50400901_160_dialog_content = "(이, 이 코를 찌르는 이 자극적인 매운 냄새... 레디젤 렌치 바비큐다!)",
  ui_story_5040_50400901_161_dialog_content = "어? 키아, 세이블? 구경하고 오겠다던 거 아니었어?",
  ui_story_5040_50400901_162_dialog_content = "벌써 다 둘러봤어요. 그러다 마침 배가 고팠거든요.\n저녁 식사 준비는 잘 돼 가고 있나 보러 왔어요!",
  ui_story_5040_50400901_163_dialog_content = "맞아...",
  ui_story_5040_50400901_164_dialog_content = "(하지만 그렇게 많은 우편물들이 다 제대로 분리돼 있을 줄은 생각도 못 했어.)",
  ui_story_5040_50400901_165_dialog_content = "(심지어는 우편물의 차이에 따라 같은 수신인일 수 있는 우편물은\n따로 모아져 있기까지 했잖아!)",
  ui_story_5040_50400901_166_dialog_content = "(그 덕분에 세이블의 편지를 빠르게 찾을 수 있었어.)",
  ui_story_5040_50400901_167_dialog_content = "(전부 예리아 장로님이 힘써준 결과겠지.)",
  ui_story_5040_50400901_168_dialog_content = "어머? 꽤 시끌벅적하네.",
  ui_story_5040_50400901_169_dialog_content = "이 냄새... 후훗, 레디젤 렌치 사람들은 이런 매운 바비큐밖에 못 만드는 걸까?",
  ui_story_5040_50400901_170_dialog_content = "다들 기왕 레디젤 사막에 왔는데, 현지 맛을 봐야 하지 않겠어?",
  ui_story_5040_50400901_171_dialog_content = "예리아 씨, 볼일은 다 끝내셨나요?",
  ui_story_5040_50400901_172_dialog_content = "응, 차량과 장비 준비도 마쳤고, 샌드버그의 활동 범위도 파악해 뒀어.",
  ui_story_5040_50400901_173_dialog_content = "녀석은 부상을 당한 상태고, 지금 사막 깊은 곳을 향해 이동 중이야.",
  ui_story_5040_50400901_174_dialog_content = "(사메야마가 했던 말이랑 똑같으니까 별문젠 없겠지.)",
  ui_story_5040_50400901_175_dialog_content = "(예리아 씨가 또 기분 나빠할 수도 있으니까,\n다른 사람들한테 연락했었단 얘긴 안 하는 게 좋겠어...)",
  ui_story_5040_50400901_176_dialog_content = "타이밍 좋네! 도마뱀 꼬치구이가 거의 다 됐거든, 얼른 먹어 봐!",
  ui_story_5040_50400901_177_dialog_content = "이거 정말 꼬치구이 맞나요? 고추로 너무 많이 싸매놔서 고기가 하나도 안 보여요.",
  ui_story_5040_50400901_178_dialog_content = "이게 바로 가장 용감한 사람만이 맛볼 수 있는 최고급 레디젤 바비큐,\n「핵매운 말린 도마뱀 꼬치구이」야.",
  ui_story_5040_50400901_179_dialog_content = "으윽, 정말 먹어야 돼?",
  ui_story_5040_50400901_180_dialog_content = "핫소스 범벅이라 냄새만 맡아도 코가 다 아파...",
  ui_story_5040_50400901_181_dialog_content = "그래서 먹을 거야, 말 거야?",
  ui_story_5040_50400901_182_dialog_content = "머, 먹을게! 당연히 먹어야지!",
  ui_story_5040_50400901_183_dialog_content = "아도니스 씨, 무리하지 마.",
  ui_story_5040_50400901_184_dialog_content = "냠냠냠...",
  ui_story_5040_50400901_185_dialog_content = "......",
  ui_story_5040_50400901_186_dialog_content = "하, 하나를 통째로 다 먹었어?",
  ui_story_5040_50400901_187_dialog_content = "......!",
  ui_story_5040_50400901_188_dialog_content = "<color=#e8d9bb>콰당!</color>",
  ui_story_5040_50400901_189_dialog_content = "아도니스 씨?!",
  ui_story_5040_50400901_190_dialog_content = "후후훗, 대단하네. 얼굴이 다 새파래졌어.",
  ui_story_5040_50400901_191_dialog_content = "매워...",
  ui_story_5040_50400901_192_dialog_content = "<size=45>매워어어어!</size>",
  ui_story_5040_50400901_193_dialog_content = "으앗! 아도니스 씨가 기절하려는 것 같아요!",
  ui_story_5040_50400901_194_dialog_content = "빨리 아도니스 씨한테 우유 가져다줘! 우유 마시면 좀 괜찮아진다고 들었거든!",
  ui_story_5040_50400901_195_dialog_content = "제가 가서 찾아볼게요!",
  ui_story_5040_50400901_196_dialog_content = "......",
  ui_story_5040_50400901_197_dialog_content = "(타라는 왜 가는 거지? 따라가 봐야겠네.)",
  ui_story_5040_50400901_198_dialog_content = "우유 찾았어요!",
  ui_story_5040_50400901_199_dialog_content = "아도니스 씨, 얼른 이거 마셔!",
  ui_story_5040_50400901_200_dialog_content = "꿀꺽... 꿀꺽...",
  ui_story_5040_50400901_201_dialog_content = "헉... 헉... 저 아직 살아있는 건가요...?",
  ui_story_5040_50400901_202_dialog_content = "아까 말린 도마뱀 꼬치구이를 하나 통째로 먹더니,\n먹자마자 바닥에 쓰러져 기절해 버렸었어.",
  ui_story_5040_50400901_203_dialog_content = "그랬습니까?",
  ui_story_5040_50400901_204_dialog_content = "으윽, 속이 꼭 불타는 숯을 삼킨 것처럼 너무 아프네요...",
  ui_story_5040_50400901_205_dialog_content = "<size=45><anim type=Shake>우욱──!</anim></size>",
  ui_story_5040_50400901_206_dialog_content = "아도니스 씨!",
  ui_story_5040_50400901_207_dialog_content = "<color=#e8d9bb>한편, 같은 시간</color>",
  ui_story_5040_50400901_208_dialog_content = "남자친구가 토하느라 정신이 없던데, 가서 안 도와줘도 괜찮겠어?",
  ui_story_5040_50400901_209_dialog_content = "아니면 다른 생각이라도 있는 거야?",
  ui_story_5040_50400901_210_dialog_content = "상태가 괜찮아지면 아도니스를 북방으로 돌려보낼 거야.",
  ui_story_5040_50400901_211_dialog_content = "이젠 지쳤어. 더는 이렇게 억지 부리고 싶지 않아.",
  ui_story_5040_50400901_212_dialog_content = "애초부터 우린 같은 길을 걸을 사람이 아니었던 거야. 우린 서로 안 어울려.",
  ui_story_5040_50400901_213_dialog_content = "호오?",
  ui_story_5040_50400901_214_dialog_content = "난 우리가 함께하면 그 어떤 어려움도 극복할 수 있을 줄 알았어.",
  ui_story_5040_50400901_215_dialog_content = "그래서 항상 아도니스한테 레디젤 사막의 생활 방식을 경험하게 해 주고 싶었어.\n아까 그 꼬치구이 같은 거 말이야...",
  ui_story_5040_50400901_216_dialog_content = "근데 미처 몰랐어. 내가 좋아하는 것들이 아도니스를 다치게 만들 수도 있단 걸.",
  ui_story_5040_50400901_217_dialog_content = "그리고 아도니스는 언제나 억지로 나한테 맞춰 주려고 노력하고, 계속 상처를 입었어.",
  ui_story_5040_50400901_218_dialog_content = "이런 건 사랑이 아니라고 생각해.",
  ui_story_5040_50400901_X218_dialog_content = "음... 역시 한창 열애 중인 아기새들은 사소한 일 하나로도 별의별 결론을 내리곤 한다니까.",
  ui_story_5040_50400901_X219_dialog_content = "왜 그런 생각을 하게 된 거야?",
  ui_story_5040_50400901_219_dialog_content = "나랑 아도니스는 생활 습관부터 성격까지 하늘과 땅처럼 달라.\n어쩌면 아도니스의 아버지가 했던 말이 맞을지도 몰라.",
  ui_story_5040_50400901_220_dialog_content = "북방의 아기새는 가벼운 깃털도 없고, 땅을 파서 물을 찾는 방법도 몰라.\n레디젤 사막에서 살아가기 힘든 건 당연한 거야.",
  ui_story_5040_50400901_221_dialog_content = "......",
  ui_story_5040_50400901_222_dialog_content = "이건 용기로 극복할 수 있는 어려움이 아니라, 생리적인 차이로 결정된 일일 뿐이야.",
  ui_story_5040_50400901_223_dialog_content = "사막의 새들에겐 일상이겠지만, 북방의 새에겐 위험이 되는 거지.",
  ui_story_5040_50400901_224_dialog_content = "하지만...",
  ui_story_5040_50400901_225_dialog_content = "하지만 뭐?",
  ui_story_5040_50400901_226_dialog_content = "매운 걸 못 먹는 그 아기새가 매워서 기절까지 해 가면서 그 꼬치구이를 먹었어.",
  ui_story_5040_50400901_227_dialog_content = "그건 자기가 용감하게 그 맵디매운 꼬치구이를 한 입 베어 무는 순간을\n네게 보여 주고 싶어서였을 거잖아?",
  ui_story_5040_50400901_228_dialog_content = "서로의 생활 습관이 다르더라도, 차이를 받아들이고 천천히 맞춰 가면 되는 거 아닐까?",
  ui_story_5040_50400901_229_dialog_content = "그리고 레디젤 사막의 생활 습관이라는 게 딱 그거 하나만으로 정해진 것도 아니잖아.",
  ui_story_5040_50400901_230_dialog_content = "......!",
  ui_story_5040_50400901_231_dialog_content = "아무튼 내가 하려던 말은 이게 다야.",
  ui_story_5040_50400901_232_dialog_content = "헤어질지, 안 헤어질지는 너희 둘이 결정할 일이지만,\n이왕 여기까지 왔으니 바람 쐬러 왔다고 생각해.",
  ui_story_5040_50400901_233_dialog_content = "다른 사람들 기분 처지게 만들지 말고 재미있게 놀아.",
  ui_story_5040_50400901_234_dialog_content = "......",
  ui_story_5040_50400901_235_dialog_content = "그래.",
  ui_story_5040_50400901_236_dialog_content = "먼저 돌아갈게.",
  ui_story_5040_50400901_237_dialog_content = "이런, 정말이지 재미있는 아기새라니까.",
  ui_story_5040_50400901_238_dialog_content = "두 사람의 이야기는 앞으로 어떻게 되려나? 꽤 궁금한걸.",
  ui_story_5040_50400901_239_dialog_content = "...후훗, 나도 참, 왜 이러는 걸까.",
  ui_story_5040_50400901_240_dialog_content = "이런 일에 신경 쓰게 될 줄은 몰랐네.",
  ui_story_5040_50401001_1_dialog_content = "어머, 다들 나왔구나?",
  ui_story_5040_50401001_2_dialog_content = "샌드버그를 잡으러 가기로 한 날이니까, 특별히 일찍 일어났어요.",
  ui_story_5040_50401001_3_dialog_content = "어제 그 꼬치구이는 아무도 안 먹으려고 해서,\n결국엔 스카이워커호에서 먹을 걸 다시 만들긴 했지만요...",
  ui_story_5040_50401001_4_dialog_content = "다들 정말 맛있는 거 먹을 줄 모르는구나?\n근데 그 걱정은 안 해도 돼. 꼬치구이는 내가 다 먹어 버렸거든.",
  ui_story_5040_50401001_5_dialog_content = "음식은 낭비하면 안 되니까!",
  ui_story_5040_50401001_6_dialog_content = "나도 동의해. 음식은 낭비하면 안 되지.",
  ui_story_5040_50401001_7_dialog_content = "그나저나 다들 어젯밤엔 잘 잤어? 물갈이 같은 건 안 했고?",
  ui_story_5040_50401001_8_dialog_content = "나는 아주 푹 잤거든.",
  ui_story_5040_50401001_9_dialog_content = "사막이라서 밤에 조금 춥긴 했지만, 다행히 예리아 장로님이 두꺼운 이불을\n준비해 주셔서 저랑 세이블도 푹 잘 수 있었어요.",
  ui_story_5040_50401001_10_dialog_content = "고...마워... 예리아 씨...",
  ui_story_5040_50401001_11_dialog_content = "후훗, 천만에, 검은 아기새.",
  ui_story_5040_50401001_12_dialog_content = "저는... 으윽...",
  ui_story_5040_50401001_13_dialog_content = "밤새 위통이...",
  ui_story_5040_50401001_14_dialog_content = "(어젯밤에 화장실 쪽으로 달려가는 발소리를 몇 번이나 들었는데,\n설마 그거 다 아도니스 씨가 왔다 갔다 한 거였나?)",
  ui_story_5040_50401001_15_dialog_content = "조금 쉬는 게 좋지 않을까?",
  ui_story_5040_50401001_16_dialog_content = "괘, 괜찮아요!",
  ui_story_5040_50401001_17_dialog_content = "아무렇지도 않습니다. 모두와 같이 움직일 수 있어요!",
  ui_story_5040_50401001_18_dialog_content = "......",
  ui_story_5040_50401001_19_dialog_content = "(어제 저녁 먹고 나서부터 타라 씨 표정이 계속 뭔가 좀 이상해.\n혹시 또 무슨 고민이라도 있는 건가?)",
  ui_story_5040_50401001_20_dialog_content = "그럼 다들 차에 타.\n타라는 조수석에 앉고 나머지 사람들은 알아서 앉아 줘.",
  ui_story_5040_50401001_21_dialog_content = "<color=#e8d9bb>얼마 후</color>",
  ui_story_5040_50401001_22_dialog_content = "이제 사막 내지의 샌드버그 출몰 구역에 거의 다 왔어.",
  ui_story_5040_50401001_23_dialog_content = "여기서 잠깐 쉬면서 마지막 정비도 하고 가자.",
  ui_story_5040_50401001_24_dialog_content = "텐트, 조리 도구, 식재료는 저랑 세이블이 차에서 다 내려 뒀어요.",
  ui_story_5040_50401001_25_dialog_content = "언제든 식사 준비를 시작할 수 있어요!",
  ui_story_5040_50401001_26_dialog_content = "고생 많았어.",
  ui_story_5040_50401001_27_dialog_content = "짐도 다 내렸으니까, 다들 차로 돌아가 줘.",
  ui_story_5040_50401001_28_dialog_content = "네? 차로요? 쉬었다 가자고 하셨잖아요?",
  ui_story_5040_50401001_29_dialog_content = "쉬기 전에 해야 할 일이 하나 있거든.",
  ui_story_5040_50401001_30_dialog_content = "이 앞에 있는 모래 언덕은 굴곡이 여기보다 더 대단해.\n바람 쐬면서 기분 전환하기 정말 좋은 곳이야.",
  ui_story_5040_50401001_31_dialog_content = "굴곡이 대단한 거랑 기분 전환하는 거랑 무슨 관계가 있는 건가요?",
  ui_story_5040_50401001_32_dialog_content = "금방 알게 될 거야, 북방의 아기새.",
  ui_story_5040_50401001_X32_dialog_content = "자, 그럼 어서들 차에 타도록 해.",
  ui_story_5040_50401001_X33_dialog_content = "하지만...",
  ui_story_5040_50401001_X34_dialog_content = "에이, 뭐 어때! 이러쿵저러쿵하지 말고 빨리 차에 타자!",
  ui_story_5040_50401001_X35_dialog_content = "아이테르 군도 같이 가야지.",
  ui_story_5040_50401001_X36_dialog_content = "<color=#e8d9bb>차 안</color>",
  ui_story_5040_50401001_X37_dialog_content = "다들 잘 앉았지?",
  ui_story_5040_50401001_X38_dialog_content = "예리아 씨, 대, 대체 뭘 하시려는 거죠?",
  ui_story_5040_50401001_X39_dialog_content = "당연히... 타라를 즐겁게 만들어 줄 일을 하려는 거지.",
  ui_story_5040_50401001_X40_dialog_content = "안 좋은 예감이 들어요! 저 내릴래요!",
  ui_story_5040_50401001_X41_dialog_content = "그냥 가서 모두가 먹을 점심 식사 준비나 하게 해 주세요!",
  ui_story_5040_50401001_X42_dialog_content = "그건 안 돼. 아이테르 군이 반드시 있어야 하거든.",
  ui_story_5040_50401001_33_option_content = "제가 반드시 있어야 한다고요?!",
  ui_story_5040_50401001_34_dialog_content = "그래. 넌 우리 모두의 소중한 길잡이잖니.",
  ui_story_5040_50401001_35_option_content = "그런 거 안 할래요!",
  ui_story_5040_50401001_36_dialog_content = "탈 때는 마음대로였겠지만 내릴 땐 아니란다, 아이테르 군.",
  ui_story_5040_50401001_37_dialog_content = "안전벨트 잘 매는 거 잊지 말고.",
  ui_story_5040_50401001_38_dialog_content = "<color=#e8d9bb>부릉부릉──!</color>",
  ui_story_5040_50401001_39_dialog_content = "으아악?!",
  ui_story_5040_50401001_40_dialog_content = "소, 속도가 너무 빠르지 않나요?!",
  ui_story_5040_50401001_41_dialog_content = "아하하! 신나!",
  ui_story_5040_50401001_42_dialog_content = "예리아! 더 빨리 달려 봐! 더 빨리!",
  ui_story_5040_50401001_43_dialog_content = "꺄아악! 이러다 차가 하늘로 날아오르겠어요!",
  ui_story_5040_50401001_44_dialog_content = "이게 바로... 하늘을 나는... 느낌?",
  ui_story_5040_50401001_X44_dialog_content = "그만! 속도 좀 줄이세요! 너, 너무 위험해요!",
  ui_story_5040_50401001_X45_dialog_content = "속이... 또 다 뒤집어질 것 같아요...",
  ui_story_5040_50401001_45_dialog_content = "폭풍처럼 더 빨리, 더 매섭게 달려가야 하늘을 나는 듯한 즐거움을 느낄 수 있다구!",
  ui_story_5040_50401001_46_dialog_content = "크어어──!",
  ui_story_5040_50401001_47_dialog_content = "조심하세요! 차 소리를 듣고 암귀 몇 마리가 몰려왔어요!",
  ui_story_5040_50401001_48_dialog_content = "아이테르 군, 이제 네가 실력 발휘를 할 시간이야~",
  ui_story_5040_50401001_49_dialog_content = "네?!",
  ui_story_5040_50401001_50_dialog_content = "눈이든, 감응 능력이든 좋으니까 암귀가 어느 쪽에서 공격해 올지\n알아내서 나한테 잘 알려줘야 해~",
  ui_story_5040_50401001_51_dialog_content = "이렇게 빨리 달리는 차에서요?! 이거 순 억지잖아요!",
  ui_story_5040_50401001_52_dialog_content = "크오오!",
  ui_story_5040_50401001_53_dialog_content = "으악! 왼쪽 뒤에서 와요!",
  ui_story_5040_50401001_54_dialog_content = "응.",
  ui_story_5040_50401001_55_dialog_content = "<color=#e8d9bb>끼이익──</color>",
  ui_story_5040_50401001_56_dialog_content = "<color=#e8d9bb>쾅──!</color>",
  ui_story_5040_50401001_57_dialog_content = "암귀가 차에 들이받혀서 날아가 버렸잖아?!",
  ui_story_5040_50401001_58_dialog_content = "이제, 더는 못 버티겠어요... 우웁!",
  ui_story_5040_50401001_59_dialog_content = "북방의 아기새, 절대 내 차에다 토하지 마.",
  ui_story_5040_50401001_60_dialog_content = "봐, 타라가 오랜만에 즐거워하고 있잖아.",
  ui_story_5040_50401001_61_dialog_content = "그, 그래요? 그렇다면, 타라를 위해... 참아야...",
  ui_story_5040_50401001_62_dialog_content = "......",
  ui_story_5040_50401001_63_dialog_content = "그어어어!",
  ui_story_5040_50401001_64_dialog_content = "또 와요! 이번엔 앞에서요!",
  ui_story_5040_50401001_65_dialog_content = "녀석한테도 이 속도와 불타는 열정을 맛보여 주자고.",
  ui_story_5040_50401001_66_dialog_content = "전속력 전진!",
  ui_story_5040_50401001_67_dialog_content = "아하하! 역시 신난다니까!",
  ui_story_5040_50401001_68_dialog_content = "안 되겠습니다. 또 속이... 우우욱!",
  ui_story_5040_50401001_69_dialog_content = "어머, 겨우 이 정도로 멀미하는 거야?\n북방의 아기새가 사막 생활에 익숙해지려면 아무래도 시간이 좀 걸리겠는걸.",
  ui_story_5040_50401001_70_dialog_content = "하지만 사막의 새는 사막에 부는 바람을 타고 있을 때만 비로소 자유롭게 날아오를 수 있어.",
  ui_story_5040_50401001_71_dialog_content = "맞아...",
  ui_story_5040_50401001_72_dialog_content = "마음을 정했어.",
  ui_story_5040_50401001_73_dialog_content = "드디어 결심이 선 거야?",
  ui_story_5040_50401001_74_dialog_content = "응. 있잖아, 아도니스. 사실 나...",
  ui_story_5040_50401001_75_dialog_content = "응...?",
  ui_story_5040_50401001_76_dialog_content = "<color=#e8d9bb>우르르르...</color>",
  ui_story_5040_50401001_77_dialog_content = "예리아 장로님, 암귀들이에요!",
  ui_story_5040_50401001_78_dialog_content = "암귀 무리가 이쪽을 향해 몰려오고 있어요!",
  ui_story_5040_50401001_79_dialog_content = "이 새카만 녀석들은 정말이지 분위기라는 걸 모른다니까.",
  ui_story_5040_50401001_80_dialog_content = "아까 예리아 씨가 브레이크를 너무 세게 잡아서 그런 거예요.\n이 암귀들 전부 다 그 소릴 듣고 몰려왔을 거라고요!",
  ui_story_5040_50401001_81_dialog_content = "아기새 여러분, 속마음을 털어놓는 건 조금 이따 해야 할 것 같아.",
  ui_story_5040_50401001_82_dialog_content = "지금은 우선 이 녀석들부터 처치하고, 맛있게 점심 먹자.",
  ui_story_5040_50401001_83_dialog_content = "하아...",
  ui_story_5040_50401001_84_dialog_content = "저, 저도 돕겠습니다!",
  ui_story_5040_50401002_1_dialog_content = "암귀는 엎드려 있는 편이 조금 더 귀엽네.",
  ui_story_5040_50401002_2_dialog_content = "크오오──",
  ui_story_5040_50401002_3_dialog_content = "무서워...",
  ui_story_5040_50401002_4_dialog_content = "괜찮아요, 예리아 씨는... 아, 그러니까, 암귀는 벌써 다 해치웠는걸요!",
  ui_story_5040_50401002_5_dialog_content = "예리아 씨는... 무섭지 않아...",
  ui_story_5040_50401002_6_dialog_content = "예리아 씨, 모두를 지켜, 좋은 사람...",
  ui_story_5040_50401002_7_dialog_content = "근데 암귀들이 날뛴 탓에 우리가 준비해 온 식재료들이 엉망이 돼 버렸잖아.",
  ui_story_5040_50401002_8_dialog_content = "움브라톤 스타일 간식도 좀 만들어 보려고 했었는데,\n재료들이 이 모양이 돼서 건질 수 있는 게 하나도 없어!",
  ui_story_5040_50401002_9_dialog_content = "어머, 그럼 이걸 어쩐담?",
  ui_story_5040_50401002_10_dialog_content = "(방금 예리아 씨가 아도니스 씨한테 눈짓을 보낸 것 같았는데?)",
  ui_story_5040_50401002_11_dialog_content = "저한테 방법이 있어요.",
  ui_story_5040_50401002_12_dialog_content = "어?",
  ui_story_5040_50401002_13_dialog_content = "이 식재료들은 살짝 다듬어 주기만 하면 아직 사용할 수 있어요.",
  ui_story_5040_50401002_14_dialog_content = "간식은 못 만들겠지만, 스튜 정도는 문제없이 만들 수 있죠!",
  ui_story_5040_50401002_15_dialog_content = "이번 식사는 저한테 맡겨 주세요!",
  ui_story_5040_50401002_16_dialog_content = "(아도니스 씨가 갑자기 바쁘게 움직이고 있잖아?!)",
  ui_story_5040_50401002_17_dialog_content = "우선 엉망이 된 부분은 도려내고, 쓸 수 있는 부분만 남깁니다.",
  ui_story_5040_50401002_18_dialog_content = "그리고 이 재료들을 한입 크기로 썬 다음, 끓는 물에 넣어요.",
  ui_story_5040_50401002_19_dialog_content = "그다음엔... 타라, 그거 좀 줄래?",
  ui_story_5040_50401002_20_dialog_content = "자, 받아.",
  ui_story_5040_50401002_21_dialog_content = "고마워. 그리고 이때쯤 소금을 조금 넣으면...",
  ui_story_5040_50401002_22_dialog_content = "냄새 좋네!",
  ui_story_5040_50401002_23_dialog_content = "자, 타라. 이건 네 거야. 네가 싫어하는 당근은 이미 다 빼놨어.",
  ui_story_5040_50401002_24_dialog_content = "고마워...",
  ui_story_5040_50401002_25_dialog_content = "저도 한 그릇 주세요! 세이블 것도요!",
  ui_story_5040_50401002_26_dialog_content = "네, 알겠습니다. 잠시만 기다리세요. 지금 바로 담아 드릴게요.",
  ui_story_5040_50401002_27_dialog_content = "자, 받아. 여기 그릇도 가져왔어.",
  ui_story_5040_50401002_28_dialog_content = "음, 맛이 꽤 나쁘지 않은 점심 식사인걸!",
  ui_story_5040_50401002_29_dialog_content = "사막에서 먹기엔 조금 뜨겁지만, 맛이 훌륭하니까 그런 사소한 거까지 따지진 않을게!",
  ui_story_5040_50401002_30_dialog_content = "마음에 든다면 다행이야!",
  ui_story_5040_50401002_31_dialog_content = "그릇은 내가 씻을게.",
  ui_story_5040_50401002_32_dialog_content = "좋아. 그럼 난 암귀들이 다시 나타나지 못하게 이 근처를 좀 순찰하고 올게.",
  ui_story_5040_50401002_33_dialog_content = "잠깐만, 너 아까 나한테 뭐라고 말하려고 하지 않았어?",
  ui_story_5040_50401002_34_dialog_content = "암귀 때문에 정신이 없어서 깜빡할 뻔했잖아.",
  ui_story_5040_50401002_35_dialog_content = "...아니, 아무것도 아니야. 그럼 갔다 올게.",
  ui_story_5040_50401002_36_dialog_content = "저랑 세이블도 이 근처를 잠깐 둘러보고 올게요. 경치 구경도 좀 하고요!",
  ui_story_5040_50401002_37_dialog_content = "(이상해. 타라가 나한테 뭔가 숨기고 있어.)",
  ui_story_5040_50401002_38_dialog_content = "(그러고 보니, 아까 내가 말을 하기도 전에 먼저 소금통을 건네줬었어.)",
  ui_story_5040_50401002_39_dialog_content = "(기억이 돌아오기 시작한 걸까?)",
  ui_story_5040_50401002_40_dialog_content = "(그렇게 생각하면 여기까지 오면서 이상했던 점이 한두 개가 아니야.)",
  ui_story_5040_50401002_41_dialog_content = "(아까 우물쭈물하는 표정도 꼭 전에 뭐 잘못한 게 있어서\n사과할 때마다 짓는 표정을 하고 있었고.)",
  ui_story_5040_50401002_42_dialog_content = "(아무래도 이상해. 설마... 애초부터 기억을 잃지 않았던 걸까?)",
  ui_story_5040_50401002_43_dialog_content = "(하지만 타라한테 그렇게 해야 할 이유는 없잖아? 생각 좀 해 보자...)",
  ui_story_5040_50401002_44_dialog_content = "(설마 기억을 잃은 척해서 날 북방 밖으로 나오게 만들려던 걸까?\n그럼 이 모든 게 나한테 용기를 북돋아 주기 위해 꾸민 일인 건가?)",
  ui_story_5040_50401002_45_dialog_content = "(...타라! 널 향한 내 사랑과 각오를 증명해 보일게! 반드시!)",
  ui_story_5040_50401002_46_dialog_content = "아도니스 씨, 왜 거기 멍하니 서 있어?",
  ui_story_5040_50401002_47_dialog_content = "아니, 아무것도 아닙니다! 무슨 일 있나요, PlayerName 씨?",
  ui_story_5040_50401002_48_dialog_content = "혹시 내가 도와줄 거 없어?",
  ui_story_5040_50401002_49_dialog_content = "없습니다. 저 혼자서도 다 정리할 수 있어요!",
  ui_story_5040_50401002_50_dialog_content = "가서 볼일 보세요.",
  ui_story_5040_50401002_51_dialog_content = "알겠어.",
  ui_story_5040_50401002_52_dialog_content = "(혼자 가만히 있으려니까 진짜 심심하네.\n바이스랑 카렌이 있었다면 같이 얘기도 하고 좋았을 텐데.)",
  ui_story_5040_50401002_53_dialog_content = "(참, 예리아 씨도 혼자 있겠네. 심심하진 않으려나?)",
  ui_story_5040_50401002_54_dialog_content = "(이제 화도 다 풀렸겠지? 가서 한 번 물어보자.)",
  ui_story_5040_50401002_55_dialog_content = "후, 조금 피곤해졌네. 그렇지만...",
  ui_story_5040_50401002_56_dialog_content = "타라, 아도니스. 후훗, 저 두 아기새는 정말 재미있단 말이지.",
  ui_story_5040_50401002_57_dialog_content = "예리아 씨!",
  ui_story_5040_50401002_58_dialog_content = "어머? 아이테르 군, 무슨 일이야?",
  ui_story_5040_50401002_59_dialog_content = "설마 동료들이 곁에 없어서 쓸쓸해진 거니?",
  ui_story_5040_50401002_60_dialog_content = "아, 아니거든요!",
  ui_story_5040_50401002_61_dialog_content = "그렇다면 내가 혼자 있는 모습이 안쓰러워 보여서 와 준 거려나?",
  ui_story_5040_50401002_62_dialog_content = "그것도 아니에요...",
  ui_story_5040_50401002_63_dialog_content = "사실 예리아 씨한테 물어볼 게 있어요.",
  ui_story_5040_50401002_64_dialog_content = "응?",
  ui_story_5040_50401002_65_option_content = "우리한테 거짓말하고 계시죠?",
  ui_story_5040_50401002_66_dialog_content = "그게 무슨 말이니?",
  ui_story_5040_50401002_67_dialog_content = "아침에 그러셨잖아요. 어젯밤에 푹 잘 잤다고.",
  ui_story_5040_50401002_68_dialog_content = "근데 제가 들은 얘기는 전혀 그렇지 않았거든요!",
  ui_story_5040_50401002_69_option_content = "억지로 무리하고 있는 거 아니에요?",
  ui_story_5040_50401002_70_dialog_content = "내가? 후훗, 아이테르 군, 어째서 그런 결론을 내린 거야?",
  ui_story_5040_50401002_71_dialog_content = "누가 말해줬어요. 예리아 씨가 어제 하루 종일 샌드버그를 찾으려고\n언령을 조종해서 사막 전체를 샅샅이 뒤졌다고요.",
  ui_story_5040_50401002_72_dialog_content = "......",
  ui_story_5040_50401002_73_dialog_content = "그렇다고 쳐. 근데 그게 뭐?",
  ui_story_5040_50401002_74_dialog_content = "그런 방식은 너무 마구잡이잖아요!",
  ui_story_5040_50401002_75_dialog_content = "강력한 루미나틱스를 그렇게 오랜 시간 써버린 데다가,\n오늘은 아침 일찍 일어나느라 제대로 쉬지도 못했고, 아깐 암귀들이랑 전투까지 치렀어요.",
  ui_story_5040_50401002_76_dialog_content = "몸을 혹사시키고 있는 거라고요!",
  ui_story_5040_50401002_77_dialog_content = "그래서 그게 뭐 어쨌는데?",
  ui_story_5040_50401002_78_dialog_content = "그러니까 제 말은 혼자서 그렇게 무리하지 말고...\n가끔은 다른 사람한테 의지해도 된다는 거예요.",
  ui_story_5040_50401002_79_dialog_content = "난 다른 사람 도움 없이도, 이 사막에서 혼자 잘 살 수 있어.",
  ui_story_5040_50401002_80_dialog_content = "그리고 나 혼자서도 샌드버그의 흔적을 찾을 수 있고,\n이 사막에 살고 있는 모두를 위해 쿠리어 길드의 우편 배송 업무도 완수할 수 있어.",
  ui_story_5040_50401002_81_dialog_content = "그럼 넌 무슨 자격으로 날 의심하는 거니?",
  ui_story_5040_50401002_82_dialog_content = "그 얘기가 아니잖아요!",
  ui_story_5040_50401002_83_dialog_content = "저도 제가 아이테르라서 루미나틱스를 사용할 수 없고,\n암귀와 맞서 싸울 힘 따윈 없다는 건 잘 알아요.",
  ui_story_5040_50401002_84_dialog_content = "그래서 지금까지 동료들의 힘에 많이 의지해 왔던 것도 사실이에요.",
  ui_story_5040_50401002_85_dialog_content = "하지만 전 약하기 때문에 깨달을 수 있었어요. 이 세상은 혼자서 살아갈 수 없단 걸요.",
  ui_story_5040_50401002_86_dialog_content = "음?",
  ui_story_5040_50401002_87_dialog_content = "혼자서 아무리 강하다고 해도, 언젠간 자기 능력 밖의 문제를 마주하게 돼요.",
  ui_story_5040_50401002_88_dialog_content = "물론 그중엔 자기 능력을 길러서 해결할 수 있는 일도 있을 테고,\n열심히 노력했더니 어떻게든 해결되는 경우도 있기야 하겠죠...",
  ui_story_5040_50401002_89_dialog_content = "하지만 살다 보면 능력을 기를 시간이 주어지지 않거나,\n노력의 한계를 뛰어넘는 문제라는 게 꼭 생겨요.",
  ui_story_5040_50401002_90_dialog_content = "보잘것없는 아이테르인 전 그런 문제를 많이 겪어 봤어요.",
  ui_story_5040_50401002_91_dialog_content = "그러니까 다른 사람한테 기대는 건 부끄러운 일이 아니라는 얘길 해 주고 싶은 거니?",
  ui_story_5040_50401002_92_dialog_content = "후훗, 아이테르 군은 참 순진하구나.",
  ui_story_5040_50401002_93_dialog_content = "다른 사람한테 기댄다? 한두 번은 괜찮을지도 몰라.\n하지만 자꾸 다른 사람의 정에 기대다 보면, 그게 다 빚이 되는 거야.",
  ui_story_5040_50401002_94_dialog_content = "그 빚들은 새가 자유롭게 날아오르지 못하게 속박하는 족쇄가 돼 버린단다.",
  ui_story_5040_50401002_95_dialog_content = "다른 사람한테 빚을 잔뜩 지고 있는 너라면, 이런 생각도 이해할 수 있겠지?",
  ui_story_5040_50401002_96_option_content = "네.",
  ui_story_5040_50401002_97_dialog_content = "다른 사람한테 마음의 빚을 질 때마다, 미안하다는 느낌이 들긴 해요.",
  ui_story_5040_50401002_98_dialog_content = "그렇지. 난 그 느낌이 싫거든. 그래서 다른 사람들과 교류 같은 건 별로 하고 싶지 않아.",
  ui_story_5040_50401002_99_dialog_content = "혼자서 자유롭게 사는 게 나쁜 건 아니잖아?",
  ui_story_5040_50401002_100_dialog_content = "자유롭게 생활하는 것도 물론 좋죠.\n고민 같은 거 안 하고, 자기가 하고 싶은 걸 할 수 있으니까요.",
  ui_story_5040_50401002_101_dialog_content = "하지만 사람과 사람 사이의 교류는 매몰차게 빚이라고 단언할 수 있는 게 아니에요.",
  ui_story_5040_50401002_102_option_content = "이해할 수 없어요.",
  ui_story_5040_50401002_103_dialog_content = "지금까지 많은 사람한테 도움을 받았지만, 전 그거 때문에 부담을 느낀 적은 없었어요.",
  ui_story_5040_50401002_104_dialog_content = "......!",
  ui_story_5040_50401002_105_dialog_content = "사람은 저마다 자신 있어 하는 분야가 다 다르고, 취약한 분야도 다 달라요.\n그래서 우린 서로의 부족한 점을 채워줄 수 있는 거고요.",
  ui_story_5040_50401002_106_dialog_content = "제 동료들은 루미나틱스를 잘 다뤄요. 그리고 전 빛의 궤적을 볼 수 있으니까\n서로가 서로의 힘이 돼 함께 암귀에 맞서 싸울 수 있어요.",
  ui_story_5040_50401002_107_dialog_content = "전 예리아 씨가 어떤 일을 겪었길래 다른 사람들과의 교류를 거부하는 건지는 몰라요.",
  ui_story_5040_50401002_108_dialog_content = "하지만 인간관계라는 건 일방통행이 아니잖아요.\n전 다른 사람한테 도움을 받기도 하고, 최선을 다해 다른 사람을 돕기도 해요.",
  ui_story_5040_50401002_109_dialog_content = "......",
  ui_story_5040_50401002_110_dialog_content = "후훗, 넌 그렇게 생각하는구나.",
  ui_story_5040_50401002_111_dialog_content = "가만 보니 아이테르 군과 네 동료들도 저 아기새들과 똑같은 모양이네.",
  ui_story_5040_50401002_112_dialog_content = "네?!",
  ui_story_5040_50401002_113_dialog_content = "저, 저흰 그냥 평범한 친구예요! 절대 그런 사이...",
  ui_story_5040_50401002_114_dialog_content = "어머? 난 아직 아무 얘기도 안 했는데, 그 조그마한 머리로 무슨 생각하는 거니?",
  ui_story_5040_50401002_115_dialog_content = "으으, 진짜...",
  ui_story_5040_50401002_116_dialog_content = "봐. 저 두 사람, 서로가 서로의 부족한 점을 채워 주잖아?",
  ui_story_5040_50401002_117_dialog_content = "나 왔어. 아직까지 이 주변에 암귀의 흔적은 없었어.",
  ui_story_5040_50401002_118_dialog_content = "고생했어! 자, 물 한 잔 마시고 조금 쉬어.",
  ui_story_5040_50401002_119_dialog_content = "확실히 그렇죠...",
  ui_story_5040_50401002_120_dialog_content = "타라 씨는 외향적이고 밝은 성격에, 야외에 생존 경험이랑 암귀 대처 경험도 풍부해요.",
  ui_story_5040_50401002_121_dialog_content = "아도니스 씨는 책임감 있고 보이지 않게 뒤에서 잘 챙겨 주는 스타일이죠.\n게다가 타라 씨가 잘 처리하지 못하는 세세한 일을 처리할 수 있을 만큼 끈기도 있어요.",
  ui_story_5040_50401002_122_dialog_content = "맞아. 레디젤 렌치 사람과 마음이 맞는 사람이 있을 줄은 정말 꿈에도 몰랐다니까.",
  ui_story_5040_50401002_123_dialog_content = "예리아 씨는 레디젤 렌치를 싫어하시는 건가요?",
  ui_story_5040_50401002_124_dialog_content = "싫어하냐고? 후후, 그럴지도 모르겠네.",
  ui_story_5040_50401002_125_dialog_content = "내가 보기엔 무모하고 생각 없이 사는 도둑들에 불과하거든.",
  ui_story_5040_50401002_126_dialog_content = "즐거움을 찾는 것 말곤 아무것도 신경 쓰지 않고 말이야.",
  ui_story_5040_50401002_127_dialog_content = "그치만 예리아 씨가 샌드버그 때문에 언령으로 사막 전체를\n뒤지고 있다는 사실을 알려 준 건 사메야마였어요.",
  ui_story_5040_50401002_128_dialog_content = "뭐?",
  ui_story_5040_50401002_129_dialog_content = "어제 예리아 씨한테 쫓겨난 다음에 전 분홍색 샌드버그에 대해\n물어보려고 사메야마한테 연락했어요.",
  ui_story_5040_50401002_130_dialog_content = "그랬더니 예리아 씨가 언령으로 샌드버그를 찾고 있는 걸\n레디젤 렌치 멤버들이 봤다고 하더라고요.",
  ui_story_5040_50401002_131_dialog_content = "다들 예리아 씨 걱정도 많이 하고, 신경도 많이 쓰고 있어요.",
  ui_story_5040_50401002_132_dialog_content = "그건 내가 자기들한테 필요한 정보를 가져다주는\n이 사막의 몇 안 되는 쿠리어니까 그러는 거겠지.",
  ui_story_5040_50401002_133_dialog_content = "그렇지 않아요!",
  ui_story_5040_50401002_134_dialog_content = "자, 이제 충분히 쉰 것 같네.",
  ui_story_5040_50401002_135_dialog_content = "잠깐만요! 예리아 씨!",
  ui_story_5040_50401002_136_dialog_content = "어서 짐 챙겨. 출발할 거야.",
  ui_story_5040_50401002_137_dialog_content = "(예리아 씨도 좀 너무하잖아. 사람을 이렇게 놔두고 그냥 가 버리다니...)",
  ui_story_5040_50401002_138_dialog_content = "(근데 예리아 씨는 항상 저렇게 무리하거나 피해버리는\n식으로 아무렇지 않은 척해 왔던 걸까...)",
  ui_story_5040_50401101_1_dialog_content = "아기새 여러분, 정리는 어떻게 돼 가?",
  ui_story_5040_50401101_2_dialog_content = "정리는 이미 다 끝냈습니다. 언제든 출발할 수 있어요.",
  ui_story_5040_50401101_3_dialog_content = "나도 준비 다 됐어.",
  ui_story_5040_50401101_4_dialog_content = "빼놓은 건 없는지 짐도 다 확인했고, 모닥불도 확실히 꺼 뒀어요.",
  ui_story_5040_50401101_5_dialog_content = "역시 키아는 꼼꼼하네!",
  ui_story_5040_50401101_6_dialog_content = "고마워요. 다 에메랄드 선생님한테 배운 거예요.",
  ui_story_5040_50401101_7_dialog_content = "에메랄드 선생님? 그게 누구야?",
  ui_story_5040_50401101_8_dialog_content = "쿠리어 길드의 선배님이에요. 지금은 퇴직하셨지만요.",
  ui_story_5040_50401101_9_dialog_content = "제가 쿠리어가 되기 전까지 제 고향인 파르 마을이랑 근처에 있는\n다른 마을의 우편물은 다 에메랄드 선생님이 가져다주셨어요.",
  ui_story_5040_50401101_10_dialog_content = "그 마을은 너무 외딴곳에 있어서 마을 밖 세상이랑 왕래가 거의 없었거든요.",
  ui_story_5040_50401101_11_dialog_content = "에메랄드 선생님이 배달해 주신 편지들만이 바깥세상과 소통할 수 있는 유일한 방법이었죠.",
  ui_story_5040_50401101_12_dialog_content = "그럼 분명히 책임감이 아주 강한 사람이었겠네.",
  ui_story_5040_50401101_13_dialog_content = "그럼요! 전 에메랄드 선생님의 영향을 받아서 쿠리어가 되기로 결심한 거거든요!",
  ui_story_5040_50401101_14_dialog_content = "전 외딴곳에서 사는 사람들은 바깥세상과 연락하기 어렵다는 걸 잘 아니까요.\n그래서 사람들한테 바깥세상을 알려줄 수 있는 사람이 되고 싶다고 생각했어요.",
  ui_story_5040_50401101_15_dialog_content = "그거 대단하네!",
  ui_story_5040_50401101_16_dialog_content = "헤헤, 저한텐 아직도 부족한 점이 많은걸요.",
  ui_story_5040_50401101_17_dialog_content = "에메랄드 선생님이 주신 노트가 있긴 하지만, 그래도 자주 일을 망쳐 버리곤 해요...",
  ui_story_5040_50401101_18_dialog_content = "노트에 적혀 있는 대로 차근차근히 해도, 꼭 끝에 가면 뜻밖의 상황이 벌어지거든요.",
  ui_story_5040_50401101_19_dialog_content = "일을 하다 보면 상황에 따라 바뀌는 게 많기 마련이야.\n그러니까 꼭 노트 내용 그대로 할 필요는 없을 것 같아.",
  ui_story_5040_50401101_20_dialog_content = "으, 저는 상황에 따라 변화를 주는 걸 잘 못해서요...",
  ui_story_5040_50401101_21_dialog_content = "크오오──",
  ui_story_5040_50401101_22_dialog_content = "멀리서 무슨 소리 안 들려?",
  ui_story_5040_50401101_23_dialog_content = "저건...",
  ui_story_5040_50401101_24_dialog_content = "크에엑──!",
  ui_story_5040_50401101_25_dialog_content = "암귀들이에요! 다들 조심하세요!",
  ui_story_5040_50401101_26_dialog_content = "엄청 많은데?!",
  ui_story_5040_50401101_27_dialog_content = "쳇, 저 녀석들은 또 어디서 튀어나온 거야?!",
  ui_story_5040_50401101_28_dialog_content = "또 암귀가 나타나다니, 이상해...",
  ui_story_5040_50401101_29_dialog_content = "아무튼 일단 눈앞에 있는 이 녀석들부터 처리해야겠지. 다들 잘해보자.",
  ui_story_5040_50401102_1_dialog_content = "크오오──",
  ui_story_5040_50401102_2_dialog_content = "이 암귀들 진짜 이상한데요? 싸울 생각이 별로 없는 건지 그냥 도망쳐 버리고 있어요.",
  ui_story_5040_50401102_3_dialog_content = "일반적으로 여긴 암귀들이 자주 출몰하는 구역이 아니야.",
  ui_story_5040_50401102_4_dialog_content = "그렇지만 지금까지 연속으로 두 번이나 암귀 무리와 마주쳤어. 이건 확실히 비정상적이야.",
  ui_story_5040_50401102_5_dialog_content = "녀석들, 도망쳐...",
  ui_story_5040_50401102_6_dialog_content = "응? 세이블, 뭐라고? 못 들었어.",
  ui_story_5040_50401102_7_dialog_content = "세이블은 녀석들이 뭔가를 피하려고 도망치고 있는 것 같대요.",
  ui_story_5040_50401102_8_dialog_content = "<color=#e8d9bb>쿠르릉...</color>",
  ui_story_5040_50401102_9_dialog_content = "땅이 흔들리는 건가?",
  ui_story_5040_50401102_10_dialog_content = "다들 얼른 흩어져! 뭔가 이쪽으로 오고 있어!",
  ui_story_5040_50401102_11_dialog_content = "타라! 조심해!",
  ui_story_5040_50401102_12_dialog_content = "<color=#e8d9bb>쿠르르릉──!</color>",
  ui_story_5040_50401102_13_dialog_content = "<size=50>그오오오──!</size>",
  ui_story_5040_50401102_14_dialog_content = "어?! 지, 진짜 분홍색 샌드버그잖아?!",
  ui_story_5040_50401102_15_dialog_content = "사막 깊은 곳을 향해 이동 중이라고 하지 않았어? 여긴 거기랑 멀어도 너무 먼데?!",
  ui_story_5040_50401102_16_dialog_content = "최대한 빨리 먹이를 먹어야만 하는 특별한 이유가 있는 걸지도 몰라.",
  ui_story_5040_50401102_17_dialog_content = "설마 저 녀석이 아까 그 암귀들을 잡아먹으려고 했단 건가요?",
  ui_story_5040_50401102_18_dialog_content = "정답이야. 그런데 이제는 암귀가 아니라 우릴 먹이로 여기고 있어.",
  ui_story_5040_50401102_19_dialog_content = "<size=50>크오오!</size>",
  ui_story_5040_50401102_20_dialog_content = "음? 덩치도 커다란 녀석이 뭘 그렇게 급하니?",
  ui_story_5040_50401102_21_dialog_content = "<color=#e8d9bb>퍼억──!</color>",
  ui_story_5040_50401102_22_dialog_content = "엄청 딱딱한데요?!",
  ui_story_5040_50401102_23_dialog_content = "후후, 저 분홍색 비늘들은 겉모습만큼 무해하진 않은 모양이네.",
  ui_story_5040_50401102_24_dialog_content = "하지만 비늘이 아무리 딱딱해 봤자, 샌드버그일 뿐이야.",
  ui_story_5040_50401102_25_dialog_content = "가라, 언령들이여!",
  ui_story_5040_50401102_26_dialog_content = "그어어──",
  ui_story_5040_50401102_27_dialog_content = "다행이에요! 효과가 있어요!",
  ui_story_5040_50401102_28_dialog_content = "나도 도와줄게!",
  ui_story_5040_50401102_29_dialog_content = "타라! 녀석하고 너무 가까워, 위험해!",
  ui_story_5040_50401102_30_dialog_content = "이 거리론 안 돼. 너무 멀리 떨어져 있으면 총알의 위력이 떨어져.\n그럼 저 샌드버그의 비늘을 못 뚫어.",
  ui_story_5040_50401102_31_dialog_content = "그래봤자 힘이나 쓸 줄 아는 벌레밖에 더 돼? 겁먹을 필요 없어!",
  ui_story_5040_50401102_32_dialog_content = "그오... 그오오...!",
  ui_story_5040_50401102_33_dialog_content = "다음 공격은 머리야!",
  ui_story_5040_50401102_34_dialog_content = "그어어어!",
  ui_story_5040_50401102_35_dialog_content = "어?!",
  ui_story_5040_50401102_36_dialog_content = "샌드버그가 타라 씨의 총을 물어버렸어요! 설마 처음부터 노린 건가?!",
  ui_story_5040_50401102_37_dialog_content = "이거 놔!",
  ui_story_5040_50401102_38_dialog_content = "샌드버그가 저런 잔꾀를 부린다고? 뭔가 이상해...",
  ui_story_5040_50401102_39_dialog_content = "지금 우리 힘으론 녀석을 빠르게 쓰러트릴 수 없어.",
  ui_story_5040_50401102_40_dialog_content = "녀석은 상황을 질질 끌어서 우리의 체력을 빼놓을 작정이에요!",
  ui_story_5040_50401102_41_dialog_content = "그렇게 하게 두진 않을 거야.\n현혹의 마법서, 네 힘을 보여라!",
  ui_story_5040_50401102_42_dialog_content = "캬악──!",
  ui_story_5040_50401102_43_dialog_content = "샌드버그가 없어졌어요!",
  ui_story_5040_50401102_44_dialog_content = "모래 속으로 숨은 거야. 다들 발밑을 조심해!",
  ui_story_5040_50401102_45_dialog_content = "<size=50>그오오오!</size>",
  ui_story_5040_50401102_46_dialog_content = "<color=#e8d9bb>부웅── 퍽!</color>",
  ui_story_5040_50401102_47_dialog_content = "아얏...!",
  ui_story_5040_50401102_48_dialog_content = "타라 씨가 저쪽의 모래 언덕까지 날아갔어요!",
  ui_story_5040_50401102_49_dialog_content = "타라!!!",
  ui_story_5040_50401102_50_dialog_content = "...난 괜찮아!",
  ui_story_5040_50401102_51_dialog_content = "이 근처에 있는 모래는 다 부드러워.\n샌드버그가 얼마든지 안으로 파고들어 우릴 습격해 올 수 있을 거야.",
  ui_story_5040_50401102_52_dialog_content = "다들 얼른 차에 타!",
  ui_story_5040_50401102_53_dialog_content = "자갈이 있는 곳까지 철수할 거야!\n거긴 지면이 암석으로 돼 있어서 샌드버그가 파고들 수 없어!",
  ui_story_5040_50401102_54_dialog_content = "알겠어요! 세이블, 얼른 가죠! 일단 차에 타요!",
  ui_story_5040_50401102_55_dialog_content = "아도니스! 빨리 철수해!",
  ui_story_5040_50401102_56_dialog_content = "알겠어... 타라! 조심해!",
  ui_story_5040_50401102_57_dialog_content = "그어어──",
  ui_story_5040_50401102_58_dialog_content = "으악──!",
  ui_story_5040_50401102_59_dialog_content = "타라!",
  ui_story_5040_50401102_60_dialog_content = "크윽...",
  ui_story_5040_50401102_61_dialog_content = "큰일이에요! 타라 씨가 다릴 다쳤어요!",
  ui_story_5040_50401102_62_dialog_content = "그어어어!",
  ui_story_5040_50401102_63_dialog_content = "(빌어먹을, 거리가 너무 멀어. 녀석을 막으려면 어떻게 해야...)",
  ui_story_5040_50401102_64_dialog_content = "이 못생긴 애벌레 녀석! 타라한테서 멀리 떨어져!",
  ui_story_5040_50401102_65_dialog_content = "그어어──",
  ui_story_5040_50401102_66_dialog_content = "이쪽이다! 애벌레! 여길 보라고!",
  ui_story_5040_50401102_67_dialog_content = "아도니스 씨가 샌드버그의 주의를 끌고 있어요!",
  ui_story_5040_50401102_68_dialog_content = "강력한 공격을 한 것도 아닌데 효과가 있나 봐요!",
  ui_story_5040_50401102_69_dialog_content = "봐, 아도니스가 공격한 곳에 아직 안 나은 상처들이 몇 개 있는 것 같아.",
  ui_story_5040_50401102_70_dialog_content = "분명 사메야마가 전에 녀석과 싸우다가 입힌 상처일 거예요!",
  ui_story_5040_50401102_71_dialog_content = "그어어어!",
  ui_story_5040_50401102_72_dialog_content = "으아아아!",
  ui_story_5040_50401102_73_dialog_content = "샌드버그가 아도니스 씨한테 정신이 팔려서 타라 씨한테서 멀리 떨어지고 있어요!",
  ui_story_5040_50401102_74_dialog_content = "예리아 씨, 지금이에요!",
  ui_story_5040_50401102_75_dialog_content = "후훗, 알겠어.",
  ui_story_5040_50401102_76_dialog_content = "호크! 녀석의 상처를 노려!",
  ui_story_5040_50401102_77_dialog_content = "그억... 그어어어!",
  ui_story_5040_50401102_78_dialog_content = "지금이에요!",
  ui_story_5040_50401102_79_dialog_content = "타라 씨, 괜찮아요?",
  ui_story_5040_50401102_80_dialog_content = "난 괜찮으니까 얼른 가서 아도니스를 도와줘!",
  ui_story_5040_50401102_81_dialog_content = "네!",
  ui_story_5040_50401102_82_dialog_content = "나도, 도울래!",
  ui_story_5040_50401102_83_dialog_content = "<color=#e8d9bb>쉬익!</color>",
  ui_story_5040_50401102_84_dialog_content = "그오오오오!",
  ui_story_5040_50401102_85_dialog_content = "사, 살았다!",
  ui_story_5040_50401102_86_dialog_content = "저희 뒤에 서세요! 넘어지지 않게 조심하시고요!",
  ui_story_5040_50401102_87_dialog_content = "그어어어!",
  ui_story_5040_50401102_88_dialog_content = "<color=#e8d9bb>쿠구구구!</color>",
  ui_story_5040_50401102_89_dialog_content = "으앗?! 왜 갑자기 모래 폭풍이?!",
  ui_story_5040_50401102_90_dialog_content = "이건 모래 폭풍이 아니라 저 샌드버그가 일으킨 모래 먼지야.",
  ui_story_5040_50401102_91_dialog_content = "이걸로 우리 시야를 차단해서 자기 약점을 숨기려는 거겠지.",
  ui_story_5040_50401102_92_dialog_content = "망했다! 키아랑 다른 사람들이 어디 있는지 안 보여요!",
  ui_story_5040_50401102_93_dialog_content = "타라! 어디야?!",
  ui_story_5040_50401102_94_dialog_content = "아도니스, 이쪽이야!",
  ui_story_5040_50401102_95_dialog_content = "저희가 금방 그쪽으로 갈게요!",
  ui_story_5040_50401102_96_dialog_content = "<color=#e8d9bb>콰르르릉!</color>",
  ui_story_5040_50401102_97_dialog_content = "으아아아악!",
  ui_story_5040_50401102_98_dialog_content = "아도니스?!",
  ui_story_5040_50401102_99_dialog_content = "내가 가서 모두를 데려와야겠어!",
  ui_story_5040_50401102_100_dialog_content = "<size=50>캬악──!</size>",
  ui_story_5040_50401102_101_dialog_content = "으윽!",
  ui_story_5040_50401102_102_dialog_content = "예리아 씨, 샌드버그가 도망치려고 해요!",
  ui_story_5040_50401102_103_dialog_content = "어딜!",
  ui_story_5040_50401102_104_dialog_content = "<size=50>그오오오!</size>",
  ui_story_5040_50401102_105_dialog_content = "으앗!",
  ui_story_5040_50401102_106_dialog_content = "PlayerName?!",
  ui_story_5040_50401102_107_dialog_content = "아, 아파...",
  ui_story_5040_50401201_1_dialog_content = "PlayerName, 정신 차려!",
  ui_story_5040_50401201_2_dialog_content = "으아앗, 아파아아아!",
  ui_story_5040_50401201_3_dialog_content = "퉷퉤퉤! 왜 입안에 모래가 이렇게 잔뜩 들어간 거지?!",
  ui_story_5040_50401201_4_dialog_content = "휴, 무사해서 다행이야. 어디 다친 덴 없어?",
  ui_story_5040_50401201_5_dialog_content = "콜록, 콜록... 정수리 쪽이 좀 아픈 거 빼곤 괜찮아. 아마 별일 아닐 거야.",
  ui_story_5040_50401201_6_dialog_content = "아까 샌드버그한테 맞고 모래에 머리부터 다이빙하길래, 크게 다쳤을 줄 알았어.",
  ui_story_5040_50401201_7_dialog_content = "나랑 타라가 모래에 거꾸로 박힌 널 뽑아내느라 정말 힘들었다니까.\n그러니까 우리한테 제대로 감사해야 해, 아이테르 군.",
  ui_story_5040_50401201_8_dialog_content = "고마워요...",
  ui_story_5040_50401201_9_dialog_content = "다른 사람들은요? 다들 괜찮아요?",
  ui_story_5040_50401201_10_dialog_content = "모래 속에 네 다리가 튀어나와 있는 게 보이길래 우선 너부터 구하러 온 거야.",
  ui_story_5040_50401201_11_dialog_content = "아까 그 모래 폭풍이 너무 강해서, 샌드버그는 도망쳐 버렸고,\n아도니스랑 키아, 그리고 세이블하고도 뿔뿔이 흩어져 버렸어.",
  ui_story_5040_50401201_12_dialog_content = "제가 감응 능력으로 모두가 어디 있는지 찾아볼게요!",
  ui_story_5040_50401201_13_option_content = "(감응!)",
  ui_story_5040_50401201_14_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_5040_50401201_15_dialog_content = "이 근처에선 아무런 흔적도 안 느껴져요...",
  ui_story_5040_50401201_16_dialog_content = "괜찮아. 이미 언령들한테 사람들을 찾아보라고 해 뒀거든.\n별일 없다면 금방 소식이 있겠지.",
  ui_story_5040_50401201_17_dialog_content = "모래 속에 파묻혀 있다고 해도, 호크는 조그마한 움직임도 느낄 수 있어.\n그러니까 찾을 수 있을 거야.",
  ui_story_5040_50401201_18_dialog_content = "아도니스, 제발 무사해야 할 텐데...",
  ui_story_5040_50401201_19_dialog_content = "퓌요오오──!",
  ui_story_5040_50401201_20_dialog_content = "호크가 소식을 가져왔네.",
  ui_story_5040_50401201_21_dialog_content = "어땠니? 사람들은?",
  ui_story_5040_50401201_22_dialog_content = "퓌이──",
  ui_story_5040_50401201_23_dialog_content = "...뭐? 근처에 아무도 없었다고?",
  ui_story_5040_50401201_24_dialog_content = "다시 가서 찾아봐. 루미나를 얼마나 쓰든 상관없으니까,\n이번엔 아까보다 더 넓은 범위를 찾아.",
  ui_story_5040_50401201_25_dialog_content = "가 봐!",
  ui_story_5040_50401201_26_dialog_content = "퓌요오오──!",
  ui_story_5040_50401201_27_dialog_content = "우리도 이 근처를 찾아보자.",
  ui_story_5040_50401201_28_dialog_content = "타라 씨는 아직 다리도 다 안 나잖아!",
  ui_story_5040_50401201_29_dialog_content = "그렇다고 여기서 가만히 기다리고 있을 수만은 없어!",
  ui_story_5040_50401201_30_dialog_content = "섣불리 움직였다간 체력만 낭비할 뿐이야.\n매의 눈으로도 못 찾은 걸 우리가 찾아낼 리는 더더욱 없어.",
  ui_story_5040_50401201_31_dialog_content = "상처가 덧나지 않게 그냥 여기서 쉬고 있는 게 좋을 거야.",
  ui_story_5040_50401201_32_dialog_content = "......",
  ui_story_5040_50401201_33_dialog_content = "내가 기억을 잃은 척만 안 했다면, 아도니스가 위험에 빠지는 일은 없었겠지?",
  ui_story_5040_50401201_34_dialog_content = "휴... 솔직히 난 타라 씨가 연기하는 거일지도 모른다고 진작부터 느꼈어.",
  ui_story_5040_50401201_35_dialog_content = "그래도 그땐 뭔가 사정이 있겠거니 해서 모르는 척해줬던 거야.",
  ui_story_5040_50401201_36_dialog_content = "응...",
  ui_story_5040_50401201_37_dialog_content = "지금 생각해 보면, 타라 씨가 그러는 걸 모르는 척해서...\n결국 지금처럼 위험한 상황을 불러오고 말았어!",
  ui_story_5040_50401201_38_dialog_content = "왜 그런 거야? 대체 무슨 생각이었던 건데?!",
  ui_story_5040_50401201_39_dialog_content = "...이렇게 하면 아도니스가 북방 밖의 세상에 가지고 있는\n두려움을 이겨낼 수 있을 줄 알았거든.",
  ui_story_5040_50401201_40_dialog_content = "계속 북방이 아닌 다른 곳에서 어떻게 살아야 하나 고민하고 그러니까,\n난 이런 시험들로 살짝 등을 떠밀어 도움을 주고 싶었어.",
  ui_story_5040_50401201_41_option_content = "방법이 너무 엉망진창이잖아!",
  ui_story_5040_50401201_42_dialog_content = "내가 이런 일에 끌어들여진 건 그러려니 할 수 있어.\n근데 아도니스 씨는 타라 씨가 제일 소중하게 생각하는 사람 아니야?",
  ui_story_5040_50401201_43_dialog_content = "시험이랍시고 자기가 제일 아끼는 사람을 위험에 빠트리면 어떡해!",
  ui_story_5040_50401201_44_dialog_content = "게다가 이젠 키아랑 세이블까지 말려들어서 실종돼 버렸어.\n더는 장난이었다고 웃어 넘길만한 상황이 아냐!",
  ui_story_5040_50401201_45_dialog_content = "미안해...",
  ui_story_5040_50401201_46_option_content = "...무슨 생각이었는지 이해는 해.",
  ui_story_5040_50401201_47_dialog_content = "나도 가끔은 용기가 없을 때 누가 등이라도 떠밀어 줬으면 좋겠다고 생각할 때가 있으니까.",
  ui_story_5040_50401201_48_dialog_content = "의도는 좋았어. 하지만 그 의도를 위해 타라 씨가 사용한 방법까지 좋았다곤 못 하겠어.",
  ui_story_5040_50401201_49_dialog_content = "친구가 무언가에 맞설 용기가 없어 머뭇거리고 있다면,\n등을 떠밀 게 아니라 곁에 있어 줬어야 하는 거야.",
  ui_story_5040_50401201_50_dialog_content = "그리고 말과 행동으로 용기를 북돋아 주고, 둘이 함께 어려움과 맞섰어야 하는 거고.",
  ui_story_5040_50401201_51_dialog_content = "내가 너무 생각 없이 행동했어, 다 내 잘못이야...",
  ui_story_5040_50401201_52_dialog_content = "처음엔 그 샌드버그도 색만 좀 특이하지, 다른 건 다 평범한 일반 샌드버그인 줄 알았어.",
  ui_story_5040_50401201_53_dialog_content = "평범한 샌드버그는 많이 상대해 봤으니까 어려울 것도 없고,\n나 혼자서 아도니스를 지킬 수 있었어.",
  ui_story_5040_50401201_54_dialog_content = "근데 녀석이 저렇게 영악하고 강할 줄은 예상 못 했어...",
  ui_story_5040_50401201_55_dialog_content = "나도 이번 일에 어느 정도는 책임이 있어.",
  ui_story_5040_50401201_56_dialog_content = "그렇게 눈에 띄는 색을 가지고도 험난한 사막에서 생활할 수 있을 정도면,\n그만한 능력은 반드시 가지고 있을 거란 점을 예상했어야 했어.",
  ui_story_5040_50401201_57_dialog_content = "어쨌든 내가 제멋대로 굴어서 모두를 위험에 빠지게 했으니까,\n내가 책임지고 최선을 다해 모두를 구할게.",
  ui_story_5040_50401201_58_dialog_content = "음, 그건 좋은데 일단 사람들이 어디 있는지부터 알아야지.",
  ui_story_5040_50401201_59_dialog_content = "다들 무사하길 빌어야겠지...",
  ui_story_5040_50401201_60_dialog_content = "(키아랑 세이블, 그리고 아도니스 씨는 지금 어떤 상황일까... 걱정되네.)",
  ui_story_5040_50401201_61_dialog_content = "(근데 만약 예리아 씨의 언령이 세 사람을 못 찾으면 어떻게 해야 하지...)",
  ui_story_5040_50401201_62_dialog_content = "내 아기새가 돌아왔어.",
  ui_story_5040_50401201_63_dialog_content = "네? 어디요?",
  ui_story_5040_50401201_64_dialog_content = "호크, 여기야!",
  ui_story_5040_50401201_65_dialog_content = "퓌요오오──!",
  ui_story_5040_50401201_66_dialog_content = "크오오...",
  ui_story_5040_50401201_67_dialog_content = "음? 별로 안 반가운 선물도 딸려 와 버렸네...",
  ui_story_5040_50401201_68_dialog_content = "일단은 암귀 녀석들부터 처리해 버리죠!",
  ui_story_5040_50401201_69_dialog_content = "나도 돕게 해 줘! 다리에 난 이까짓 상처쯤이야...\n레디젤 사막에서 자란 나한텐 별문제도 안 되니까!",
  ui_story_5040_50401202_1_dialog_content = "콜록, 콜록콜록!",
  ui_story_5040_50401202_2_dialog_content = "어머, 의외로 조금 힘이 들긴 하네.",
  ui_story_5040_50401202_3_dialog_content = "이 암귀들도 저 분홍색 샌드버그를 피하려고 여기 온 걸까?",
  ui_story_5040_50401202_4_dialog_content = "그건 아닐 거예요. 몸을 피하려고 여기까지 왔다고 치기엔 너무 침착해요...",
  ui_story_5040_50401202_5_dialog_content = "후훗, 호크가 루미나를 잔뜩 쓰면서 여기저기 수색하고 있는 걸 보곤,\n지금 습격하면 승산이 있다고 생각했던 걸지도 몰라.",
  ui_story_5040_50401202_6_dialog_content = "자, 그럼 나의 아기새야, 이번엔 뭘 찾았니?",
  ui_story_5040_50401202_7_dialog_content = "퓌이!",
  ui_story_5040_50401202_8_dialog_content = "역시 못 찾았구나...",
  ui_story_5040_50401202_9_dialog_content = "이 근처에 샌드버그가 남긴 흔적은 없어.\n그 녀석은 자기가 땅속에 파둔 동굴로 도망쳤을 가능성이 높아.",
  ui_story_5040_50401202_10_dialog_content = "그렇게 된 거라면 아도니스, 키아, 세이블 세 사람도 높은 확률로\n그 녀석한테 휘말려서 동굴 속에 빠졌겠지...",
  ui_story_5040_50401202_11_dialog_content = "그럼 셋 다 굉장히 위험한 상태란 거잖아!",
  ui_story_5040_50401202_12_dialog_content = "그 세 사람만으로 녀석을 상대하는 건 절대 무리야.\n게다가 지하 동굴은 길이 복잡하게 나 있어서 길을 잃어버리기도 쉽고.",
  ui_story_5040_50401202_13_dialog_content = "그럼 얼른 세 사람이 어디 있는지 찾아야죠!",
  ui_story_5040_50401202_14_dialog_content = "걱정하지 마. 수색 범위를 지금보다 더 넓힐 거야.\n호크한테 사막 전체를 찾아보라고 할게.",
  ui_story_5040_50401202_15_dialog_content = "호... 콜록콜록, 콜록, 호크!",
  ui_story_5040_50401202_16_dialog_content = "예리아 씨, 멈춰요!",
  ui_story_5040_50401202_17_dialog_content = "얼굴색이 너무 안 좋잖아요. 이러다 쓰러져요!",
  ui_story_5040_50401202_18_dialog_content = "후후, 내 체력을 얕보면 곤란해, 아이테르 군. 나 아직 그 정도로 약하진 않아.",
  ui_story_5040_50401202_19_dialog_content = "난 지금까지 그 어떤 어려움을 겪게 되더라도, 전부 다 나 스스로 이겨내 왔어.",
  ui_story_5040_50401202_20_dialog_content = "그러니까 이번에도 반드시...",
  ui_story_5040_50401202_21_dialog_content = "우리 이 근처에 있는 레디젤 렌치 사람들한테 연락해요.",
  ui_story_5040_50401202_22_dialog_content = "뭐?",
  ui_story_5040_50401202_23_dialog_content = "스카이워커호로 돌아가서 통신 장치로 사메야마랑 다른 레디젤 렌치 사람들한테\n우릴 좀 도와 달라고 부탁해 보자는 거예요.",
  ui_story_5040_50401202_24_dialog_content = "혼자서 못 찾았으면, 이 사막에 사는 모든 사람들이랑 같이 찾으면 되죠!",
  ui_story_5040_50401202_25_dialog_content = "예리아 씨는 쿠리어 길드의 장로잖아요.\n예리아 씨 부탁이라면 다들 발 벗고 나서서 우릴 도와줄 거예요!",
  ui_story_5040_50401202_26_dialog_content = "내 부탁이라면 다들 발 벗고 나서서 도와줄 거라고?\n후후, 아이테르 군은 정말 순진하구나...",
  ui_story_5040_50401202_27_dialog_content = "난 지금껏 모든 일을 다 사무적으로만 처리해 왔어.\n남에게 도움을 준 적도 없고, 반대로 내가 남에게 신세를 진 적도 없지.",
  ui_story_5040_50401202_28_dialog_content = "나처럼 서비스 마인드도 없는 쿠리어가 없어지고,\n더 책임감 있는 사람이 온다면 다들 훨씬 좋아할걸?",
  ui_story_5040_50401202_29_dialog_content = "예리아 넌 있어도 그만, 없어도 그만인 쿠리어가 절대 아니야!",
  ui_story_5040_50401202_30_dialog_content = "레디젤 사막 사람들한테 쿠리어는 모두가 끈끈한 사이를\n유지할 수 있게 해 주는 다리 같은 존재야.",
  ui_story_5040_50401202_31_dialog_content = "나랑 아도니스가 서로 오래 연락을 주고받을 수 있었던 것도,\n다 쿠리어 길드가 있었기 때문이라구.",
  ui_story_5040_50401202_32_dialog_content = "타라 씨 말이 맞아요. 사람과 사람 사이의 관계는 그렇게 단순한 게 아니잖아요.",
  ui_story_5040_50401202_33_dialog_content = "사람들의 편지를 배달해 주었던 그 점만으로도,\n예리아 씨는 이 사막의 모두와 끈끈한 관계가 된 거예요.",
  ui_story_5040_50401202_34_dialog_content = "......",
  ui_story_5040_50401202_35_dialog_content = "정말이지, 너희 둘은 어쩔 수가 없구나.",
  ui_story_5040_50401202_36_dialog_content = "그럼 너희 말대로 다른 사람들한테 도움을 청해 보도록 하자.",
  ui_story_5040_50401202_37_dialog_content = "그렇지만 나처럼 아쉬울 때가 돼서야 도와달라고 찾는 사람을,\n저들이 무조건 도와주러 올 거라는 기대는 안 하는 게 좋을걸.",
  ui_story_5040_50401202_38_dialog_content = "해 보기 전엔 모르는 거죠.",
  ui_story_5040_50401202_39_dialog_content = "그럼 얼른 스카이워커호로 돌아가요!",
  ui_story_5040_50401202_40_dialog_content = "그럴 필요 없어, 아이테르 군. 나한테는 네 통신 장치보다 더 빠른 방법이 있으니까.",
  ui_story_5040_50401202_41_dialog_content = "네?",
  ui_story_5040_50401202_42_dialog_content = "이 능력은 내 루미나를 극심하게 소모하게 될 거야.\n일단 한 번 쓰면 꽤 오래 힘을 모아야 다시 쓸 수 있겠지만...",
  ui_story_5040_50401202_43_dialog_content = "지금 상황에선 이것보다 좋은 방법은 없을 테니까.",
  ui_story_5040_50401202_44_dialog_content = "예리아, 설마 아직까지도 아껴 둔 비장의 수단이 있었던 거야?",
  ui_story_5040_50401202_45_dialog_content = "그렇게 거창한 건 아니야.",
  ui_story_5040_50401202_46_dialog_content = "급하게 내 아기새들한테 연락해야 할 때가 있을지도 모르니까\n가지고 있던 비상 수단일 뿐이야.",
  ui_story_5040_50401202_47_dialog_content = "이 능력을 사용하면 호크를 통해서 저들의 도움을 받을 수 있을 거야.\n근처에 있는 레디젤 렌치 사람들한테 빠르게 내 말을 전할 수 있거든.",
  ui_story_5040_50401202_48_dialog_content = "전에는 써 본 적 없는 건가요?",
  ui_story_5040_50401202_49_dialog_content = "써 본 적 없어. 그러니까 이번이 처음이야.",
  ui_story_5040_50401202_50_dialog_content = "아기새야, 나 대신 이 소식을 사람들한테 전해 줘.",
  ui_story_5040_50401202_51_dialog_content = "퓌이!",
  ui_story_5040_50401202_52_dialog_content = "자, 가 봐!",
  ui_story_5040_50401202_53_dialog_content = "퓌요오오──!",
  ui_story_5040_50401202_54_dialog_content = "어여쁜 아기새야, 이번에는 부디 좋은 소식을 가지고 돌아와 주렴.",
  ui_story_5040_50401202_55_dialog_content = "<color=#e8d9bb>10여 분 후</color>",
  ui_story_5040_50401202_56_dialog_content = "여전히 답장이 없네...",
  ui_story_5040_50401202_57_dialog_content = "아무리 내 아기새라도 소식을 전하려면 어느 정도 시간이 걸릴 거야.",
  ui_story_5040_50401202_58_dialog_content = "보세요! 돌아왔어요!",
  ui_story_5040_50401202_59_dialog_content = "진짜네! 예리아의 호크야!",
  ui_story_5040_50401202_60_dialog_content = "퓌요오오──!",
  ui_story_5040_50401202_61_dialog_content = "발에 뭘 쥐고 있는 것 같아 보이는데... 으앗! 다 이쪽으로 던져 버렸는데요?!",
  ui_story_5040_50401202_62_dialog_content = "이건... 편지?",
  ui_story_5040_50401202_63_dialog_content = "정말로 편지였네! 하늘에서 흩날리면서 떨어지는 게 꼭 눈꽃 같아...",
  ui_story_5040_50401202_64_dialog_content = "엄청 많네요. 안에 쪽지도 있어요.",
  ui_story_5040_50401202_65_dialog_content = "우와, 이 종이는 뭐죠? 위에 낙서도 돼 있는데요?!",
  ui_story_5040_50401202_66_dialog_content = "내가 한 번 볼게.",
  ui_story_5040_50401202_67_dialog_content = "아, 이건 레디젤 렌치에서 쓰는 연락 방식이야.\n사막 북서쪽에선 우리가 찾는 사람이나 샌드버그는 못 봤다는 내용이고.",
  ui_story_5040_50401202_68_dialog_content = "모든 레디젤 렌치 멤버가 글을 읽고 쓸 줄 아는 건 아니라서,\n글 대신 낙서로 소통하는 사람들이 많아.",
  ui_story_5040_50401202_69_dialog_content = "정말로 답장을 보냈구나...",
  ui_story_5040_50401202_70_dialog_content = "퓌이!",
  ui_story_5040_50401202_71_dialog_content = "각지의 레디젤 렌치 사람들이 분홍색 샌드버그의 목격 기록을 여기 적어 줬다고?",
  ui_story_5040_50401202_72_dialog_content = "그럼 이 기록들만 잘 따라가면 그 샌드버그를 찾을 수 있고,\n녀석을 찾으면 동굴에 빠진 세 사람도 찾을 수 있겠네요?",
  ui_story_5040_50401202_73_dialog_content = "맞아...",
  ui_story_5040_50401202_74_dialog_content = "그럼 이러고 있을 게 아니라, 얼른 이 편지들을 확인해 보자!",
  ui_story_5040_50401202_75_dialog_content = "테일스트리트 근처에는 없고, 크림슨 밸리 근처에도 없대.",
  ui_story_5040_50401202_76_dialog_content = "일루미나 근처 쪽에도 없... 어라?",
  ui_story_5040_50401202_77_dialog_content = "어머, 있대.",
  ui_story_5040_50401202_78_dialog_content = "어디?!",
  ui_story_5040_50401202_79_dialog_content = "남쪽, 사막 깊은 곳에 있는 오아시스에서 봤다고 하네.",
  ui_story_5040_50401202_80_dialog_content = "거긴 원래부터 샌드버그들이 활동하는 구역이거든.\n그래서 가끔 레디젤 렌치 사람들이 거기 가서 샌드버그를 사냥하곤 했어.",
  ui_story_5040_50401202_81_dialog_content = "그리고 방금 전에 분홍색 샌드버그 한 마리가 땅속에서 튀어나오는 걸\n레디젤 렌치 멤버 몇 명이 봤다고 해.",
  ui_story_5040_50401202_82_dialog_content = "얼른 가자! 아도니스나 다른 애들을 찾을 수 있을지도 모르잖아!",
  ui_story_5040_50401202_83_dialog_content = "어서 타!",
  ui_story_5040_50401202_84_dialog_content = "<color=#e8d9bb>부르르릉──</color>",
  ui_story_5040_50401202_85_dialog_content = "으아아악!",
  ui_story_5040_50401202_86_dialog_content = "예리아 씨, 제, 제발, 운전 좀 살살 해요!",
  ui_story_5040_50401202_87_dialog_content = "<size=45>아이테르 군──!</size>",
  ui_story_5040_50401202_88_dialog_content = "<size=45>뭐── 라── 고──?</size>",
  ui_story_5040_50401202_89_option_content = "살── 살── 좀── 하── 라── 고── 요──!",
  ui_story_5040_50401202_90_dialog_content = "무슨 소리야! 지금이야말로 「1분 1초에 목숨이 달린 상황」이잖아!",
  ui_story_5040_50401202_91_option_content = "과── 속── 은── 안── 돼── 요──!",
  ui_story_5040_50401202_92_dialog_content = "후훗, 아이테르 군은 농담도 잘하는구나?",
  ui_story_5040_50401202_93_dialog_content = "사막엔 속도 제한 같은 건 없어!",
  ui_story_5040_50401202_94_dialog_content = "캬오오오──!",
  ui_story_5040_50401202_95_dialog_content = "암귀들이 쫓아오고 있어!",
  ui_story_5040_50401202_96_dialog_content = "따돌리자!",
  ui_story_5040_50401202_97_dialog_content = "아이테르 군, 차에서 안 떨어지게 꽉 잡아! 속도를 더 낼 거야!",
  ui_story_5040_50401202_98_dialog_content = "<color=#e8d9bb>부아아앙──!</color>",
  ui_story_5040_50401301_1_dialog_content = "<color=#e8d9bb>부릉부릉──!</color>",
  ui_story_5040_50401301_2_dialog_content = "으아아앗!",
  ui_story_5040_50401301_3_dialog_content = "완벽한 드리프트였어, 예리아!",
  ui_story_5040_50401301_4_dialog_content = "이 정도면 레디젤 렌치 사람들이랑 비교해도 손에 꼽을 것 같아!",
  ui_story_5040_50401301_5_dialog_content = "호오? 칭찬이라고 생각할게.",
  ui_story_5040_50401301_6_dialog_content = "암귀들은 저 멀리 뒤처져서, 이제 잘 보이지도 않아요.",
  ui_story_5040_50401301_7_dialog_content = "암귀도 따돌렸으니까, 이제 이런 운전을 계속할 필요는 없겠네.",
  ui_story_5040_50401301_8_dialog_content = "휴, 드디어 끝인가...",
  ui_story_5040_50401301_9_dialog_content = "거의 다 온 거야?",
  ui_story_5040_50401301_10_dialog_content = "아직 조금 더 가야 해.",
  ui_story_5040_50401301_11_dialog_content = "사막엔 모래 언덕이 끝없이 펼쳐져 있고, 경치도 다 비슷비슷하게 생겨서\n거리감과 방향 감각을 잃기 쉬워.",
  ui_story_5040_50401301_12_dialog_content = "난 걱정 하나도 안 돼. 예리아 네가 있잖아.",
  ui_story_5040_50401301_13_dialog_content = "전에도 누가 비슷한 말을 했던 것 같은데...",
  ui_story_5040_50401301_14_dialog_content = "그러니까 예리아가 있다면 마음 놓고 따라가도 된다는 거다! 틀릴 일은 없으니까!",
  ui_story_5040_50401301_15_dialog_content = "어제까지만 해도 조금 의심했었지만, 이제부턴 저도 예리아 씨를 믿을게요.",
  ui_story_5040_50401301_16_dialog_content = "사메야마랑 연락했을 때, 사메야마도 아까 타라 씨가 했던 말처럼\n예리아 씨라면 안심하고 믿어도 된다고 했었거든요.",
  ui_story_5040_50401301_17_dialog_content = "사메야마가 그런 말을 했어?",
  ui_story_5040_50401301_18_dialog_content = "당연한 거 아니겠어? 레디젤 렌치 사람들은 너한테 무척 고마워하고, 널 많이 믿고 있어.",
  ui_story_5040_50401301_19_dialog_content = "네가 레디젤 렌치의 험담을 할 때마다 내 기분이 팍 상하긴 하지만 말이야.",
  ui_story_5040_50401301_20_dialog_content = "그랬구나... 후훗, 고마워.",
  ui_story_5040_50401301_21_dialog_content = "참, PlayerName. 어제는 미안했어.",
  ui_story_5040_50401301_22_dialog_content = "어? 갑자기 왜요?",
  ui_story_5040_50401301_23_dialog_content = "어젯밤에 네가 다른 사람들한테 도움을 요청해 보자고 했을 때,\n내가 너무 틱틱거려서 네가 중간에 자리를 피했었잖아.",
  ui_story_5040_50401301_24_dialog_content = "아, 그거요? 전혀 신경 안 써요.",
  ui_story_5040_50401301_25_dialog_content = "근데 이해가 잘 안돼요. 예리아 씨는 레디젤 렌치를 왜 그렇게 싫어하는 거예요?",
  ui_story_5040_50401301_26_dialog_content = "맞아. 예리아도 이 사막 출신이니까, 레디젤 렌치엔 대해 잘 알 거 아냐.",
  ui_story_5040_50401301_27_dialog_content = "설마 어떤 정신 빠진 놈들이 대장 말을 안 듣고 네가 사는 마을을 약탈했던 거야?",
  ui_story_5040_50401301_28_dialog_content = "아니, 그게 아니라... 딱 그 반대야.\n내 부모님은 두 분 다 레디젤 렌치의 멤버고, 나도 한때는 그랬거든.",
  ui_story_5040_50401301_29_dialog_content = "하지만 난 일찌감치 레디젤 렌치는 물론이고, 우리 부모님과도 연락을 끊었어.",
  ui_story_5040_50401301_30_dialog_content = "왜요?",
  ui_story_5040_50401301_31_dialog_content = "어머, 아이테르 군은 누구한테나 그렇게 꼬치꼬치 캐묻고 그러니?",
  ui_story_5040_50401301_32_dialog_content = "죄, 죄송해요! 내키지 않는다면 말 안 해 주셔도 돼요...",
  ui_story_5040_50401301_33_dialog_content = "후훗, 얘는 정말 놀리지도 못하겠네.",
  ui_story_5040_50401301_34_dialog_content = "사실 무슨 엄청난 비밀이 있는 것도 아니야.\n그냥 내가 부모님과 레디젤 렌치의 방식을 받아들일 수가 없어서 그랬던 거야.",
  ui_story_5040_50401301_35_dialog_content = "부모님도 대부분의 레디젤 렌치 멤버들처럼 뭔가에 얽매이지 않고 자유분방하셨어.",
  ui_story_5040_50401301_36_dialog_content = "내가 철이 들기 전부터, 두 분은 내 생활에 거의 신경 쓰지 않으셨지.\n그저 내게 사막에서 생존할 때 필요한 지식 몇 가지만 알려 주셨고.",
  ui_story_5040_50401301_37_dialog_content = "남겨진 난 혼자 알아서 생활해야 했어.",
  ui_story_5040_50401301_38_dialog_content = "혼자서요?!",
  ui_story_5040_50401301_39_dialog_content = "상상이 잘 안되니?",
  ui_story_5040_50401301_40_option_content = "상상도 못 하겠어요.",
  ui_story_5040_50401301_41_dialog_content = "음... 전 지하에서 몇 년이나 갇혀 지내긴 했지만,\n그래도 제 곁에는 항상 스카이워커가 함께 있어 줬거든요.",
  ui_story_5040_50401301_42_dialog_content = "매일매일 단순하고 변화가 없는 생활을 보내면서도, 스카이워커 덕분에 외롭지 않았고요.",
  ui_story_5040_50401301_43_dialog_content = "그래서 혼자 사는 생활이라는 게 어떤 모습일지 상상이 안 돼요.",
  ui_story_5040_50401301_44_dialog_content = "참 부러운 인생이구나, 아이테르 군.",
  ui_story_5040_50401301_45_dialog_content = "스카이워커호가 널 아주 잘 보호해 줬던 모양이구나?",
  ui_story_5040_50401301_46_dialog_content = "네, 스카이워커는 제 소중한 가족이에요.",
  ui_story_5040_50401301_47_option_content = "상상할 수 있어요.",
  ui_story_5040_50401301_48_dialog_content = "17년 동안 지하에 갇혀 있었을 때, 제 곁에서 함께 있어 준 건 스카이워커밖에 없었어요.",
  ui_story_5040_50401301_49_dialog_content = "스카이워커는 제 선생님이기도 하고, 제 가족이기도 하죠.",
  ui_story_5040_50401301_50_dialog_content = "만약 그 17년 동안 스카이워커가 제 곁에 있어 주지 않았다면,\n저는 지금처럼은 되지 못했을 거예요.",
  ui_story_5040_50401301_51_dialog_content = "스카이워커호는 꽤 훌륭한 선생님인 모양이구나?",
  ui_story_5040_50401301_52_dialog_content = "그럼요! 당연하죠!",
  ui_story_5040_50401301_53_dialog_content = "넌 운이 좋았던 거야. 네가 운이 좋았다고 해서 다른 사람도 다 그런 건 아니야.",
  ui_story_5040_50401301_54_dialog_content = "이 사막은 이렇게나 광활하단다. 너무나도 넓어서 사람과 사람 사이의 거리가\n모래 바다만큼 멀리 떨어져 있다고 해도 될 정도야.",
  ui_story_5040_50401301_55_dialog_content = "아마 부모님은 이런 환경에서 지내는 데 너무 익숙해진 나머지,\n나도 당연히 혼자 알아서 잘 지낼 수 있을 거라고 여기셨을지도 모르지.",
  ui_story_5040_50401301_56_dialog_content = "내가 어렸을 때, 부모님은 두 분 마음 내키는 대로 사는 데만 신경을 써서,\n내겐 거의 아무런 신경도 쓰지 않으셨어.",
  ui_story_5040_50401301_57_dialog_content = "레디젤 렌치엔 확실히 그런 사람들이 가끔 있긴 해...",
  ui_story_5040_50401301_58_dialog_content = "두 분 다 참 열정이 과한 부모셨지. 아무튼 난 이 집 저 집을 돌아다니면서 신세를 졌고,\n그 덕분에 별 탈 없이 어른이 될 수 있었어.",
  ui_story_5040_50401301_59_dialog_content = "레디젤 렌치 사람들은 다들 열정적이지.\n하지만 난 그래도 가족들이 늘 신경 써 주고, 돌봐 주는 아이들이 부러웠어.",
  ui_story_5040_50401301_60_dialog_content = "그 아이들은 기댈 수 있는 누군가가 항상 곁에 있어 줬고,\n아무런 고민과 걱정 없이 울고 웃을 수 있었으니까.",
  ui_story_5040_50401301_61_dialog_content = "게다가 모두한테 둘러싸여 생활하는 건 확실히 떠들썩하지만,\n항상 다른 사람과 어울려야 해서 결국 나만의 공간을 잃게 됐어.",
  ui_story_5040_50401301_62_dialog_content = "레디젤 렌치의 분위기는 너무 왁자지껄하고, 너무 맹렬했어.\n반면에 난 그저 조용한 환경을 가지고 싶었어.",
  ui_story_5040_50401301_63_dialog_content = "그래서 어느 날, 난 부모님, 그리고 레디젤 렌치와 갈라서고,\n내가 속해 있던 무리에서 벗어나기로 했어.",
  ui_story_5040_50401301_64_dialog_content = "난 그 어느 세력에도 속하고 싶지 않았고, 그 누구와도 접점을 만들고 싶지 않았어.\n그냥 오롯이 자유로운 한 마리 새가 되고 싶었던 거야.",
  ui_story_5040_50401301_65_dialog_content = "그래서 쿠리어 길드의 업무도, 내겐 그냥 공적인 사무에 불과해.",
  ui_story_5040_50401301_66_dialog_content = "예리아, 너 정말 그렇게 생각해?",
  ui_story_5040_50401301_67_dialog_content = "내가 처음으로 네 사무실에 들어갔을 때, 나 진짜 깜짝 놀랐어.\n사무실 안에 장식품이 그렇게 많을 줄은 몰랐거든.",
  ui_story_5040_50401301_68_dialog_content = "그 장식들은 여기저기 어지럽게 널려 있었고, 정리도 거의 안 된 상태였어.\n어떤 건 위에 먼지까지 쌓여 있었고 말이야.",
  ui_story_5040_50401301_69_dialog_content = "그 장식들은 내 소중한 동료들이야. 아무리 너라도 그 장식들은 못 줘.",
  ui_story_5040_50401301_70_dialog_content = "난 그 장식들엔 하나도 관심 없어!\n그리고 난 닥치는 대로 남의 물건 뺏는 그런 나쁜 사람도 아니거든!",
  ui_story_5040_50401301_71_dialog_content = "내가 하고 싶은 말은 그러니까 넌 그 장식들을 아끼는 것 같지만,\n사실은 전혀 마음에 두고 있지 않다는 거야. 안 그래?",
  ui_story_5040_50401301_72_dialog_content = "......",
  ui_story_5040_50401301_73_dialog_content = "넌 그냥 네가 레디젤 렌치 출신이라고는 상상도 못 할 장식들로,\n자기가 레디젤 렌치 출신이 아니라는 걸 증명하고 싶을 뿐이겠지.",
  ui_story_5040_50401301_74_dialog_content = "하지만 너 자신도 레디젤 렌치가 아니면,\n자기가 대체 어디 사람이라고 해야 할지 모르는 거잖아.",
  ui_story_5040_50401301_75_dialog_content = "(어쩐지 예리아 씨 사무실에 화려하고 정신없어 보이는 장식들이 잔뜩 있더라...)",
  ui_story_5040_50401301_76_dialog_content = "(어쩌면 예리아 씨는 마음의 공허함을 채우려고 그것들을 갖다 둔 걸지도 모르겠네.)",
  ui_story_5040_50401301_77_dialog_content = "그럼 네 눈에 비치는 난 어떤 모습인데?",
  ui_story_5040_50401301_78_dialog_content = "언제나 속을 알 수 없는 사람인 척하곤 있지만, 사실은 그냥 애정결핍이야.",
  ui_story_5040_50401301_79_dialog_content = "사랑을 주는 것도, 사랑을 받는 것도 거부하고 있는 거지.",
  ui_story_5040_50401301_80_dialog_content = "그럼 설마 사랑이 뭔지도 모르고, 사랑을 느껴 본 적도 없는 사람한테\n무작정 다른 사람을 사랑하라고 말하고 싶은 거야?",
  ui_story_5040_50401301_81_dialog_content = "그런 뜻으로 한 말은 아니잖아...",
  ui_story_5040_50401301_82_dialog_content = "저기... 예리아 씨, 자기 비하가 조금 심하신 거 아니에요?",
  ui_story_5040_50401301_83_dialog_content = "자기 비하?",
  ui_story_5040_50401301_84_dialog_content = "전 예리아 씨가 사랑이 뭔지도 모르는 사람은 아니라고 생각해요.",
  ui_story_5040_50401301_85_dialog_content = "말로는 사랑이 뭔지 모른다고 하셨지만,\n이번 여행에선 타라 씨랑 아도니스 씨를 도와주고 계시잖아요.",
  ui_story_5040_50401301_86_dialog_content = "백야성에서도 예리아 씨가 직접 우표를 어떻게 판매해야 하는지 가르쳐 주셨고요.",
  ui_story_5040_50401301_87_dialog_content = "그 덕에 일루미나에 가면 타라 씨를 도와줄 사람이 있다는 정보도\n티나한테 들을 수 있었고 말이죠.",
  ui_story_5040_50401301_88_dialog_content = "비록 타라 씨가 기억상실인 건 연기였지만,\n어쨌든 지금까지 예리아 씨가 많은 도움을 준 건 사실이니까요.",
  ui_story_5040_50401301_89_dialog_content = "그리고 이렇게까지 해 주고 있는 이유는, 예리아 씨도 타라 씨랑 아도니스 씨가\n안 좋게 헤어지는 걸 보고 싶지 않기 때문이잖아요?",
  ui_story_5040_50401301_90_dialog_content = "......",
  ui_story_5040_50401301_91_dialog_content = "저 애들처럼 아스트라 대륙의 끝과 끝이라는 거리를 뛰어넘어서,\n결국 서로 함께하게 된 커플은 드물잖아. 이유는 그게 다야.",
  ui_story_5040_50401301_92_dialog_content = "마치 하늘을 날아다니는 새랑 땅굴에서 사는 토끼가 서로 사랑에 빠진 것처럼,\n이상하고 신기하니까.",
  ui_story_5040_50401301_93_dialog_content = "좀처럼 없는 경우라서, 난 이야기를 조금 들어보고 싶었어.\n그래서 순간적으로 흥미가 생겨서 같이 다닌 거야.",
  ui_story_5040_50401301_94_dialog_content = "그랬다면 이럴 필요 없이, 그냥 같이 다니면서 구경만 하셨어야 하는 거 아닌가요?",
  ui_story_5040_50401301_95_dialog_content = "하지만 그렇지 않고 두 사람을 돕기 위해 최선을 다하고 계신걸요.\n예리아 씨는 계속 부정하고 계시지만요.",
  ui_story_5040_50401301_96_dialog_content = "지금까진 제대로 사랑받은 적 없었다 해도, 예리아 씨는 강하고 대단한 사람이니까,\n앞으로 반드시 예리아 씨를 사랑해 주는 사람을 만날 수 있을 거예요!",
  ui_story_5040_50401301_97_dialog_content = "그러니...?",
  ui_story_5040_50401301_98_dialog_content = "난 그저 모든 일을 사무적으로 대하는 평범한 쿠리어일 뿐인걸.",
  ui_story_5040_50401301_99_dialog_content = "자기 자신을 보잘것없다고 여기면 안 돼요!",
  ui_story_5040_50401301_100_dialog_content = "예리아 씨는 쿠리어예요. 사막 사람들한텐 절대로 없어서는 안 될 사람이라고요!",
  ui_story_5040_50401301_101_dialog_content = "예리아 씨는 소중한 사람이에요!",
  ui_story_5040_50401301_102_dialog_content = "......!",
  ui_story_5040_50401301_103_dialog_content = "맞아! 예리아, 넌 소중해!",
  ui_story_5040_50401301_104_dialog_content = "사막은 가혹한 곳이야. 이런 환경에서 살아가려면 서로 의지하고, 서로 도와야 해.",
  ui_story_5040_50401301_105_dialog_content = "사막에 사는 모든 오로리안들은 모래 바다 위의 작은 조각배 같은 존재야.\n그리고 조각배는 쉽게 뒤집어질 수 있어.",
  ui_story_5040_50401301_106_dialog_content = "하지만 서로를 연결해 둔다면 어지간한 문제에는 끄떡없을 정도로 견고해지지.",
  ui_story_5040_50401301_107_dialog_content = "그렇게 우리라는 작은 조각배를 연결해 주고 있는 게 바로 쿠리어 길드야!",
  ui_story_5040_50401301_108_dialog_content = "......",
  ui_story_5040_50401301_109_dialog_content = "후훗, 아도니스가 왜 북방에서 떠날 용기를 냈는지 이제 알겠어.",
  ui_story_5040_50401301_110_dialog_content = "뭐?!",
  ui_story_5040_50401301_111_dialog_content = "왜죠?",
  ui_story_5040_50401301_112_dialog_content = "그건 네가 스스로 생각해 보렴, 아이테르 군.",
  ui_story_5040_50401301_113_dialog_content = "궁금하게 만들어 놓고 그러는 게 어디 있어요!",
  ui_story_5040_50401301_114_dialog_content = "지금은 다른 이야기를 하고 있을 때가 아닌 것 같거든.",
  ui_story_5040_50401301_115_dialog_content = "크오오오──!",
  ui_story_5040_50401301_116_dialog_content = "또 암귀야?! 대체 어디서 자꾸 튀어나오는 거죠?",
  ui_story_5040_50401301_117_dialog_content = "샌드버그가 지하에 판 땅굴을 점거해서 자기들 은신처로 사용하고 있는 걸지도 모르겠네.",
  ui_story_5040_50401301_118_dialog_content = "우리 목표가 그리 멀지 않은 곳에 있나 봐.",
  ui_story_5040_50401301_119_dialog_content = "그럼 단숨에 녀석들을 처치해 버리자!",
  ui_story_5040_50401302_1_dialog_content = "<color=#e8d9bb>끼이이익──!</color>",
  ui_story_5040_50401302_2_dialog_content = "여기가 바로 샌드버그의 서식지라고 했던 오아시스인가요?",
  ui_story_5040_50401302_3_dialog_content = "샌드버그들한테 점거당하지만 않았어도, 마을로 발전할 수 있었을 거야.",
  ui_story_5040_50401302_4_dialog_content = "하지만 지금은 잡초만 무성하고, 주변은 황폐한 오아시스에 불과해.",
  ui_story_5040_50401302_5_dialog_content = "지금 이 상태를 유지해도 나쁘지 않을 것 같아요. 겉보기엔 꽤 멋지니까요.",
  ui_story_5040_50401302_6_dialog_content = "그래? 그럼 이 아름다운 호수 주변의 모래 아래에, 샌드버그의 공격을 받고 목숨을 잃은\n동물들과 오로리안들의 유해가 잔뜩 쌓여 있다고 한다면?",
  ui_story_5040_50401302_7_dialog_content = "히익!",
  ui_story_5040_50401302_8_dialog_content = "사막에선 물건이든 생명체든, 아름다울수록 치명적인 법이야.",
  ui_story_5040_50401302_9_dialog_content = "그러니까 아름답다고 그 뒤에 도사리고 있는 위험을 무시하면 안 돼. 알겠니?",
  ui_story_5040_50401302_10_dialog_content = "아, 알겠어요...",
  ui_story_5040_50401302_11_dialog_content = "이상하네, 이 근처엔 샌드버그는커녕, 샌드버그 비늘 하나도 안 보여.",
  ui_story_5040_50401302_12_dialog_content = "다 이사라도 갔나?",
  ui_story_5040_50401302_13_dialog_content = "다른 가능성도 있어.",
  ui_story_5040_50401302_14_dialog_content = "그 분홍색 샌드버그가 다른 샌드버그를 전부 다 쓰러트리고\n이 오아시스를 독차지한 걸지도 몰라.",
  ui_story_5040_50401302_15_dialog_content = "얼른 이 근처에 그 녀석의 흔적이 있는지 찾아보자!",
  ui_story_5040_50401302_16_dialog_content = "호크, 네가 한 번 더 수고해 줘야 할 것 같아.",
  ui_story_5040_50401302_17_dialog_content = "퓌이!",
  ui_story_5040_50401302_18_dialog_content = "그럼 저도 감응 능력으로 주변을 확인해 볼게요.",
  ui_story_5040_50401302_19_option_content = "(강제 감응!)",
  ui_story_5040_50401302_20_dialog_content = "(제발... 분홍색 샌드버그의 흔적이라도 좋고,\n키아나 아도니스 씨의 기척이라도 좋으니까, 제발 뭐라도 좀 감응되라...)",
  ui_story_5040_50401302_21_dialog_content = "이건...?",
  ui_story_5040_50401302_22_dialog_content = "예리아 씨, 타라 씨! 키아랑 아도니스 씨가 어디 있는지 감응했어요!",
  ui_story_5040_50401302_23_dialog_content = "어머, 호크보다 빨리 찾아냈구나.",
  ui_story_5040_50401302_24_dialog_content = "다들 어디 있어?!",
  ui_story_5040_50401302_25_dialog_content = "이쪽이에요!",
  ui_story_5040_50401302_26_dialog_content = "어디? 키 작은 나무들 빼곤 아무것도 없는데...?",
  ui_story_5040_50401302_27_dialog_content = "감응 능력으로 찾아낸 거니까 이 근처에 있다는 건 틀림없어요.\n그치만 정신을 잃은 것처럼 아무 반응도 안 해요.",
  ui_story_5040_50401302_28_dialog_content = "들려요──?",
  ui_story_5040_50401302_29_dialog_content = "키아──! 아도니스 씨──! 세이블──!",
  ui_story_5040_50401302_30_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_5040_50401302_31_dialog_content = "잠깐, 저 나무들 뭔가 이상해. 저 품종이라면 위로 곧게 자라야 하는데,\n저것들은 땅 쪽으로 쓰러져 있어.",
  ui_story_5040_50401302_32_dialog_content = "사람이 남긴 흔적이야. 설마...",
  ui_story_5040_50401302_33_dialog_content = "아도니스?!",
  ui_story_5040_50401302_34_dialog_content = "키아도 있어요! 근데 세이블이 안 보여요!",
  ui_story_5040_50401302_35_dialog_content = "두 사람 다 숨은 잘 쉬고 있어. 그냥 기절한 거야.",
  ui_story_5040_50401302_36_dialog_content = "아도니스, 정신 좀 차려 봐!",
  ui_story_5040_50401302_37_dialog_content = "으윽... 여, 여긴...",
  ui_story_5040_50401302_38_dialog_content = "무사했구나! 정말 다행이야!",
  ui_story_5040_50401302_39_dialog_content = "윽! 타라, 조금만 살살... 갈비뼈가 부러지겠어. 아니, 이미 부러졌을 수도 있겠네...",
  ui_story_5040_50401302_40_dialog_content = "미안해, 너무 기뻐서 조절을 못 했어. 정말 괜찮은 거 맞지?",
  ui_story_5040_50401302_41_dialog_content = "어떻게 여기까지 온 건지 기억해? 세이블은 어디 있어?",
  ui_story_5040_50401302_42_dialog_content = "잠깐 좀 생각해 볼게요...",
  ui_story_5040_50401302_43_dialog_content = "모래 폭풍이 세차게 불었을 때, 땅이 아래로 가라앉았고,\n분홍색 샌드버그가 절 향해 달려들었습니다...",
  ui_story_5040_50401302_44_dialog_content = "전 겁에 질렸고, 흘러내리는 모래와 거센 바람에 휘말리지 않으려고\n죽기 살기로 녀석을 끌어안고 비늘을 붙잡았죠.",
  ui_story_5040_50401302_45_dialog_content = "그리고 녀석 때문에 땅굴 같은 곳으로 끌려갔습니다. 아주 어두운 곳이었어요.",
  ui_story_5040_50401302_46_dialog_content = "큰소리로 키아랑 세이블을 불렀지만, 아무런 대답도 없었고요.",
  ui_story_5040_50401302_47_dialog_content = "녀석이 계속 세차게 꿈틀대는 바람에 손을 놓을 엄두도 못 냈고,\n그러다 결국 기절해 버렸습니다.",
  ui_story_5040_50401302_48_dialog_content = "다음에 또 샌드버그를 만나면, 그땐 이번처럼 몸에 매달리고 그러지 마.",
  ui_story_5040_50401302_49_dialog_content = "지금 살아있는 게 기적이라고 해도 좋을 정도로 아주 위험한 행동이니까.",
  ui_story_5040_50401302_50_dialog_content = "어, 어쩔 수 없었어요. 전 샌드버그를 상대해 본 경험이 없으니까요...",
  ui_story_5040_50401302_51_dialog_content = "아무튼 살아있으니까 그것만으로도 이미 충분히 다행이야.",
  ui_story_5040_50401302_52_dialog_content = "응, 나도 정말 다행이라고 생각해.",
  ui_story_5040_50401302_53_dialog_content = "아, 그렇지! 이거 봐!",
  ui_story_5040_50401302_54_dialog_content = "그 분홍색 샌드버그의 비늘이네?!",
  ui_story_5040_50401302_55_dialog_content = "맞습니다! 제가 그 녀석 몸에 매달려 여기저기 끌려다닐 때, 우연히 떼어낸 비늘입니다!",
  ui_story_5040_50401302_56_dialog_content = "하나밖에 못 구하긴 했지만, 부족하지 않았으면 좋겠네요.",
  ui_story_5040_50401302_57_dialog_content = "(근데 사실 타라 씨는 애초부터 기억상실증에 걸린 것도 아니었잖아?\n이걸 아도니스 씨한테 얘기해 줘야 하나, 말아야 하나?)",
  ui_story_5040_50401302_58_dialog_content = "아도니스, 저기... 너한테 털어놓을 게 하나 있어...",
  ui_story_5040_50401302_59_dialog_content = "응? 무슨 일인데?",
  ui_story_5040_50401302_60_dialog_content = "나 기억상실 아니야.",
  ui_story_5040_50401302_61_dialog_content = "다 거짓말이었어. 널 시험에 빠트려서, 네가 북방을 떠날 용기를\n낼 수 있게 해 주고 싶어서 이런 짓을 한 거야...",
  ui_story_5040_50401302_62_dialog_content = "...타라... 그건 아니잖아...",
  ui_story_5040_50401302_63_dialog_content = "정말 미안해...",
  ui_story_5040_50401302_64_dialog_content = "내 의견만 앞세워서 너한테 북방을 떠나라고 강요하면 안 됐던 거야.\n심지어는 네 목숨까지 위험하게 만들었어. 네가 날 비난하고 원망해도 다 받아들일게.",
  ui_story_5040_50401302_65_dialog_content = "앞으로 두 번 다시 너한테 낯선 사막에서 생활하자고 강요하지 않을게.\n우리... 앞으론 쭉 북방에 살자.",
  ui_story_5040_50401302_66_dialog_content = "근데 북방처럼 교통이 불편한 곳에 살면,\n아스트라 대륙 각지에 있는 유적 탐험은 어떻게 할 생각이야?",
  ui_story_5040_50401302_67_dialog_content = "유적 탐험은... 그만둘 거야.",
  ui_story_5040_50401302_68_dialog_content = "그 유적들보단, 아도니스 네가 나한테 더 소중하니까.",
  ui_story_5040_50401302_69_dialog_content = "......",
  ui_story_5040_50401302_70_dialog_content = "나 화났어.",
  ui_story_5040_50401302_71_dialog_content = "뭐?!",
  ui_story_5040_50401401_1_dialog_content = "나 지금, 정말 많이 화가 나.",
  ui_story_5040_50401401_2_dialog_content = "미안해...",
  ui_story_5040_50401401_3_dialog_content = "사과받고 싶은 게 아니야.\n그것보단 내가 왜 화가 난 건지 제대로 들어 줬으면 좋겠어.",
  ui_story_5040_50401401_4_dialog_content = "과거의 난 굉장히 나약한 사람이었어.\n그래서 북방 밖으로는 한 발짝도 안 나가려고 했고. 암귀에 맞서는 건 엄두도 못 냈어.",
  ui_story_5040_50401401_5_dialog_content = "내가 그 모양이었으니까, 너도 어떻게 해야 내가 용기를 내게\n만들 수 있을지 막막했을 거라고 생각해.",
  ui_story_5040_50401401_6_dialog_content = "아도니스...",
  ui_story_5040_50401401_7_dialog_content = "그러니까 아도니스 넌 타라가 기억상실인 척해서 화가 난 게 아니라는 거구나?",
  ui_story_5040_50401401_8_dialog_content = "맞아요. 사실 타라가 기억상실이 아니라는 건 어젯밤에 이미 눈치챘어요.\n하지만 화는 안 났어요.",
  ui_story_5040_50401401_9_dialog_content = "오히려 진짜로 기억상실에 걸린 게 아니란 걸 알아서 안심했어요.",
  ui_story_5040_50401401_10_dialog_content = "제가 너무 싫어져서 타라가 절 잊으려고 했단 게 아니란 걸 드디어 알게 됐으니까요.",
  ui_story_5040_50401401_11_dialog_content = "그럼 대체 왜 화가 난 건데?",
  ui_story_5040_50401401_12_dialog_content = "「타협」 때문이겠지?",
  ui_story_5040_50401401_13_dialog_content = "「타협」이요? 뭐랑요?",
  ui_story_5040_50401401_14_dialog_content = "역시 예리아 씨는 금방 눈치채셨군요.",
  ui_story_5040_50401401_15_dialog_content = "나 지금 감이 하나도 안 오는데, 수수께끼는 그만하고 그냥 알려주면 안 될까?",
  ui_story_5040_50401401_16_dialog_content = "제가 화가 난 건, 타라가 저랑 북방에서 생활하겠다는 이유만으로,\n세계 각지를 탐험하러 다니겠다는 자기 꿈을 포기하겠다고 했기 때문입니다.",
  ui_story_5040_50401401_17_option_content = "타라 씨를 옭아매는 게 싫은 거구나?",
  ui_story_5040_50401401_18_dialog_content = "그렇죠!",
  ui_story_5040_50401401_19_option_content = "설마 타라 씨가 싫어진 거야?",
  ui_story_5040_50401401_20_dialog_content = "설마요! 제가 타라를 싫어할 리가 없잖습니까.",
  ui_story_5040_50401401_21_dialog_content = "전 타라의 성격을 아주 잘 압니다.\n타라는 절대 북방에서 잠잠한 일생을 보내는 걸 원하지 않을 겁니다.",
  ui_story_5040_50401401_22_dialog_content = "지금은 저와 함께 북방에 남겠다고 말했지만,\n그건 자신의 뜻을 접어 타협하고, 제게 양보한 결정입니다.",
  ui_story_5040_50401401_23_dialog_content = "전 저 때문에 타라가 자기 뜻을 꺾는 걸 원하지 않아요!",
  ui_story_5040_50401401_24_dialog_content = "아도니스, 너...",
  ui_story_5040_50401401_25_dialog_content = "내가 좋아하는 건 언제나 용감하게 여러 곳을 모험하고, 유적을 탐험하는 너야.",
  ui_story_5040_50401401_26_dialog_content = "네가 있었기 때문에, 항상 북방에만 머물러 있던 난\n아스트라 대륙이 얼마나 드넓은지 알 수 있었어.",
  ui_story_5040_50401401_27_dialog_content = "난 아직도 네가 레디젤 사막에서 일루미나 방어선 쪽을 바라보면,\n지평선 위로 구불구불한 성벽이 보인다고 설명해 줬던 걸 기억해.",
  ui_story_5040_50401401_28_dialog_content = "그리고 백야성에서 아스트라 대륙을 내려다볼 때 봤다던 산맥이랑 평원들,\n그리고 발아래의 갖가지 구름까지도...",
  ui_story_5040_50401401_29_dialog_content = "풉... 그다음엔 내가 백야성 병사한테 도둑으로 오해받아서\n잡혔던 일 얘기하려고 그랬지?",
  ui_story_5040_50401401_30_dialog_content = "그땐 정말 곤란했어. 덕분에 진짜 도둑을 잡아주려고\n백야성 병사들이랑 한참을 같이 다녔었잖아.",
  ui_story_5040_50401401_31_dialog_content = "하하하, 그랬었지. 그래도 네 눈썰미랑 달리기 실력이 좋아서 진짜 도둑을 잡았으니 망정이지.",
  ui_story_5040_50401401_32_dialog_content = "내 결백을 증명하려고 진짜 노력했었다구!",
  ui_story_5040_50401401_33_dialog_content = "어쩌다 보니 이야기가 많이 길어졌지만, 내가 하고 싶었던 말은...",
  ui_story_5040_50401401_34_dialog_content = "타라, 널 만나기 전까지 내 세상은 설원처럼 새하얄 뿐이었어.",
  ui_story_5040_50401401_35_dialog_content = "변화 하나 없는 내 삶, 내 세상을 소중한 색채로 알록달록하게 물들여 준 건...\n바로 너야, 타라.",
  ui_story_5040_50401401_36_dialog_content = "그리고 난 그런 널 사랑해. 난 널 얽매는 존재가 되고 싶지 않아.\n네가 이 세상을 자유롭게 탐험해 줬으면 해.",
  ui_story_5040_50401401_37_dialog_content = "앞으로 너랑 발맞춰 걸을 수 있도록, 내가 더 노력하고, 용기를 낼게!",
  ui_story_5040_50401401_38_dialog_content = "<size=45>아도니스──!</size>",
  ui_story_5040_50401401_39_dialog_content = "윽──! 아파! 살살 좀!",
  ui_story_5040_50401401_40_dialog_content = "두 사람은 저런 마음이었던 거네요.",
  ui_story_5040_50401401_41_dialog_content = "감응 능력으로 사람의 생각을 꿰뚫어 볼 수 있는 아이테르 군이라도,\n사람의 마음을 정확히 알 순 없는 거야.",
  ui_story_5040_50401401_42_dialog_content = "제 감응 능력은 만능이 아니거든요!",
  ui_story_5040_50401401_43_dialog_content = "맞아. 서로의 마음을 알 수 없기 때문에 사람은 서로 오해하게 되는 건가 봐.\n오해는 서먹함을 낳고, 그러다 보면 다른 사람과의 관계 자체를 끊게 되는 거겠지.",
  ui_story_5040_50401401_44_dialog_content = "하지만 서로 소통하며 그 서먹함을 이겨내고, 다시 한번 관계를 구축한다면...",
  ui_story_5040_50401401_45_dialog_content = "서로의 관계는 더 견고해져서 깨지지 않을지도 모르겠네.",
  ui_story_5040_50401401_46_dialog_content = "음... 갑자기 왜 시끄럽지...",
  ui_story_5040_50401401_47_dialog_content = "키아! 드디어 깨어났구나!",
  ui_story_5040_50401401_48_dialog_content = "PlayerName 씨? 예리아 장로님?\n타라 씨랑 아도니스 씨까지? 두 사람, 다시 사이가 좋아졌네요?",
  ui_story_5040_50401401_49_dialog_content = "이런저런 일들이 있었지만, 결국엔 화해했어!",
  ui_story_5040_50401401_50_dialog_content = "다행이에요. 저랑 세이블이 샌드버그의 움직임에 휘말렸을 땐,\n아도니스 씨한테 위험한 일이 생기진 않았을까 무척 걱정했었거든요.",
  ui_story_5040_50401401_51_dialog_content = "참! 세이블은요? 세이블은 어디 있죠?",
  ui_story_5040_50401401_52_dialog_content = "세이블은 못 봤어. 여기 와 보니까 키아 너랑 아도니스 씨 둘만 쓰러져 있더라고.\n감응도 해 봤는데, 이 근처에서 세이블의 기운은 못 느꼈어.",
  ui_story_5040_50401401_53_dialog_content = "기절하기 전에 무슨 일이 있었는지 기억나?",
  ui_story_5040_50401401_54_dialog_content = "저, 저랑 세이블 둘 다 사막 폭풍에 휩쓸려서 공중으로 날아갔는데,\n세이블이 샌드버그의 뿔을 잡았던 게 기억이 나요...",
  ui_story_5040_50401401_55_dialog_content = "그리고 샌드버그가 땅속으로 들어가서 저랑 세이블도 덩달아 끌려들어 갔는데,\n전 그때 땅속에 있던 바위에 머리를 부딪히는 바람에 기절해 버렸고요.",
  ui_story_5040_50401401_56_dialog_content = "키아도 도중에 기절한 거면, 대체 누가 너랑 아도니스 씨를 여기 숨겨 놓은 거지?",
  ui_story_5040_50401401_57_dialog_content = "설마...",
  ui_story_5040_50401401_58_dialog_content = "세이블?",
  ui_story_5040_50401401_59_dialog_content = "그치만 세이블이 두 사람을 여기 숨겨 놓은 거라면,\n왜 세이블은 이 근처에서 안 보이는 거지?",
  ui_story_5040_50401401_60_dialog_content = "키아랑 아도니스를 위해 혼자서 샌드버그를 유인했을 수도 있고, 그게 아니라면...",
  ui_story_5040_50401401_61_dialog_content = "이제 한계라고 느꼈을지도 몰라요...",
  ui_story_5040_50401401_62_dialog_content = "한계? 또 둘이서만 아는 얘기야?",
  ui_story_5040_50401401_63_dialog_content = "PlayerName 씨, 사실 세이블은 오로리안이 아니에요.\n아니, 세이블은 오로리안이었어요. 예전에는요.",
  ui_story_5040_50401401_64_dialog_content = "?!",
  ui_story_5040_50401401_65_dialog_content = "역시...",
  ui_story_5040_50401401_66_dialog_content = "아이테르 군은 하나도 안 놀라는구나.",
  ui_story_5040_50401401_67_dialog_content = "도중에 조금 이상한 점을 느끼긴 했지만, 심증만 있지 물증은 없었거든요...",
  ui_story_5040_50401401_68_dialog_content = "연인에게 버림받고 절망에 빠져 있을 때 암귀의 유혹을 받았고,\n결국 암귀 같은 모습으로 변하고 만 거예요.",
  ui_story_5040_50401401_69_dialog_content = "겉모습이 바뀌고, 속마음도 영향을 받았지만,\n세이블의 의식은 계속 파괴의 충동에 맞서고 있었어요.",
  ui_story_5040_50401401_70_dialog_content = "하지만 얼마 전에 더는 충동을 억누를 수 없을 것 같다고 제게 말했어요...",
  ui_story_5040_50401401_71_dialog_content = "어떻게 그런...",
  ui_story_5040_50401401_72_dialog_content = "(이런 상황... 전에도 겪어본 적 있었던 것 같아...)",
  ui_story_5040_50401401_73_dialog_content = "PlayerName, 넌 세이블이 어떤 사람이라고 생각하니?",
  ui_story_5040_50401401_74_option_content = "좋은 사람 같았어요.",
  ui_story_5040_50401401_75_dialog_content = "겉모습이 조금 이상하긴 하지만, 세이블은 모두와 친하게 지냈어요.\n그래서 전 세이블은 좋은 사람이라고 생각해요.",
  ui_story_5040_50401401_76_dialog_content = "세이블이 어려운 상황에 처해 있다면, 우리가 도와줘야 해요.",
  ui_story_5040_50401401_77_option_content = "잘 모르겠어요...",
  ui_story_5040_50401401_78_dialog_content = "세이블은 부끄럼을 좀 많이 타서, 얘기를 많이 나눠 보진 못했어요.\n하지만 세이블은 마음씨 좋은 사람 같았어요.",
  ui_story_5040_50401401_79_dialog_content = "세이블만 괜찮다면, 저도 세이블과 친구가 되고 싶어요.",
  ui_story_5040_50401401_80_dialog_content = "그럼 최선을 다해 세이블을 찾아보자.",
  ui_story_5040_50401401_81_dialog_content = "네!",
  ui_story_5040_50401401_82_dialog_content = "퓌요오오──!",
  ui_story_5040_50401401_83_dialog_content = "아기새가 정보를 좀 가져온 모양이네. 수고했어, 호크.",
  ui_story_5040_50401401_84_dialog_content = "퓌이, 퓌요오!",
  ui_story_5040_50401401_85_dialog_content = "세이블의 흔적을 찾은 거야?",
  ui_story_5040_50401401_86_dialog_content = "지금 어디 있죠?!",
  ui_story_5040_50401401_87_dialog_content = "퓌이──",
  ui_story_5040_50401401_88_dialog_content = "우리 발밑에 있다고?",
  ui_story_5040_50401401_89_dialog_content = "발밑이요?",
  ui_story_5040_50401401_90_dialog_content = "발밑에서 아주 미약한 다크매터가 다가오는 게 느껴지긴 하는데...",
  ui_story_5040_50401401_91_dialog_content = "<color=#e8d9bb>쿠르릉──!</color>",
  ui_story_5040_50401401_92_dialog_content = "으앗?! 땅이 흔들려요! 설마 샌드버그가 나타난 건가?!",
  ui_story_5040_50401401_93_dialog_content = "<size=45>그오오오──!</size>",
  ui_story_5040_50401401_94_dialog_content = "타라! 조심해!",
  ui_story_5040_50401401_95_dialog_content = "후훗, 정말로 아직 이 근처에 있었네.",
  ui_story_5040_50401401_96_dialog_content = "<size=45>캬오오오──!</size>",
  ui_story_5040_50401401_97_dialog_content = "뭔가가 샌드버그를 따라 땅에서 튀어나왔어요! 저건... 세이블?!",
  ui_story_5040_50401401_98_dialog_content = "절대, 가게, 안 둬!",
  ui_story_5040_50401401_99_dialog_content = "세이블?! 저 모습은...",
  ui_story_5040_50401401_100_dialog_content = "세이블이 암귀든 뭐든, 지금도 여전히 우리 편이에요.",
  ui_story_5040_50401401_101_dialog_content = "PlayerName 씨, 세이블을 도와주세요!",
  ui_story_5040_50401401_102_dialog_content = "......",
  ui_story_5040_50401401_103_dialog_content = "알겠어! 세이블을 도울게!",
  ui_story_5040_50401401_104_dialog_content = "준비됐니, 아이테르 군? 이제 저 분홍색 골칫덩이를 해결해 보자.",
  ui_story_5040_50401401_105_dialog_content = "괜찮은 거예요? 쉴 틈도 거의 없이 계속 싸웠고, 루미나도 많이 소모했잖아요.",
  ui_story_5040_50401401_106_dialog_content = "후훗, 아이테르 군은 세심하네.",
  ui_story_5040_50401401_107_dialog_content = "걱정 안 해도 돼. 차 타고 여기 오면서 루미나를 조금 회복해 뒀거든.",
  ui_story_5040_50401401_108_dialog_content = "자, 가자.",
  ui_story_5040_50401401_109_dialog_content = "네, 그럼 얼른 세이블을 도우러 가요!",
  ui_story_5040_50401402_1_dialog_content = "내 기억은 이미 무척 흐릿해졌다.",
  ui_story_5040_50401402_2_dialog_content = "기억들은 마치 조각난 필름처럼 내 머릿속에서 떠올랐다, 사라졌다 하다가,\n가끔은 단편적인 화면이 뇌리를 스쳐 지나가기도 했다.",
  ui_story_5040_50401402_3_dialog_content = "기억의 첫 조각은 드넓은 사막에 관한 것이었다.\n나는 그곳에서 태어났고, 그곳에서 자랐었다...",
  ui_story_5040_50401402_4_dialog_content = "쿠리어 씨가 그 편지를 가져다주기 전까지,\n나는 내가 여느 사람 중에서도 가장 평범한 편이라고 생각했다.",
  ui_story_5040_50401402_5_dialog_content = "그 편지를 통해, 나는 사막 밖에 존재하는 유난히 아름다운 세상을 알게 됐고,\n「그 사람」을 알게 됐다.",
  ui_story_5040_50401402_6_dialog_content = "그 사람의 이름은 이미 오래전에 잊어버렸다.\n하지만 그 사람과 편지를 주고받으면서 깊어졌던 내 마음은 여전히 기억이 난다.",
  ui_story_5040_50401402_7_dialog_content = "그래서 편지로 그 사람한테 내 마음을 전하고, 그 사람이 내 마음을 받아 주었을 때...",
  ui_story_5040_50401402_8_dialog_content = "내 마음은 기쁨으로 가득 차, 마치 터질 듯 쿵쾅댔었다.",
  ui_story_5040_50401402_9_dialog_content = "그리고 바로 그때부터, 그 사람이 내게 답장하는 횟수가 점차 줄어들기 시작했다.",
  ui_story_5040_50401402_10_dialog_content = "나는 내가 보내는 편지에 정성이 부족했다고 생각했고,\n그래서 편지를 보낼 때 선물을 함께 보내기 시작했다.",
  ui_story_5040_50401402_11_dialog_content = "맨 처음 보낸 선물은 사막에서는 찾아보기 힘든 생화와 고대의 유물이었다.",
  ui_story_5040_50401402_12_dialog_content = "시간이 갈수록 편지에 동봉하는 선물의 수가 늘어났고, 더 값비싸졌으며,\n결국에는 나이티움을 보내게 되었다.",
  ui_story_5040_50401402_13_dialog_content = "내가 아무리 애를 써도 그 사람한테서 답장이 오는 횟수는 계속 줄어들었고,\n답장도 점차 선물을 더 많이 보내달라는 내용으로 변해갔다.",
  ui_story_5040_50401402_14_dialog_content = "나는 그 사람이 왜 변했는지 이해할 수 없었지만, 그 사람을 의심하기는커녕,\n오히려 그 사람을 만나고 싶었다. 그러자, 그 사람은 편지로 어떤 장소를 하나 알려줬다.",
  ui_story_5040_50401402_15_dialog_content = "나는 용기를 내, 처음으로 사막을 떠났다.",
  ui_story_5040_50401402_16_dialog_content = "그 사람이 보낸 편지에서 시키는 대로, 나는 일루미나로 향했다...",
  ui_story_5040_50401402_17_dialog_content = "그리고 백야성에도 갔고...",
  ui_story_5040_50401402_18_dialog_content = "마지막에는 거울 호수 근처에 오게 되었다.",
  ui_story_5040_50401402_19_dialog_content = "그 사람은 북방에서 나를 위해 성대한 결혼식을 준비하고 있다고 했다.",
  ui_story_5040_50401402_20_dialog_content = "하지만 그 어디에서도 그 사람의 모습을 찾을 순 없었다.",
  ui_story_5040_50401402_21_dialog_content = "이제 어디로 가야 할지, 집으로 돌아갈 수는 있을지,\n아무것도 알 수 없게 된 나는 절망에 빠져 울음을 터트렸다.",
  ui_story_5040_50401402_22_dialog_content = "그리고 그때, 누군가 내게 말을 걸었다...",
  ui_story_5040_50401402_23_dialog_content = "이 「씨앗」을 받아. 그럼 네 소망을 이룰 힘을 얻게 될 거야.",
  ui_story_5040_50401402_24_dialog_content = "나는 그 「씨앗」에 모든 희망을 걸었지만, 그로 인해 오히려 모든 걸 잃게 될 줄은 몰랐다.",
  ui_story_5040_50401402_25_dialog_content = "나는 기억도, 사고하는 능력도 잃은 채, 들짐승 같은 괴물로 전락해 이곳저곳을 떠돌았다...",
  ui_story_5040_50401402_26_dialog_content = "그러다 아도니스와 타라를 보게 되었고, 나는 서로를 위해 행동하는 두 사람을 통해\n이 세상에 저런 사랑이 있다는 사실을 깨달았다.",
  ui_story_5040_50401402_27_dialog_content = "그리고 책임감 있고, 약속을 꼭 지키려 하는 키아를 만났다.",
  ui_story_5040_50401402_28_dialog_content = "다른 사람에게 무심한 것처럼 보이지만, 사실은 무척이나 믿음직한 예리아 씨도 알게 되었다.",
  ui_story_5040_50401402_29_dialog_content = "그리고 그녀를 통해 나는 자유를 보았다.",
  ui_story_5040_50401402_30_dialog_content = "이제 내가 할 수 있는 건 한 가지뿐이다.",
  ui_story_5040_50401402_31_dialog_content = "절대, 가게, 두지... 않아!",
  ui_story_5040_50401402_32_dialog_content = "<size=45>그오오오──!</size>",
  ui_story_5040_50401402_33_dialog_content = "으으윽──!",
  ui_story_5040_50401402_34_dialog_content = "세이블!",
  ui_story_5040_50401402_35_dialog_content = "녀석이 세이블을 삼키려고 해요! 예리아 장로님, 녀석의 머리를 공격해 주세요!\n녀석이 다른 데 집중하게 만들어야 해요!",
  ui_story_5040_50401402_36_dialog_content = "나, 신경, 쓰지 마!",
  ui_story_5040_50401402_37_dialog_content = "약점, 놓치면, 안 돼!",
  ui_story_5040_50401402_38_dialog_content = "......",
  ui_story_5040_50401402_39_dialog_content = "알겠어.",
  ui_story_5040_50401402_40_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5040_50401402_41_dialog_content = "끼에에엑...",
  ui_story_5040_50401402_42_dialog_content = "크윽!",
  ui_story_5040_50401402_43_dialog_content = "(샌드버그를 쓰러트렸어...)",
  ui_story_5040_50401402_44_dialog_content = "(예리아 씨가 루미나틱스로 샌드버그가 전에 입었던 상처를 정확히 노려서,\n거길 꿰뚫은 덕분이야.)",
  ui_story_5040_50401402_45_dialog_content = "(하지만 세이블이 샌드버그한테 심하게 물린 데다가, 집어던져지기까지 했어...)",
  ui_story_5040_50401402_46_dialog_content = "세이블! 괜찮아요?!",
  ui_story_5040_50401402_47_dialog_content = "아...파...",
  ui_story_5040_50401402_48_dialog_content = "세이블, 세이블! 정신 차려요!",
  ui_story_5040_50401402_49_dialog_content = "상처가 너무 깊어요!",
  ui_story_5040_50401402_50_dialog_content = "생명력이 강한 암귀라고 해도, 이 정도 상처라면...",
  ui_story_5040_50401402_51_dialog_content = "제가 루미나틱스로 치료해 보겠습니다!",
  ui_story_5040_50401402_52_dialog_content = "...이런... 전혀 효과가 없어요...",
  ui_story_5040_50401402_53_dialog_content = "소용없어. 네 루미나틱스로 치료할 수 있는 상처가 아니야...",
  ui_story_5040_50401402_54_dialog_content = "예리아 장로님! 왜 세이블을 안 구해주신 거죠?!",
  ui_story_5040_50401402_55_dialog_content = "난 세이블의 부탁을 들어줬을 뿐이야.",
  ui_story_5040_50401402_56_dialog_content = "키아 너도 알고 있잖니. 조금 전에 내가 세이블을 구했더라도,\n이제 곧 세이블은 자아가 없는 암귀로 변해 버렸을 거란 걸.",
  ui_story_5040_50401402_57_dialog_content = "......",
  ui_story_5040_50401402_58_dialog_content = "키아...",
  ui_story_5040_50401402_59_dialog_content = "세이블, 저 여기 있어요!",
  ui_story_5040_50401402_60_dialog_content = "예리아 씨, 탓, 하지...마.",
  ui_story_5040_50401402_61_dialog_content = "내가... 너흴... 해칠까... 무서워. 그래서... 떠났어.\n근데... 샌드버그... 만났어...",
  ui_story_5040_50401402_62_dialog_content = "마지막에... 너... 모두... 만날 수 있어서...",
  ui_story_5040_50401402_63_dialog_content = "내가... 오로리안...이었던... 기억... 해내서...",
  ui_story_5040_50401402_64_dialog_content = "나... 기뻐.",
  ui_story_5040_50401402_65_dialog_content = "하지만 전 아직 당신 의뢰를 완수하지 못했어요! 같이 집으로 돌아가야죠!",
  ui_story_5040_50401402_66_dialog_content = "그럼... 의뢰... 바꿀래.",
  ui_story_5040_50401402_67_dialog_content = "이거... 우리 집에... 줘...",
  ui_story_5040_50401402_68_dialog_content = "...가족...한테... 미안하다고... 전해... 줘...",
  ui_story_5040_50401402_69_dialog_content = "......",
  ui_story_5040_50401402_70_dialog_content = "쿠리어 길드의 쿠리어 키아, 의뢰를 접수했습니다...",
  ui_story_5040_50401402_71_dialog_content = "쿠리어 길드, 사명은 반드시 완수합니다!",
  ui_story_5040_50401402_72_dialog_content = "그럼... 부탁, 할게.",
  ui_story_5040_50401402_73_dialog_content = "세이블... 흑흑...",
  ui_story_5040_50401402_74_dialog_content = "키아...",
  ui_story_5040_50401402_75_dialog_content = "저, 전 가서 휴지 좀 가져올게요.",
  ui_story_5040_50401402_76_dialog_content = "......",
  ui_story_5040_50401402_77_dialog_content = "울어도 돼. 원하는 만큼 울어.",
  ui_story_5040_50401402_78_dialog_content = "그리고 이 아픔을 이겨내고 성장하렴.",
  ui_story_5040_50401402_79_dialog_content = "예리아 씨...?",
  ui_story_5040_50401402_80_dialog_content = "괜찮으세요? 갑자기 자리를 떠나시길래 무슨 일인가 해서요.",
  ui_story_5040_50401402_81_dialog_content = "아무리 나라도 마음을 추스를 시간이 조금은 필요한 법이야, 아이테르 군.",
  ui_story_5040_50401402_82_dialog_content = "아, 죄송해요. 자꾸 무의식적으로 예리아 씨는 어떤 상황에서도\n담담할 거라고 생각하게 돼서요...",
  ui_story_5040_50401402_83_dialog_content = "후훗, 칭찬 고마워, 아이테르 군.",
  ui_story_5040_50401402_84_dialog_content = "사실 있지. 난 한참 전부터 세이블의 여행이 길진 않을 거라고 예상했었어.",
  ui_story_5040_50401402_85_dialog_content = "예전처럼 남의 일처럼 지켜보기만 할 수 있을 줄 알았는데, 이번에는 그게 잘 안됐네.",
  ui_story_5040_50401402_86_dialog_content = "진작부터 세이블의 정체를 알고 계셨다고요? 근데 왜 아무 말도 안 하셨어요?",
  ui_story_5040_50401402_87_dialog_content = "내가 모두한테 그걸 얘기해 줘야 할 이유가 있니?",
  ui_story_5040_50401402_88_dialog_content = "음... 저랑 다른 사람들한테 알려주셨으면 뭔가 도움이 됐을지도 모르잖아요.",
  ui_story_5040_50401402_89_dialog_content = "타라 씨랑 아도니스 씨라면 그 사실을 알았어도 세이블을 거부하진 않았을 거예요.",
  ui_story_5040_50401402_90_dialog_content = "그 둘은 확실히 그렇겠지. 하지만 다른 사람들은?",
  ui_story_5040_50401402_91_dialog_content = "비밀이란 건 아는 사람이 많아질수록 새어 나가기 쉬운 법이야.",
  ui_story_5040_50401402_92_dialog_content = "더군다나 이 세상에는 암귀라면 이를 가는 사람들이 많아.",
  ui_story_5040_50401402_93_dialog_content = "게다가 그 아기새는 이미 폭풍 속으로 너무 깊이 날아가서,\n더는 돌이킬 수 없는 상황이었어.",
  ui_story_5040_50401402_94_dialog_content = "그러니 비밀이 드러났다면, 소중한 「마지막 여행」에\n불필요한 번거로움이 생겼을지도 모르지.",
  ui_story_5040_50401402_95_dialog_content = "그것도 그렇네요...",
  ui_story_5040_50401402_96_dialog_content = "그러니까 아이테르 군, 이거 하나는 제대로 알아 둬.",
  ui_story_5040_50401402_97_dialog_content = "인간관계는 중요해.\n하지만 아는 사람이 많을수록, 서로 허물없이 가까운 게 무작정 좋은 건 아니야.",
  ui_story_5040_50401402_98_dialog_content = "서로가 어느 정도 거리를 유지하고, 비밀을 어느 정도는 가지고 있는 편이\n나을 때가 더 많거든.",
  ui_story_5040_50401402_99_dialog_content = "인간관계는 네가 날아오를 수 있도록 뒷받침해 주는 바람이 되어야지,\n네가 가진 날개를 얽매는 그물이 돼서는 안 돼.",
  ui_story_5040_50401402_100_dialog_content = "알겠어요...",
  ui_story_5040_50401402_101_dialog_content = "예리아 장로님, 저 왔어요.",
  ui_story_5040_50401402_102_dialog_content = "너무 오래 울어 버렸네요. 폐를 끼쳐서 죄송해요...",
  ui_story_5040_50401402_103_dialog_content = "폐는 무슨! 감정은 꽁꽁 싸매 두면 안 되는 거야.\n표현해 줘야 할 땐 표현해 주는 게 훨씬 좋다구.",
  ui_story_5040_50401402_104_dialog_content = "타라 말이 맞아요.",
  ui_story_5040_50401402_105_dialog_content = "결의를 다진 모양이구나, 키아.",
  ui_story_5040_50401402_106_dialog_content = "네. 세이블이 제게 이 우표를 자기 고향에 가져다 달라고 의뢰했어요.\n전 그 사명을 완수해야 하니까, 이제 더는 울지 않을 거예요.",
  ui_story_5040_50401402_107_dialog_content = "지금 당장은 세이블의 고향을 찾을 순 없지만,\n이번 일이 끝나고 나면 레디젤 렌치 지부로 전근 신청을 할 거예요.",
  ui_story_5040_50401402_108_dialog_content = "일을 하면서 사막 환경에 익숙해진다면, 언젠가는 세이블의 고향을 찾을 수 있을 테니까요.",
  ui_story_5040_50401402_109_dialog_content = "이 사막을 전부 다 뒤져야 한다고 해도, 절대로 포기하지 않을 거예요.",
  ui_story_5040_50401402_110_dialog_content = "아무리 먼 길을 가야 한다 하더라도, 목표가 있는 새는 굳세게 버틸 수 있어. 그렇지?",
  ui_story_5040_50401402_111_dialog_content = "네!",
  ui_story_5040_50401402_112_dialog_content = "그나저나 너희 둘은 어떻게 할 거야?",
  ui_story_5040_50401402_113_dialog_content = "난 이미 내가 진심으로 아도니스를 사랑하고 있단 걸 다시 한번 확인했어.",
  ui_story_5040_50401402_114_dialog_content = "그러니깐 이제 시련 같은 거 없이도 이 사랑을 증명할 수 있어.",
  ui_story_5040_50401402_115_dialog_content = "저도 북방 밖의 세상은 위험하지만, 제가 생각했던 것만큼 무섭진 않다는 걸 알았습니다.",
  ui_story_5040_50401402_116_dialog_content = "예전의 제가 두려워했던 건 북방 밖의 세상이 아니라, 제가 알지 못하는 세상이었어요.",
  ui_story_5040_50401402_117_dialog_content = "하지만 이젠 타라 덕분에 그 두려움을 이겨냈습니다.",
  ui_story_5040_50401402_118_dialog_content = "나도 이제 다시는 아도니스한테 억지로 무리한 일 안 시킬 거야.",
  ui_story_5040_50401402_119_dialog_content = "이 순간이 오기까지 참 많은 일들이 있었네.\n위험한 일들도 많이 겪었고, 후회가 남은 일도 몇 가지 있었지만...",
  ui_story_5040_50401402_120_dialog_content = "그래도 결국에는 두 사람이 서로를 이해하게 돼서 다행이야.",
  ui_story_5040_50401402_121_dialog_content = "불행 중 다행이라고 해야겠지.",
  ui_story_5040_50401402_122_dialog_content = "근데, 타라, 아도니스가 비늘을 손에 넣지 못해서 시련에 실패해 버리면 어쩔 작정이었어?",
  ui_story_5040_50401402_123_dialog_content = "계속 기억상실인 척하려고 했던 건 아니지?",
  ui_story_5040_50401402_124_dialog_content = "그건...",
  ui_story_5040_50401402_125_dialog_content = "너라면 틀림없이 대책을 준비해 뒀을 텐데?",
  ui_story_5040_50401402_126_dialog_content = "음, 역시 예리아 넌 못 속이겠다니까.",
  ui_story_5040_50401402_127_dialog_content = "비늘이 하나 더 있었네?!",
  ui_story_5040_50401402_128_dialog_content = "이건 사메야마 대장이 손에 넣었다고 했던 그 비늘이야.\n내가 경매에서 거금을 주고 사 뒀고.",
  ui_story_5040_50401402_129_dialog_content = "타, 타라 네가 샀단 거야?!",
  ui_story_5040_50401402_130_dialog_content = "어쩐지, 영매가 말했던 재료는 타라 네가 가지고 있었으니까,\n보자마자 그 마법약이 가짜란 걸 안 거구나.",
  ui_story_5040_50401402_131_dialog_content = "솔직히 재료 같은 거 안 가지고 있어도,\n「만능 마법약」이라는 이름에서 거짓말일 거라는 느낌이 팍팍 오잖아.",
  ui_story_5040_50401402_132_dialog_content = "그런 거짓말에 속을 사람은 너처럼 충동적이고 단순한 사람밖에 없을걸, 아도니스.",
  ui_story_5040_50401402_133_dialog_content = "나, 난... 으음...",
  ui_story_5040_50401402_134_dialog_content = "처음에 기억상실증 연기를 하려고 마음먹었을 때부터,\n혹시라도 이런 일이 생기지 않을까 싶긴 했었어.",
  ui_story_5040_50401402_135_dialog_content = "그래서 만약 아도니스가 시련에 실패하면...",
  ui_story_5040_50401402_135X1_dialog_content = "난 예리아한테 이 비늘을 주고, 우리가 「다른 방법」으로 이 비늘을\n얻을 수 있게 해 달라고 부탁할 생각이었어.",
  ui_story_5040_50401402_136_dialog_content = "그랬구나. 근데 애초에 왜 분홍색 샌드버그의 비늘을 고른 거야?",
  ui_story_5040_50401402_137_dialog_content = "......!",
  ui_story_5040_50401402_138_dialog_content = "희귀한 샌드버그의 비늘이잖아. 게다가 분홍색이기도 하고...",
  ui_story_5040_50401402_139_dialog_content = "새롭고 신기해서 아도니스한테도 알려주고 싶었거든.\n그래서 충동적으로 이 비늘을 사 버렸어.",
  ui_story_5040_50401402_140_dialog_content = "그리고 원래는 기술자한테 이 비늘을 결혼반지로 만들어 달라고 해서,\n아도니스한테 줄 생각이었어.",
  ui_story_5040_50401402_141_dialog_content = "어머? 그건 꽤 독특하고 신선한 발상인걸.\n샌드버그가 이렇게 예쁜 분홍색 비늘을 가지고 있던 보람이 있네.",
  ui_story_5040_50401402_142_dialog_content = "근데 그 비늘, 반지로 만들 만큼 단단한 건 정중앙 쪽 한 조각뿐이잖아?\n비늘 하나로 반지는 기껏해야 하나밖에 못 만들 텐데?",
  ui_story_5040_50401402_143_dialog_content = "만약 이번에 샌드버그를 못 잡아서 반지도 아도니스 것만 만들었으면,\n네 반지는 어쩔 생각이었어?",
  ui_story_5040_50401402_144_dialog_content = "그건... 솔직히 생각 안 해 봤어.",
  ui_story_5040_50401402_145_dialog_content = "근데 그래도 별로 상관은 없었을 거야. 대충 아무 재료나 가져다 만들면 되니까.",
  ui_story_5040_50401402_146_dialog_content = "타라, 넌 처음 만났을 때도, 그리고 지금도 자기 자신한테는 너무 무신경해. 그러면 안 돼.",
  ui_story_5040_50401402_147_dialog_content = "결혼반지는 따로따로인 것보다 한 쌍인 게 좋아. 게다가...",
  ui_story_5040_50401402_148_dialog_content = "이제 우리한텐 분홍색 비늘이 이렇게나 많은걸.",
  ui_story_5040_50401402_149_dialog_content = "<color=#e8d9bb>끼이익──</color>",
  ui_story_5040_50401402_150_dialog_content = "샌드버그는? 샌드버그는 어디 있어?",
  ui_story_5040_50401402_151_dialog_content = "렉커, 일단 진정해. 저기 좀 봐.",
  ui_story_5040_50401402_152_dialog_content = "진짜 분홍색 샌드버그잖아! 근데 왜 안 움직이지...?",
  ui_story_5040_50401402_153_dialog_content = "죽은 거 아냐?!",
  ui_story_5040_50401402_154_dialog_content = "플뢰르? 렉커? 너희가 여긴 웬일이야?",
  ui_story_5040_50401402_155_dialog_content = "아, PlayerName, 무사해서 다행이야.",
  ui_story_5040_50401402_156_dialog_content = "사메야마 대장한테 너희가 분홍색 샌드버그를 찾고 있단 얘길 들었거든.\n걱정이 돼서 와 봤어.",
  ui_story_5040_50401402_157_dialog_content = "도와주려고 온 건데, 상황을 보니까 벌써 끝난 것 같네.",
  ui_story_5040_50401402_158_dialog_content = "어머, 레디젤 렌치에도 꽤 친절한 녀석이 있구나. 근데... 아쉽지만 너무 늦었어.",
  ui_story_5040_50401402_159_dialog_content = "그렇네요... 다음에 도움이 필요할 때가 생기면, 그땐 최대한 빨리 오도록 할게요.",
  ui_story_5040_50401402_160_dialog_content = "다들 알아서 문제를 해결한 것 같으니까, 우린 이만 가 볼게.",
  ui_story_5040_50401402_161_dialog_content = "이번엔 선수를 뺏겼지만, 다음엔 반드시 내가 먼저 저 샌드버그보다\n더 강한 녀석을 사냥해 주겠어.",
  ui_story_5040_50401402_162_dialog_content = "근데 그 커다란 샌드버그를 어떻게 처리할 생각이야? 좀 도와줄까?\n그 분홍색 비늘들은 팔면 값이 꽤 나갈걸?",
  ui_story_5040_50401402_163_dialog_content = "저건 키아의 소중한 친구가 목숨과 맞바꿔 손에 넣은 거야.\n멋대로 너희들한테 넘겨줄 순 없어.",
  ui_story_5040_50401402_164_dialog_content = "적어도 키아한테 어떻게 할 건지 물어는 봐야지.",
  ui_story_5040_50401402_165_dialog_content = "...전 딱히 저 샌드버그를 어떻게 하고 싶단 생각은 없어요.",
  ui_story_5040_50401402_166_dialog_content = "타라 씨랑 아도니스 씨가 반지를 만들 수 있을 만큼만 비늘을 남겨 주면,\n나머지는 알아서 처리하셔도 돼요.",
  ui_story_5040_50401402_167_dialog_content = "세이블도 아마 그걸 바랄 거예요.",
  ui_story_5040_50401402_168_dialog_content = "무슨 일이 있었던 건진 모르겠지만, 너무 슬퍼하진 않았으면 좋겠어.",
  ui_story_5040_50401402_169_dialog_content = "그럼 저 샌드버그는 우리가 잘 쓸게. 절대 낭비 안 할 거라고.",
  ui_story_5040_50401402_170_dialog_content = "우린 사람들을 모으러 가 볼게.\n저 정도 크기의 샌드버그를 처리하려면 사람이 꽤 많이 필요할 것 같거든.",
  ui_story_5040_50401402_171_dialog_content = "다음에 또 보자, PlayerName.",
  ui_story_5040_50401402_172_dialog_content = "응, 다음에 봐!",
  ui_story_5040_50401402_173_dialog_content = "정말 바쁜 하루였네. 힘들게 싸운 끝에 분홍색 샌드버그도 쓰러트렸고.",
  ui_story_5040_50401402_174_dialog_content = "어쨌든 아도니스도 정식으로 마지막 시련을 통과한 셈이잖아.",
  ui_story_5040_50401402_175_dialog_content = "세이블의 일은 가슴 아프지만...",
  ui_story_5040_50401402_176_dialog_content = "이번엔 드디어 아도니스의 마음을 확실히 알 수 있었어.",
  ui_story_5040_50401402_177_dialog_content = "나도 타라 널 더 이해할 수 있었어. 그리고 북방 밖의 세상을 마주할 용기도 생겼고.",
  ui_story_5040_50401402_178_dialog_content = "다들 수확이 있었으니까, 이제 마지막 단계를 진행해야겠네.\n자, 내가 두 사람한테 도장을 찍어 줄게.",
  ui_story_5040_50401402_179_dialog_content = "<color=#e8d9bb>꾸욱</color>",
  ui_story_5040_50401402_180_dialog_content = "축하해.",
  ui_story_5040_50401402_181_dialog_content = "축하드려요!",
  ui_story_5040_50401402_182_option_content = "축하해!",
  ui_story_5040_50401402_183_dialog_content = "고마워!",
  ui_story_5040_50401402_184_dialog_content = "모두 감사합니다!",
  ui_story_5040_50401402_185_dialog_content = "여러분의 도움이 없었다면 전 아직도 북방에 틀어박혀서\n바깥세상으로 나올 엄두도 못 냈을 거예요.",
  ui_story_5040_50401402_186_dialog_content = "하지만 이젠 그 두려움을 이겨냈잖아.",
  ui_story_5040_50401402_187_dialog_content = "맞아. 이제야 드디어 계속 네 곁에 있어 줄 용기가 생겼어.",
  ui_story_5040_50401402_188_dialog_content = "크흠... 딱히 방해하고 싶진 않지만, 깨가 쏟아지기 전에 너희 아직 해야 할 일이 있는걸.",
  ui_story_5040_50401402_189_dialog_content = "......!",
  ui_story_5040_50401402_190_dialog_content = "그렇네요! 가장 중요한 문제가 아직 남아있어요!",
  ui_story_5040_50401402_191_dialog_content = "좋아, 우리 아기새들이 드디어 가장 심각한 문제가 있단 사실을 깨달은 모양이구나.",
  ui_story_5040_50401402_192_dialog_content = "어? 아직 뭐가 더 남았어요?",
  ui_story_5040_50401402_193_dialog_content = "그거야 당연히...",
  ui_story_5040_50401402_194_dialog_content = "결혼식이지!\n결혼식이죠!",
  ui_story_5040_50401501_1_dialog_content = "<color=#e8d9bb>며칠 뒤, 북방</color>",
  ui_story_5040_50401501_2_dialog_content = "아도니스 씨랑 타라 씨가 많이 늦네...",
  ui_story_5040_50401501_3_dialog_content = "으엣취──!",
  ui_story_5040_50401501_4_dialog_content = "추워... 여기서 얼마나 더 기다려야 돼요?",
  ui_story_5040_50401501_5_dialog_content = "아이테르 군은 정말 참을성이 없구나.\n중요한 의식이니만큼 두 사람한테 충분히 준비할 시간을 줘야지.",
  ui_story_5040_50401501_6_dialog_content = "으, 알겠어요.",
  ui_story_5040_50401501_7_dialog_content = "근데 갑자기 생각난 건데, 여기가 혹시 전에 아도니스 씨가 준비했다던 그 결혼식장은 아니죠...?",
  ui_story_5040_50401501_8_dialog_content = "당연히 아니지.",
  ui_story_5040_50401501_9_dialog_content = "이번엔 몰래 도망칠 필요도 없으니까, 당당하게 결혼식을 치러야지.",
  ui_story_5040_50401501_10_dialog_content = "혹시... 아이테르 군은 그런 배덕감을 더 좋아하는 거니?",
  ui_story_5040_50401501_11_dialog_content = "지금이 더 좋아요! 친구들이랑 가족들한테 축복을 받는 게 더 좋죠!",
  ui_story_5040_50401501_12_dialog_content = "PlayerName 님?",
  ui_story_5040_50401501_13_dialog_content = "이런 곳에서 뵙게 될 줄은 몰랐네요.",
  ui_story_5040_50401501_14_dialog_content = "아, 노비오 씨도 결혼식에 오신 건가요?",
  ui_story_5040_50401501_15_dialog_content = "그렇습니다. 결혼식에 참석해 달라는 아도니스의 초대를 받았습니다.",
  ui_story_5040_50401501_16_dialog_content = "아도니스는 제 학생입니다. 그러니 아도니스에게 윈터 팰리스의 축복을 전해야지요.",
  ui_story_5040_50401501_17_dialog_content = "아, 그랬죠. 전에 아도니스 씨의 부모님이랑 나로세르도 얘기했거든요.",
  ui_story_5040_50401501_18_dialog_content = "아도니스는 조심스럽고 내향적인 성격이라 지금까지는 북방을 떠난 적이 없었답니다.",
  ui_story_5040_50401501_19_dialog_content = "그래서 아도니스가 레디젤 렌치 출신의 타라 양과 결혼하려고 한다는\n이야기를 들었을 때는 저도 무척 뜻밖이었습니다.",
  ui_story_5040_50401501_20_dialog_content = "하지만 더 많은 북방인이 바깥세상과 교류하며 견문을 넓히는 모습을 보신다면,\n여왕 폐하께서도 분명 기뻐하시겠지요.",
  ui_story_5040_50401501_21_dialog_content = "그렇겠죠!",
  ui_story_5040_50401501_22_dialog_content = "여왕 폐하께도 안부 좀 전해 주세요.",
  ui_story_5040_50401501_23_dialog_content = "물론입니다.",
  ui_story_5040_50401501_24_dialog_content = "전 아도니스와 타라 양에게 선물을 주어야 하니, 먼저 실례하겠습니다.",
  ui_story_5040_50401501_25_dialog_content = "네, 나중에 또 봐요!",
  ui_story_5040_50401501_26_dialog_content = "그럼 다음에 뵙겠습니다, PlayerName 님.",
  ui_story_5040_50401501_27_dialog_content = "그나저나 키아는 왜 아직 안 오는 걸까요?",
  ui_story_5040_50401501_28_dialog_content = "움브라톤을 지날 때쯤에 갑자기 급한 일이 있다면서 빨리 내려 달라고 했거든요.",
  ui_story_5040_50401501_29_dialog_content = "무슨 일이냐고 물어봐도 정신이 없어서 못 들은 건지 대답도 안 해 주고,\n심지어는 콜로서스가 완전히 멈추기도 전에 뛰어내려 버렸어요.",
  ui_story_5040_50401501_30_dialog_content = "설마 타라 씨랑 아도니스 씨 결혼식에 안 오는 건 아니겠죠?",
  ui_story_5040_50401501_31_dialog_content = "키아는 약속은 반드시 지키는 아기새인걸.",
  ui_story_5040_50401501_32_dialog_content = "드디어 도착했네요! 아슬아슬했어요!",
  ui_story_5040_50401501_33_dialog_content = "휴, 휴우, 안 늦어서 정말 다행이에요!",
  ui_story_5040_50401501_34_dialog_content = "키아?! 엄청 급하게 온 모양이네...",
  ui_story_5040_50401501_35_dialog_content = "물부터 마시고 조금 쉬고 있으렴. 이제 곧 결혼식이 시작될 거야.",
  ui_story_5040_50401501_36_dialog_content = "감사해요, 예리아 장로님...",
  ui_story_5040_50401501_37_dialog_content = "<color=#e8d9bb>꿀꺽, 꿀꺽...</color>",
  ui_story_5040_50401501_38_dialog_content = "휴우... 늦지 않게 도착해서 정말 다행이에요. 늦었으면 정말 큰 실례였겠죠.",
  ui_story_5040_50401501_39_dialog_content = "며칠 동안 어딜 그렇게 바쁘게 돌아다녔어?",
  ui_story_5040_50401501_40_dialog_content = "참, PlayerName 씨한텐 아직 말을 안 했었네요.",
  ui_story_5040_50401501_41_dialog_content = "타라 씨랑 아도니스 씨가 저한테 그때 그 샌드버그 비늘 두 개를 주고,\n기술자한테 맡겨서 반지로 만들어 달라고 했었거든요.",
  ui_story_5040_50401501_42_dialog_content = "자, 바로 이거예요!",
  ui_story_5040_50401501_43_dialog_content = "진짜 예쁘네! 재료가 샌드버그의 비늘일 거라곤 전혀 모르겠는데?",
  ui_story_5040_50401501_44_dialog_content = "반지를 만드는 데 예상보다 시간이 조금 많이 걸렸어요.",
  ui_story_5040_50401501_45_dialog_content = "만약 에메랄드 선생님이 남겨주신 노트에 지름길이 안 나와 있었으면,\n꼼짝없이 결혼식에 지각했을 거예요.",
  ui_story_5040_50401501_46_dialog_content = "어머, 어떤 지름길인데? 나는 왜 모르겠지?",
  ui_story_5040_50401501_47_dialog_content = "당연히 날아서 이동하는 거죠!\n북방행 마차에 제때 타려고 한참을 쉬지도 않고 날았어요!",
  ui_story_5040_50401501_48_dialog_content = "덕분에 날개가 지금까지 아프다구요!",
  ui_story_5040_50401501_49_dialog_content = "키아, 그거 모르니? 긴급 우편물을 접수한 쿠리어는 움브라톤 쿠리어 길드에\n신청만 하면 길드에서 대신 교통수단을 준비해 주는걸.",
  ui_story_5040_50401501_50_dialog_content = "네?!",
  ui_story_5040_50401501_51_dialog_content = "그런 게 있는 줄도 몰랐어요!\n에메랄드 선생님의 노트에도 그런 건 안 적혀 있었단 말이에요...",
  ui_story_5040_50401501_52_dialog_content = "얼마 전 움브라톤 지부에서 새로 내놓은 서비스거든.\n그러니까 은퇴한 대선배의 노트엔 안 적혀 있겠지.",
  ui_story_5040_50401501_53_dialog_content = "으... 아무래도 지부에서 어떤 일들을 하는지 이참에 좀 더 알아둬야 할 것 같네요.",
  ui_story_5040_50401501_54_dialog_content = "시간 맞춰 온 것만 해도 대단한 거야.\n조금 있으면 결혼식이 시작될 테니까, 일단은 좀 쉬어.",
  ui_story_5040_50401501_55_dialog_content = "네!",
  ui_story_5040_50401501_56_dialog_content = "제가 없는 며칠 동안 다들 준비는 순조롭게 끝내셨나요?",
  ui_story_5040_50401501_57_dialog_content = "특히 자기가 영매라고 했던 사기꾼한테 앞으론 사람들을 속이지 말라고\n제대로 이야기해 주신 거죠?",
  ui_story_5040_50401501_58_dialog_content = "후훗, 물론이지.",
  ui_story_5040_50401501_59_dialog_content = "우린 돌아오자마자 바로 그 사기꾼을 찾아가서...",
  ui_story_5040_50401501_60_dialog_content = "바로 저 사람입니다! 저 사람이 그 영매예요!",
  ui_story_5040_50401501_61_dialog_content = "어...?! 서, 선생님, 무슨 일로 이러십니까?",
  ui_story_5040_50401501_62_dialog_content = "며칠 전에 그쪽한테 「만능 마법약」이란 걸 샀는데, 그 마법약은 가짜더군요.",
  ui_story_5040_50401501_63_dialog_content = "아! 기억났어. 누군가 했네.",
  ui_story_5040_50401501_64_dialog_content = "근데 말은 바로 해야지! 내 마법약은 진짜 재료로 만든 거고, 효과도 확실하다고!",
  ui_story_5040_50401501_65_dialog_content = "분홍색 샌드버그의 비늘로 만든 거니까!",
  ui_story_5040_50401501_66_dialog_content = "전에 나한테 와서 내 마법약 때문에 약혼녀가 기억을 잃어버렸다고 하지 않았었나?",
  ui_story_5040_50401501_67_dialog_content = "내가 바로 이 사람 약혼녀야. 그리고 기억을 잃었다는 건 다 거짓말이었고.\n당신 마법약은 효과가 하나도 없었어.",
  ui_story_5040_50401501_68_dialog_content = "그리고 안에 분홍색 샌드버그의 비늘 같은 건 넣지도 않았잖아!",
  ui_story_5040_50401501_69_dialog_content = "즈, 증거 있어? 증거 있냐고!",
  ui_story_5040_50401501_70_dialog_content = "일단 들어나 보자. 마법약에 썼다는 비늘, 당신 그거 어디서 났어?",
  ui_story_5040_50401501_71_dialog_content = "어, 얼마 전에 있었던 경매에서 산 거야.\n이 아스트라 대륙에 딱 하나밖에 없는 비늘이었다고.",
  ui_story_5040_50401501_72_dialog_content = "그래? 그거 신기하네. 나도 경매에서 분홍색 샌드버그의 비늘을 하나 샀거든.",
  ui_story_5040_50401501_73_dialog_content = "뭐야?!",
  ui_story_5040_50401501_74_dialog_content = "경매에서 낙찰받은 다음에 서명한 낙찰 증명서도 아직 가지고 있는데, 한번 볼래?",
  ui_story_5040_50401501_75_dialog_content = "샌드버그의 비늘을 고가에 낙찰받은 정체불명의 구매자가 누군가 했더니...\n당신이었어?!",
  ui_story_5040_50401501_76_dialog_content = "후훗, 별로 한 것도 없는데 싱겁게 인정해 버렸잖아.",
  ui_story_5040_50401501_77_dialog_content = "북방에서 사기꾼을 어떻게 처리하는진 잘 모르겠지만...",
  ui_story_5040_50401501_78_dialog_content = "레디젤 사막에서 사기꾼을 어떻게 처리하는지 알고 싶은 사람은 없을 거라고 생각해.",
  ui_story_5040_50401501_79_dialog_content = "윽... 말 안 해 주셔도 될 것 같아요...",
  ui_story_5040_50401501_80_dialog_content = "저, 정말 죄송합니다!",
  ui_story_5040_50401501_81_dialog_content = "돈은 지금 당장 돌려드리겠습니다! 그, 그리고 바로 가서 자수하겠습니다!",
  ui_story_5040_50401501_82_dialog_content = "잘 해결돼서 정말 다행이네요.",
  ui_story_5040_50401501_83_dialog_content = "근데 아도니스 씨의 부모님은 이 결혼에 동의하신 건가요?",
  ui_story_5040_50401501_84_dialog_content = "이번 일을 겪고 달라진 아도니스 씨의 모습을 보시더니, 별말 없으시더라고.",
  ui_story_5040_50401501_85_dialog_content = "흔쾌히 두 사람의 결혼을 허락해 주셨어!",
  ui_story_5040_50401501_86_dialog_content = "정말요?! 그것도 안 믿기는데요!",
  ui_story_5040_50401501_87_dialog_content = "전에는 타라 씨랑 사랑의 도피를 하겠다는 아도니스 씨를 호되게 꾸짖으셨잖아요.",
  ui_story_5040_50401501_88_dialog_content = "그건 키아 네가 두 분의 생각을 잘못 파악해서 그렇게 느낀 거야.",
  ui_story_5040_50401501_89_dialog_content = "쉽게 다른 사람을 파악할 수 있는 건 예리아 장로님만 가능한 일이 아닐까요...",
  ui_story_5040_50401501_90_dialog_content = "감응 능력으로 마음을 읽는다면 아이테르 군도 할 수 있을걸?",
  ui_story_5040_50401501_91_dialog_content = "전 감응 능력으로 멋대로 다른 사람의 생각을 읽지는 않는다구요.\n그건 무례한 짓이잖아요!",
  ui_story_5040_50401501_92_dialog_content = "다른 사람을 이해하려면 서로 소통을 해야죠.",
  ui_story_5040_50401501_93_dialog_content = "그럼 아도니스 씨의 부모님은 어떤 생각을 가지고 계셨는데요?",
  ui_story_5040_50401501_94_dialog_content = "사실 아주 단순해. 여느 평범한 가정의 부모님들과 똑같아.",
  ui_story_5040_50401501_95_dialog_content = "지금껏 북방을 떠나 본 적 없는 아들이 복잡한 환경에 적응하지 못할까 걱정이 많으셨지.",
  ui_story_5040_50401501_96_dialog_content = "그리고 그 걱정 때문에 아도니스가 북방을 떠나는 걸 반대하셨던 거야.",
  ui_story_5040_50401501_97_dialog_content = "그럼 걱정이 끝없이 계속되는 거잖아요!",
  ui_story_5040_50401501_98_dialog_content = "맞아. 그래서 아도니스한테 기회를 줘 보는 게 어떻겠냐고 「살짝」 설득을 했었어.",
  ui_story_5040_50401501_99_dialog_content = "설마 영매한테 그랬던 것처럼 아도니스의 부모님을 협박하신 건 아니죠?",
  ui_story_5040_50401501_100_dialog_content = "아이테르 군은 날 그런 사람이라고 생각하는 거니?",
  ui_story_5040_50401501_101_dialog_content = "그, 그건 아니고요...",
  ui_story_5040_50401501_102_dialog_content = "설득이라는 건 사람에 따라 다른 기술과 교섭 방법을 사용해야 해.",
  ui_story_5040_50401501_103_dialog_content = "아도니스의 부모님은 소중한 가족에 대한 일이니까 예민해지셨을 뿐이지,\n원래부터 앞뒤가 꽉 막힌 분들은 아니야.",
  ui_story_5040_50401501_104_dialog_content = "그래서 문제점을 짚어 드리니까, 바로 그게 잘못된 행동이었단 걸 이해하셨어.",
  ui_story_5040_50401501_105_dialog_content = "그런 부모님이 있다는 것도 정말 부럽네.",
  ui_story_5040_50401501_106_dialog_content = "알고 보니 예리아 씨가 뒤에서 고생을 많이 하셨네요!",
  ui_story_5040_50401501_107_dialog_content = "그냥 내키는 대로 살짝 도와줬을 뿐이야.\n원거리 연애를 하던 커플이 마지막에 어떤 결말을 맞을지 궁금했거든.",
  ui_story_5040_50401501_108_dialog_content = "이제 보니 나쁘지 않은 것 같네.",
  ui_story_5040_50401501_109_dialog_content = "보세요! 왔어요!",
  ui_story_5040_50401501_110_dialog_content = "아도니스 씨랑 타라 씨예요!",
  ui_story_5040_50401501_111_dialog_content = "둘 다 예복으로 갈아입었네!",
  ui_story_5040_50401501_112_dialog_content = "타라 씨는 정말 예쁘고, 아도니스 씨는 옷 하나 갈아입었을 뿐인데 갑자기 멋있어졌는데요?!",
  ui_story_5040_50401501_113_dialog_content = "타라, 아도니스, 결혼 축하해.",
  ui_story_5040_50401501_114_dialog_content = "결혼 축하드려요!",
  ui_story_5040_50401501_115_dialog_content = "결혼 축하해!",
  ui_story_5040_50401501_116_dialog_content = "감사합니다!",
  ui_story_5040_50401501_117_dialog_content = "다들 고마워. 오래 기다리게 해서 미안해!",
  ui_story_5040_50401501_118_dialog_content = "결혼식 입회인으로 쿠리어를 둘이나 초대할 수 있다니,\n아마 우리야말로 이 아스트라 대륙에서 가장 행복한 커플일 거야!",
  ui_story_5040_50401501_119_dialog_content = "자, 그럼 내가 이 결혼의 입회인이 돼 줄게.",
  ui_story_5040_50401501_120_dialog_content = "신부 타라 양은 신랑 아도니스 군을 남편으로 맞이하겠습니까?",
  ui_story_5040_50401501_121_dialog_content = "기쁠 때나, 슬플 때나, 가난할 때나, 풍족할 때나, 그 어떤 역경이 찾아 온다 하더라도...",
  ui_story_5040_50401501_122_dialog_content = "아도니스 군을 아끼고, 사랑하고, 존중하고, 이해하며,\n검은 머리가 파뿌리가 될 때까지 서로 사랑하겠습니까?",
  ui_story_5040_50401501_123_dialog_content = "네!",
  ui_story_5040_50401501_124_dialog_content = "신랑 아도니스 군은 신부 타라 양을 신부로 맞이하겠습니까?",
  ui_story_5040_50401501_125_dialog_content = "기쁠 때나, 슬플 때나, 가난할 때나, 풍족할 때나, 그 어떤 역경이 찾아 온다 하더라도...",
  ui_story_5040_50401501_126_dialog_content = "타라 양을 아끼고, 사랑하고, 존중하고, 이해하며,\n검은 머리가 파뿌리가 될 때까지 서로 사랑하겠습니까?",
  ui_story_5040_50401501_127_dialog_content = "네!",
  ui_story_5040_50401501_128_dialog_content = "그럼 이제, 머나먼 거리를 극복하고, 수없이 많은 어려움을 이겨내\n드디어 마주하게 된 두 아기새는...",
  ui_story_5040_50401501_129_dialog_content = "서로 반지를 교환해 주세요.",
  ui_story_5040_50401501_130_dialog_content = "휴... 결혼식이 드디어 끝났어!",
  ui_story_5040_50401501_131_dialog_content = "드디어 이 드레스를 벗고 좀 편한 옷으로 갈아입을 수 있겠네!",
  ui_story_5040_50401501_132_dialog_content = "드레스가 마음에 안 들었어?",
  ui_story_5040_50401501_133_dialog_content = "당연히 마음에 들지. 우리 둘이 같이 고른 거잖아!",
  ui_story_5040_50401501_134_dialog_content = "근데 솔직히 무거워도 너~무 무거워! 입고 있으면 걷기도 힘들다니까!",
  ui_story_5040_50401501_135_dialog_content = "네가 내 손을 잡고 단상으로 올라갈 땐 몇 번이나 치맛자락을 밟고 넘어질 뻔했잖아.",
  ui_story_5040_50401501_136_dialog_content = "하하하, 사실 나도 네가 움직이기 불편해하는 것 같았어.\n그렇게 큰 드레스를 입으니까, 뭔가 좀 어색하더라고.",
  ui_story_5040_50401501_137_dialog_content = "역시 타라 네가 좋아하는 옷을 입고, 네가 좋아하는 모습으로 있는 게 제일 좋은 것 같아!",
  ui_story_5040_50401501_138_dialog_content = "근데 아도니스 넌 턱시도가 꽤 잘 어울리던데? 하나도 안 어색했어.",
  ui_story_5040_50401501_139_dialog_content = "나도 좀 신기하네.\n북방의 아기새들이 평소에 입는 옷들은 그런 턱시도와 전혀 다른 스타일이던데.",
  ui_story_5040_50401501_140_dialog_content = "어떻게 그렇게 자연스러웠을까?",
  ui_story_5040_50401501_141_dialog_content = "크흠, 사실...",
  ui_story_5040_50401501_142_dialog_content = "사실 아도니스는 이 결혼식을 위해 계속 몰래 준비를 해 왔습니다.",
  ui_story_5040_50401501_143_dialog_content = "아버지, 어머니?!",
  ui_story_5040_50401501_144_dialog_content = "종종 우리가 잠든 밤늦은 시간에 혼자 몰래 턱시도로 갈아입고,\n거울 앞에서 결혼식 연습을 하더군요.",
  ui_story_5040_50401501_145_dialog_content = "이 아이는 이번 결혼식을 굉장히 중요하게 생각했어요.\n타라한테 가장 아름다운 기억을 만들어 주고 싶어 했거든요.",
  ui_story_5040_50401501_146_dialog_content = "그래도 너무 부스럭대고 시끄러워서, 우리도 매번 자다가 깼었지요.",
  ui_story_5040_50401501_147_dialog_content = "두 분... 다 알고 계셨던 거예요?",
  ui_story_5040_50401501_148_dialog_content = "당연하지.",
  ui_story_5040_50401501_149_dialog_content = "우린 네 결혼을 반대하는 게 아니야.\n결혼을 하는 것도, 그 상대가 누구인지도, 모두 네 자유란다.",
  ui_story_5040_50401501_150_dialog_content = "우리가 반대했던 건 네가 제대로 된 마음의 준비도 없이,\n순간의 충동만으로 사랑의 도피를 하려고 했던 거란다.",
  ui_story_5040_50401501_151_dialog_content = "바깥세상이 어떤 곳인지 제대로 알지도 못하는 데다가,\n그런 웃기지도 않는 마법약의 힘을 빌려서야 용기를 낼 수 있는 녀석이 말이야.",
  ui_story_5040_50401501_152_dialog_content = "그런 널 내버려 두는 건 부모의 책임을 저버리는 게 아니고 뭐겠냐!",
  ui_story_5040_50401501_153_dialog_content = "너희 아버지 말이 맞아. 만약 네가 혹시라도 나중에 바깥 생활이 싫어져서,\n북방을 떠난 걸 후회라도 한다면...",
  ui_story_5040_50401501_154_dialog_content = "그땐 타라한테 원망의 화살을 돌릴지도 모르는 일이잖니.",
  ui_story_5040_50401501_155_dialog_content = "그렇게 되면 너는 너 자신한테도, 그리고 타라한테도 무책임한 짓을 하게 되는 거야.",
  ui_story_5040_50401501_156_dialog_content = "아버지, 어머니... 죄송해요, 제가 너무 이기적이었어요...",
  ui_story_5040_50401501_157_dialog_content = "하지만 이제 전 바깥세상을 제대로 잘 알고 있어요.\n그리고 그렇게 이해하고 나서도 여전히 타라랑 결혼하고 싶어요.",
  ui_story_5040_50401501_158_dialog_content = "그래. 우리도 네가 달라졌단 걸 느꼈어. 그래서 너희 결혼을 응원해 주기로 했단다.",
  ui_story_5040_50401501_159_dialog_content = "결혼 축하한다. 앞으로 행복하게 살아라.",
  ui_story_5040_50401501_160_dialog_content = "이제부터 이곳은 우리만이 아니라, 타라의 집이 될 거다.",
  ui_story_5040_50401501_161_dialog_content = "앞으로도 너흰 아스트라 대륙 곳곳을 돌아다니겠지.\n그래도 너희에겐 언제나 너흴 환영해 주는 북방이라는 집이 있다는 걸 기억해 주렴.",
  ui_story_5040_50401501_162_dialog_content = "아버지, 어머니... 정말 감사해요!",
  ui_story_5040_50401501_163_dialog_content = "그럼 이제부터 우린 한 가족인 거네요!",
  ui_story_5040_50401501_164_dialog_content = "<color=#e8d9bb>이틀 뒤, 스카이워커호</color>",
  ui_story_5040_50401501_165_dialog_content = "(다녀오는 데 이렇게 오래 걸릴 줄이야...)",
  ui_story_5040_50401501_166_dialog_content = "(사람을 레디젤 사막에서 북방까지 데려다주면 끝나는 일인 줄 알았는데,\n결국엔 온 아스트라 대륙을 몇 번이나 왔다 갔다 했잖아!)",
  ui_story_5040_50401501_167_dialog_content = "(그래도 바이스랑 카렌 휴가가 끝나기 전에 돌아올 수 있어서 다행이야.\n나로세르가 준 보수라면 턴테이블을 사기에도 충분하고.)",
  ui_story_5040_50401501_168_dialog_content = "(평소엔 두 사람한테 계속 도움을 받아 왔으니까,\n이번엔 내 힘으로 두 사람을 위해 깜짝 선물을 준비하고 싶어.)",
  ui_story_5040_50401501_169_dialog_content = "PlayerName, 우리 왔어!",
  ui_story_5040_50401501_170_dialog_content = "관월제 관련 업무는 작년과 마찬가지로 많았지만,\n올해도 다행히 별 탈 없이 조용히 지나갈 수 있었어.",
  ui_story_5040_50401501_171_dialog_content = "우리가 없는 동안 어떻게 지냈어?",
  ui_story_5040_50401501_172_dialog_content = "평소랑 똑같았어.",
  ui_story_5040_50401501_173_dialog_content = "스카이워커를 타고 여기저기 다니면서 각지의 명절 분위기도 즐겼어.",
  ui_story_5040_50401501_174_dialog_content = "겸사겸사 쿠리어 길드의 의뢰도 받아서 용돈도 좀 벌었고.",
  ui_story_5040_50401501_175_dialog_content = "아! 나도 얘기 들었어! 유라 씨가 나한테 왜 너랑 같이 안 다니냐고 물어보더라고.",
  ui_story_5040_50401501_176_dialog_content = "백야성 경비병들도 네가 쿠리어 길드를 돕는 모습을 봤다고 했었어.\n수고가 많았겠네.",
  ui_story_5040_50401501_177_dialog_content = "별거 아니었어, 수고는 뭘.",
  ui_story_5040_50401501_178_dialog_content = "엄청 바빴어.",
  ui_story_5040_50401501_179_dialog_content = "쿠리어 길드의 의뢰를 받아서 용돈을 좀 벌었거든.",
  ui_story_5040_50401501_180_dialog_content = "원래는 얼른 갔다 오려고 했는데, 결국엔 시간이 엄청 오래 걸렸지 뭐야!",
  ui_story_5040_50401501_181_dialog_content = "나도 얘기 들었어. 백야성뿐만 아니라 일루미나에도 갔다 왔었지?",
  ui_story_5040_50401501_182_dialog_content = "레디젤 사막이랑 북방에도 갔다던 것 같은데? 이번엔 진짜 멀리까지 갔다 왔네!",
  ui_story_5040_50401501_183_dialog_content = "잠깐만, 너희가 왜 내가 어디 갔었는지 다 알고 있는 거야?!",
  ui_story_5040_50401501_184_dialog_content = "스카이워커호는 엄청 눈에 띄잖아. 그러니까 어딜 가든 모두한테 주목을 받는다구!",
  ui_story_5040_50401501_185_dialog_content = "하긴 그렇네...",
  ui_story_5040_50401501_186_dialog_content = "아무튼 이번에 의뢰로 번 돈으로 두 사람한테 줄 선물을 준비했어!",
  ui_story_5040_50401501_187_dialog_content = "짜자잔!",
  ui_story_5040_50401501_188_dialog_content = "턴테이블이네?!",
  ui_story_5040_50401501_189_dialog_content = "내 기억이 맞다면 가격이 상당히 비쌌던 것 같은데.",
  ui_story_5040_50401501_190_dialog_content = "그날 움브라톤에서 쇼핑할 때, 너희가 진열장 앞에서\n이 턴테이블을 한참 뚫어져라 쳐다보는 걸 봤거든.",
  ui_story_5040_50401501_191_dialog_content = "그래서 이걸 사면 너희가 좋아할 것 같아서 몰래 가격을 봤는데,\n솔직히 너무 비싸서 깜짝 놀랐다니까.",
  ui_story_5040_50401501_192_dialog_content = "근데 지금까지 계속 두 사람한텐 도움만 받았는데,\n내가 고마움을 표현한 적은 별로 없는 것 같아서...",
  ui_story_5040_50401501_193_dialog_content = "그래서 이 턴테이블을 사서 선물하기로 한 거야!",
  ui_story_5040_50401501_194_dialog_content = "그리고 그동안 너희 모르게 의뢰를 잔뜩 받았고, 이번에 드디어 이걸 살만큼 돈을 모은 거지!",
  ui_story_5040_50401501_195_dialog_content = "PlayerName...",
  ui_story_5040_50401501_196_dialog_content = "사실 우리가 그때 이 턴테이블을 보고 있었던 건 다른 이유가 있었어...",
  ui_story_5040_50401501_197_dialog_content = "항상 우리랑 함께 다녔던 PlayerName한테 선물을 하나 주자고\n전에 카렌이랑 상의를 좀 했었거든.",
  ui_story_5040_50401501_198_dialog_content = "그러다 움브라톤에서 이 턴테이블을 보게 됐는데, 보니까 이게 딱 좋겠다고 생각했어.",
  ui_story_5040_50401501_199_dialog_content = "아이테르 일족은 음악을 좋아하잖아.\n좋은 턴테이블로 듣는 음악은 더 아름답게 들릴 테고 말이야.",
  ui_story_5040_50401501_200_dialog_content = "그래서 그때 우린 돈을 모아서 너한테 이 턴테이블을 선물해 주자고 했었어.",
  ui_story_5040_50401501_201_dialog_content = "그래서 이번 관월제엔 나도, 바이스도 돌아가서 일을 했던 거야.",
  ui_story_5040_50401501_202_dialog_content = "돌아가서 일을 했다니... 쉬러 간 게 아니었던 거야?!",
  ui_story_5040_50401501_203_dialog_content = "응... 나랑 카렌 둘 다 비밀로 하기로 해서 너한테 말을 안 했던 건데...",
  ui_story_5040_50401501_204_dialog_content = "그런데 정작 우리가 움브라톤에 갔더니 턴테이블이 팔린 뒤였어.",
  ui_story_5040_50401501_205_dialog_content = "그래서 하는 수 없이 움브라톤에서 디저트와 새로 나온 책들을 사서 돌아왔어.\n이런 것들로라도 함께 즐거움을 나누면 좋으니까.",
  ui_story_5040_50401501_206_dialog_content = "그럼 너희가 이 턴테이블을 가지고 싶었던 게 아니란 말이야?!",
  ui_story_5040_50401501_207_dialog_content = "음...",
  ui_story_5040_50401501_208_dialog_content = "괜찮아! 우여곡절이 있긴 했지만, 어쨌든 결국 턴테이블을 샀잖아!",
  ui_story_5040_50401501_209_dialog_content = "그리고 함께 즐길 디저트와 책도 있어.",
  ui_story_5040_50401501_210_dialog_content = "응... 그렇네!",
  ui_story_5040_50401501_211_dialog_content = "그럼 이제 같이 즐기는 일만 남았네!"
